/* GRAMMAR — grammar points by lesson: {"<lesson>": [{id, t, e, pat, tgt, alt, s:[{zh, en, py}], …}]}. One line of JSON: the tools read and rewrite it whole. */
const GRAMMAR = {"1":[{"id":"g1-1","t":"Questions with 嗎","e":"Add 嗎 to the end of any statement to make a yes/no question — word order never changes.","tgt":["嗎"],"alt":["呢","吧","啊"],"s":[{"zh":"你是李小姐嗎？","en":"Are you Miss Li?","py":"nǐ shì lǐ xiǎo jiě ma?"},{"zh":"這是咖啡嗎？","en":"Is this coffee?","py":"zhè shì kā fēi ma?"},{"zh":"你要喝茶嗎？","en":"Do you want to drink tea?","py":"nǐ yào hē chá ma?"},{"zh":"他是美國人嗎？","en":"Is he American?","py":"tā shì měi guó rén ma?"},{"zh":"請問，你們學校附近有好吃的牛肉麵嗎？","en":"Excuse me, is there good beef noodle soup near your school?","py":"qǐng wèn, nǐ men xué xiào fù jìn yǒu hǎo chī de niú ròu miàn ma?"},{"zh":"你朋友也要跟我們一起去看電影嗎？","en":"Is your friend also coming to the movies with us?","py":"nǐ péng yǒu yě yào gēn wǒ men yì qǐ qù kàn diàn yǐng ma?"}],"cy":"Turn any statement about yourself into a yes/no question with 嗎."},{"id":"g1-2","t":"姓 and 叫 — Introducing yourself","e":"姓 gives your surname; 叫 gives your full or given name.","tgt":["姓","叫"],"alt":["是","要"],"s":[{"zh":"我姓王。","en":"My surname is Wang.","py":"wǒ xìng wáng."},{"zh":"我叫王開文。","en":"I'm called Wang Kaiwen.","py":"wǒ jiào wáng kāi wén."},{"zh":"請問你姓什麼？","en":"May I ask your surname?","py":"qǐng wèn nǐ xìng shén me?"},{"zh":"他叫李明華。","en":"He is called Li Minghua.","py":"tā jiào lǐ míng huá."},{"zh":"我們的老師姓王，可是我不知道他叫什麼名字。","en":"Our teacher's surname is Wang, but I don't know his full name.","py":"wǒ men de lǎo shī xìng wáng, kě shì wǒ bù zhī dào tā jiào shén me míng zì."},{"zh":"請問你姓什麼？我姓李，叫李明華。","en":"May I ask your surname? Mine is Li — Li Minghua.","py":"qǐng wèn nǐ xìng shén me? wǒ xìng lǐ, jiào lǐ míng huá."}],"cy":"Introduce yourself twice: once with 姓, once with 叫."},{"id":"g1-3","t":"Bounce-back 呢","e":"呢 bounces a question back: 我很好，你呢？","tgt":["呢"],"alt":["嗎","吧","啊"],"s":[{"zh":"我很好，你呢？","en":"I'm good, and you?","py":"wǒ hěn hǎo, nǐ ne?"},{"zh":"我喜歡喝茶，你呢？","en":"I like drinking tea, and you?","py":"wǒ xǐ huān hē chá, nǐ ne?"},{"zh":"我是美國人，你呢？","en":"I'm American, and you?","py":"wǒ shì měi guó rén, nǐ ne?"},{"zh":"我很喜歡臺灣的烏龍茶，你呢？你喜歡喝什麼？","en":"I really like Taiwanese oolong — and you? What do you like to drink?","py":"wǒ hěn xǐ huān tái wān de wū lóng chá, nǐ ne? nǐ xǐ huān hē shén me?"},{"zh":"我週末想去游泳，你呢？","en":"I want to go swimming this weekend — how about you?","py":"wǒ zhōu mò xiǎng qù yóu yǒng, nǐ ne?"}],"cy":"State a preference of yours, then bounce it back with 呢."},{"id":"g1-4","t":"Negation with 不","e":"Place 不 directly before the verb to negate it.","tgt":["不"],"alt":["沒","很","都"],"s":[{"zh":"我不喜歡咖啡。","en":"I don't like coffee.","py":"wǒ bù xǐ huān kā fēi."},{"zh":"他不是日本人。","en":"He isn't Japanese.","py":"tā bú shì rì běn rén."},{"zh":"我不喝烏龍茶。","en":"I don't drink oolong tea.","py":"wǒ bù hē wū lóng chá."},{"zh":"他不是臺灣人，可是他很喜歡臺灣菜。","en":"He isn't Taiwanese, but he loves Taiwanese food.","py":"tā bú shì tái wān rén, kě shì tā hěn xǐ huān tái wān cài."},{"zh":"我不想喝咖啡，我要喝熱茶。","en":"I don't want coffee; I'll have hot tea.","py":"wǒ bù xiǎng hē kā fēi, wǒ yào hē rè chá."}],"cy":"Say two things you don't do or don't like, using 不."}],"2":[{"id":"g2-1","t":"Possessive 的","e":"的 links possessor and noun: 我的家人 my family; also links descriptions: 漂亮的房子.","tgt":["的"],"alt":["得","了","都"],"s":[{"zh":"這是我的家人。","en":"This is my family.","py":"zhè shì wǒ de jiā rén."},{"zh":"那是老師的書。","en":"That is the teacher's book.","py":"nà shì lǎo shī de shū."},{"zh":"她的照片很好看。","en":"Her photos are good-looking.","py":"tā de zhào piān hěn hǎo kàn."},{"zh":"他們的房子很漂亮。","en":"Their house is beautiful.","py":"tā men de fáng zi hěn piào liàng."},{"zh":"這是我媽媽的照片，她的房子在山上。","en":"This is my mom's photo — her house is in the mountains.","py":"zhè shì wǒ mā mā de zhào piān, tā de fáng zi zài shān shàng."},{"zh":"老師的書都很有意思，你可以看看。","en":"The teacher's books are all interesting — take a look.","py":"lǎo shī de shū dōu hěn yǒu yì si, nǐ kě yǐ kàn kàn."}],"cy":"Describe two things you own using 的."},{"id":"g2-2","t":"Measure words 個 and 張","e":"Numbers need a measure word: 個 for people/general, 張 for flat things (photos, paper).","tgt":["個","張"],"alt":["杯","家","支"],"s":[{"zh":"我有兩個姐姐。","en":"I have two older sisters.","py":"wǒ yǒu liǎng gè jiě jiě."},{"zh":"他有三個哥哥。","en":"He has three older brothers.","py":"tā yǒu sān gè gē gē."},{"zh":"這是一張照片。","en":"This is one photo.","py":"zhè shì yī zhāng zhào piān."},{"zh":"我要五張紙。","en":"I want five sheets of paper.","py":"wǒ yào wǔ zhāng zhǐ."},{"zh":"我家有五個人：爸爸、媽媽、兩個哥哥和我。","en":"There are five people in my family: dad, mom, two older brothers, and me.","py":"wǒ jiā yǒu wǔ gè rén ： bà bà, mā mā, liǎng gè gē gē hé wǒ."},{"zh":"這三張照片都是在學校前面照的。","en":"All three of these photos were taken in front of the school.","py":"zhè sān zhāng zhào piān dōu shì zài xué xiào qián miàn zhào de."}],"cy":"Count your family members with 個 and something flat with 張."},{"id":"g2-3","t":"有 and 沒有","e":"有 = to have / there is. Negate 有 with 沒, never 不.","tgt":["有","沒有"],"alt":["是","不是"],"s":[{"zh":"我有兩個姐姐。","en":"I have two older sisters.","py":"wǒ yǒu liǎng gè jiě jiě."},{"zh":"你有兄弟嗎？","en":"Do you have brothers?","py":"nǐ yǒu xiōng dì ma?"},{"zh":"我沒有妹妹。","en":"I don't have a younger sister.","py":"wǒ méi yǒu mèi mèi."},{"zh":"這裡有很多照片。","en":"There are many photos here.","py":"zhè lǐ yǒu hěn duō zhào piān."},{"zh":"我們學校有很多學生，可是沒有游泳池。","en":"Our school has lots of students but no swimming pool.","py":"wǒ men xué xiào yǒu hěn duō xué shēng, kě shì méi yǒu yóu yǒng chí."},{"zh":"你有沒有你家人的照片？給我看看。","en":"Do you have photos of your family? Show me.","py":"nǐ yǒu méi yǒu nǐ jiā rén de zhào piān? gěi wǒ kàn kàn."}],"cy":"Say one thing you have (有) and one you don't (沒有)."},{"id":"g2-4","t":"都 — all / both","e":"都 goes AFTER the subject and BEFORE the verb: 我們都是學生.","tgt":["都"],"alt":["也","很","常"],"s":[{"zh":"我們都是學生。","en":"We are all students.","py":"wǒ men dōu shì xué shēng."},{"zh":"他們都很好看。","en":"They are all good-looking.","py":"tā men dōu hěn hǎo kàn."},{"zh":"照片都很漂亮。","en":"The photos are all beautiful.","py":"zhào piān dōu hěn piào liàng."},{"zh":"我的兄弟姐妹都不住在臺灣。","en":"None of my siblings live in Taiwan.","py":"wǒ de xiōng dì jiě mèi dōu bú zhù zài tái wān."},{"zh":"他們家的人都很喜歡照相。","en":"Everyone in their family loves taking photos.","py":"tā men jiā de rén dōu hěn xǐ huān zhào xiàng."}],"cy":"Say something true of your whole family/class using 都."},{"id":"g2-5","t":"幾 — how many","e":"幾 asks small quantities and always needs a measure word: 幾個, 幾張.","tgt":["幾"],"alt":["多少","什麼","誰"],"s":[{"zh":"你有幾個兄弟？","en":"How many brothers do you have?","py":"nǐ yǒu jǐ gè xiōng dì?"},{"zh":"你家有幾個人？","en":"How many people are in your family?","py":"nǐ jiā yǒu jǐ gè rén?"},{"zh":"這是幾張照片？","en":"How many photos is this?","py":"zhè shì jǐ zhāng zhào piān?"},{"zh":"你們家有幾個人？都住在哪裡？","en":"How many people are in your family? Where do they all live?","py":"nǐ men jiā yǒu jǐ gè rén? dōu zhù zài nǎ lǐ?"},{"zh":"請問，這個字有幾個意思？","en":"Excuse me, how many meanings does this character have?","py":"qǐng wèn, zhè ge zì yǒu jǐ gè yì si?"}],"cy":"Ask someone a 幾 + measure word question about their family."},{"id":"g2-6","t":"兩 vs 二","e":"Counting things: 兩 + measure word (兩個人). Counting numbers: 二 (一、二、三).","tgt":["兩"],"alt":["二","幾","個"],"s":[{"zh":"我有兩個姐姐。","en":"I have two older sisters.","py":"wǒ yǒu liǎng gè jiě jiě."},{"zh":"他買了兩張照片。","en":"He bought two photos.","py":"tā mǎi le liǎng zhāng zhào piān."},{"zh":"我們家有兩個哥哥。","en":"Our family has two older brothers.","py":"wǒ men jiā yǒu liǎng gè gē gē."},{"zh":"我要兩杯咖啡，一杯大的，一杯小的。","en":"I'd like two coffees — one large, one small.","py":"wǒ yào liǎng bēi kā fēi, yī bēi dà de, yī bēi xiǎo de."},{"zh":"我們兩個人常常一起吃晚飯。","en":"The two of us often eat dinner together.","py":"wǒ men liǎng gè rén cháng cháng yì qǐ chī wǎn fàn."}],"cy":"Mention two of something you have, using 兩 + the right measure word."}],"3":[{"id":"g3-1","t":"打 vs 踢 — playing sports","e":"打 for hand sports (打籃球/棒球/網球); 踢 for foot sports (踢足球).","tgt":["打","踢"],"alt":["做","玩"],"s":[{"zh":"我常打籃球。","en":"I often play basketball.","py":"wǒ cháng dǎ lán qiú."},{"zh":"他喜歡打網球。","en":"He likes playing tennis.","py":"tā xǐ huān dǎ wǎng qiú."},{"zh":"我們週末踢足球。","en":"We play soccer on weekends.","py":"wǒ men zhōu mò tī zú qiú."},{"zh":"我哥哥常打棒球，我妹妹喜歡踢足球。","en":"My older brother often plays baseball; my younger sister likes soccer.","py":"wǒ gē gē cháng dǎ bàng qiú, wǒ mèi mèi xǐ huān tī zú qiú."},{"zh":"你想打網球還是打籃球？我都可以。","en":"Tennis or basketball? Either works for me.","py":"nǐ xiǎng dǎ wǎng qiú hái shì dǎ lán qiú? wǒ dōu kě yǐ."}],"cy":"Say which sports you play, choosing 打 or 踢 correctly."},{"id":"g3-2","t":"想 — want / think","e":"想 + verb = want to; 想 + clause = think; 想 + person = miss.","tgt":["想"],"alt":["要","會","喜歡"],"s":[{"zh":"我想去看電影。","en":"I want to go watch a movie.","py":"wǒ xiǎng qù kàn diàn yǐng."},{"zh":"你想吃什麼？","en":"What do you want to eat?","py":"nǐ xiǎng chī shén me?"},{"zh":"我想他是老師。","en":"I think he is a teacher.","py":"wǒ xiǎng tā shì lǎo shī."},{"zh":"週末我想在家聽音樂，不想運動。","en":"This weekend I want to stay home listening to music, not exercise.","py":"zhōu mò wǒ xiǎng zài jiā tīng yīn yuè, bù xiǎng yùn dòng."},{"zh":"我想去臺灣學中文，也想吃很多小吃。","en":"I want to go to Taiwan to study Chinese — and eat lots of street food.","py":"wǒ xiǎng qù tái wān xué zhōng wén, yě xiǎng chī hěn duō xiǎo chī."}],"cy":"Say two things you want to do this weekend with 想."},{"id":"g3-3","t":"還是 — or (in questions)","e":"還是 offers a choice in questions. In statements use 或是.","tgt":["還是"],"alt":["或是","也","和"],"s":[{"zh":"你想看電影還是聽音樂？","en":"Do you want to watch a movie or listen to music?","py":"nǐ xiǎng kàn diàn yǐng hái shì tīng yīn yuè?"},{"zh":"你要喝茶還是咖啡？","en":"Do you want tea or coffee?","py":"nǐ yào hē chá hái shì kā fēi?"},{"zh":"我們今天去還是明天去？","en":"Do we go today or tomorrow?","py":"wǒ men jīn tiān qù hái shì míng tiān qù?"},{"zh":"我們早上去游泳還是下午去打網球？","en":"Shall we swim in the morning or play tennis in the afternoon?","py":"wǒ men zǎo shàng qù yóu yǒng hái shì xià wǔ qù dǎ wǎng qiú?"},{"zh":"你覺得看電影好還是去KTV唱歌好？","en":"Do you think a movie is better, or singing at KTV?","py":"nǐ jué de kàn diàn yǐng hǎo hái shì qù K T V chàng gē hǎo?"}],"cy":"Ask a friend an A-還是-B question about the weekend."},{"id":"g3-4","t":"Suggestion 吧","e":"吧 softens a sentence into a suggestion (我們去吧) or a guess (你是美國人吧？).","tgt":["吧"],"alt":["嗎","呢","啊"],"s":[{"zh":"我們去看電影吧。","en":"Let's go watch a movie.","py":"wǒ men qù kàn diàn yǐng ba."},{"zh":"吃晚飯吧。","en":"Let's eat dinner.","py":"chī wǎn fàn ba."},{"zh":"你是美國人吧？","en":"You're American, right?","py":"nǐ shì měi guó rén ba?"},{"zh":"今天我們一起去看電影吧，明天再運動。","en":"Let's go see a movie today — we can exercise tomorrow.","py":"jīn tiān wǒ men yì qǐ qù kàn diàn yǐng ba, míng tiān zài yùn dòng."},{"zh":"我們晚上七點在學校前面見面吧。","en":"Let's meet at seven in front of the school.","py":"wǒ men wǎn shàng qī diǎn zài xué xiào qián miàn jiàn miàn ba."}],"cy":"Make two suggestions to a friend using 吧."},{"id":"g3-5","t":"好不好 / 怎麼樣","e":"Tag onto a suggestion to seek agreement: …，好不好？ …，怎麼樣？","tgt":["好不好","怎麼樣"],"alt":["是不是","對不對"],"s":[{"zh":"我們明天去游泳，好不好？","en":"Let's go swimming tomorrow, okay?","py":"wǒ men míng tiān qù yóu yǒng, hǎo bù hǎo?"},{"zh":"今天晚上看電影，怎麼樣？","en":"How about watching a movie tonight?","py":"jīn tiān wǎn shàng kàn diàn yǐng, zěn me yàng?"},{"zh":"我們先吃晚飯，再去看電影，好不好？","en":"Dinner first, then the movie — sound good?","py":"wǒ men xiān chī wǎn fàn, zài qù kàn diàn yǐng, hǎo bù hǎo?"},{"zh":"星期六早上去山上走走，怎麼樣？","en":"How about a walk in the mountains Saturday morning?","py":"xīng qī liù zǎo shàng qù shān shàng zǒu zǒu, zěn me yàng?"}],"cy":"Propose a plan and tag it with 好不好 or 怎麼樣."},{"id":"g3-6","t":"也 — also","e":"也 sits after the subject, before the verb — never at the end.","tgt":["也"],"alt":["都","還","again"],"s":[{"zh":"我喜歡籃球，我也喜歡足球。","en":"I like basketball, and I also like soccer.","py":"wǒ xǐ huān lán qiú, wǒ yě xǐ huān zú qiú."},{"zh":"他也想去。","en":"He also wants to go.","py":"tā yě xiǎng qù."},{"zh":"我也常游泳。","en":"I also often swim.","py":"wǒ yě cháng yóu yǒng."},{"zh":"她會說中文，也會說一點日文。","en":"She speaks Chinese, and a little Japanese too.","py":"tā huì shuō zhōng wén, yě huì shuō yì diǎn rì wén."},{"zh":"我常游泳，我朋友也常跟我一起去。","en":"I swim often, and my friend often comes along.","py":"wǒ cháng yóu yǒng, wǒ péng yǒu yě cháng gēn wǒ yì qǐ qù."}],"cy":"Agree with something a friend likes using 也."},{"id":"g3-7","t":"常 — often","e":"常 before the verb: 我常運動.","tgt":["常"],"alt":["都","也","很"],"s":[{"zh":"我常運動。","en":"I often exercise.","py":"wǒ cháng yùn dòng."},{"zh":"你常看電影嗎？","en":"Do you often watch movies?","py":"nǐ cháng kàn diàn yǐng ma?"},{"zh":"我們常一起吃晚飯。","en":"We often eat dinner together.","py":"wǒ men cháng yì qǐ chī wǎn fàn."},{"zh":"我們常在學校旁邊的餐廳吃飯。","en":"We often eat at the restaurant next to school.","py":"wǒ men cháng zài xué xiào páng biān de cān tīng chī fàn."},{"zh":"你常聽什麼音樂？可以教我嗎？","en":"What music do you often listen to? Can you show me?","py":"nǐ cháng tīng shén me yīn yuè? kě yǐ jiào wǒ ma?"}],"cy":"Say two things you often do with 常."}],"4":[{"id":"g4-1","t":"多少 vs 幾","e":"多少 for big/unknown amounts & prices (no measure word needed); 幾 for small counts (needs measure word).","tgt":["多少","幾"],"alt":["什麼","怎麼"],"s":[{"zh":"這個多少錢？","en":"How much is this?","py":"zhè ge duō shǎo qián?"},{"zh":"一共多少錢？","en":"How much altogether?","py":"yī gòng duō shǎo qián?"},{"zh":"你要幾杯咖啡？","en":"How many cups of coffee do you want?","py":"nǐ yào jǐ bēi kā fēi?"},{"zh":"你有幾個姐姐？","en":"How many older sisters do you have?","py":"nǐ yǒu jǐ gè jiě jiě?"},{"zh":"老闆，這種包子一個多少錢？我要買五個。","en":"Boss, how much is this kind of bun? I'll take five.","py":"lǎo bǎn, zhè zhǒng bāo zi yí gè duō shǎo qián? wǒ yào mǎi wǔ gè."},{"zh":"你們學校有多少學生？有幾個美國人？","en":"How many students does your school have? How many Americans?","py":"nǐ men xué xiào yǒu duō shǎo xué shēng? yǒu jǐ gè měi guó rén?"}],"cy":"Ask a shop owner the price of something with 多少錢."},{"id":"g4-2","t":"太…了 — too…","e":"太 + adjective + 了: the 了 is required — 太貴 alone sounds unfinished.","tgt":["太","了"],"alt":["很","真","最"],"s":[{"zh":"這個手機太貴了。","en":"This phone is too expensive.","py":"zhè ge shǒu jī tài guì le."},{"zh":"那個包子太大了。","en":"That steamed bun is too big.","py":"nà ge bāo zi tài dà le."},{"zh":"我的手機太舊了。","en":"My phone is too old.","py":"wǒ de shǒu jī tài jiù le."},{"zh":"這家店的東西太貴了，我們去別家看看吧。","en":"This shop is too expensive — let's check another one.","py":"zhè jiā diàn de dōng xī tài guì le, wǒ men qù bié jiā kàn kàn ba."},{"zh":"今天太熱了，我想喝一杯大杯的冰咖啡。","en":"It's too hot today — I want a large iced coffee.","py":"jīn tiān tài rè le, wǒ xiǎng hē yī bēi dà bēi de bīng kā fēi."}],"cy":"Complain about two things with 太…了."},{"id":"g4-3","t":"能 vs 可以","e":"能 = ability/possibility; 可以 = permission/acceptability.","tgt":["能","可以"],"alt":["會","要"],"s":[{"zh":"這支手機能上網。","en":"This phone can go online.","py":"zhè zhī shǒu jī néng shàng wǎng."},{"zh":"你能幫我嗎？","en":"Can you help me?","py":"nǐ néng bāng wǒ ma?"},{"zh":"我可以看看嗎？","en":"May I take a look?","py":"wǒ kě yǐ kàn kàn ma?"},{"zh":"這裡可以內用。","en":"You can dine in here.","py":"zhè lǐ kě yǐ nèi yòng."},{"zh":"這裡不能照相，可是外面可以。","en":"You can't take photos in here, but outside is fine.","py":"zhè lǐ bù néng zhào xiàng, kě shì wài miàn kě yǐ."},{"zh":"我今天不能去上課，你可以幫我問老師嗎？","en":"I can't make class today — could you ask the teacher for me?","py":"wǒ jīn tiān bù néng qù shàng kè, nǐ kě yǐ bāng wǒ wèn lǎo shī ma?"}],"cy":"Ask permission with 可以, then state an ability with 能."},{"id":"g4-4","t":"Measure words 杯 / 支 / 種","e":"杯 cups of drinks; 支 long thin objects (phones, pens); 種 kinds/types.","tgt":["杯","支","種"],"alt":["個","張","家"],"s":[{"zh":"我要一杯咖啡。","en":"I want one cup of coffee.","py":"wǒ yào yī bēi kā fēi."},{"zh":"他買了一支手機。","en":"He bought a cell phone.","py":"tā mǎi le yī zhī shǒu jī."},{"zh":"你們有幾種包子？","en":"How many kinds of steamed buns do you have?","py":"nǐ men yǒu jǐ zhǒng bāo zi?"},{"zh":"我要兩杯大杯的熱咖啡，外帶，謝謝。","en":"Two large hot coffees to go, thanks.","py":"wǒ yào liǎng bēi dà bēi de rè kā fēi, wài dài, xiè xiè."},{"zh":"老闆，這種手機有沒有便宜一點的？","en":"Boss, is there a cheaper version of this kind of phone?","py":"lǎo bǎn, zhè zhǒng shǒu jī yǒu méi yǒu pián yi yì diǎn de?"}],"cy":"Order a drink and ask about types (種) of something."},{"id":"g4-5","t":"為什麼 — why","e":"為什麼 before the verb phrase asks why.","tgt":["為什麼"],"alt":["怎麼","什麼","多少"],"s":[{"zh":"為什麼這麼貴？","en":"Why is it so expensive?","py":"wèi shén me zhè me guì?"},{"zh":"你為什麼要買新手機？","en":"Why do you want to buy a new phone?","py":"nǐ wèi shén me yào mǎi xīn shǒu jī?"},{"zh":"你為什麼不買那支新手機？太貴了嗎？","en":"Why aren't you buying that new phone? Too expensive?","py":"nǐ wèi shén me bù mǎi nà zhī xīn shǒu jī? tài guì le ma?"},{"zh":"為什麼這家店的包子這麼有名？","en":"Why are this shop's buns so famous?","py":"wèi shén me zhè jiā diàn de bāo zi zhè me yǒu míng?"}],"cy":"Ask why something is so expensive / so good with 為什麼."},{"id":"g4-6","t":"了 — change of state","e":"Sentence-final 了 marks a new situation: 包子冷了 the bun has gotten cold.","tgt":["了"],"alt":["的","得","嗎"],"s":[{"zh":"我的手機太舊了。","en":"My phone is too old now.","py":"wǒ de shǒu jī tài jiù le."},{"zh":"包子冷了。","en":"The bun has gotten cold.","py":"bāo zi lěng le."},{"zh":"這支手機不能上網了，我要買新的。","en":"This phone can't get online anymore — I need a new one.","py":"zhè zhī shǒu jī bù néng shàng wǎng le, wǒ yào mǎi xīn de."},{"zh":"包子都冷了，我幫你微波一下吧。","en":"The buns have gone cold — let me microwave them for you.","py":"bāo zi dōu lěng le, wǒ bāng nǐ wēi bō yī xià ba."}],"cy":"Describe something that has changed recently with 了."}],"5":[{"id":"g5-1","t":"最 — superlative","e":"最 + adjective/verb = the most: 最有名, 最喜歡.","tgt":["最"],"alt":["很","太","更"],"s":[{"zh":"這家店最有名。","en":"This shop is the most famous.","py":"zhè jiā diàn zuì yǒu míng."},{"zh":"牛肉麵是最好吃的。","en":"Beef noodle soup is the most delicious.","py":"niú ròu miàn shì zuì hǎo chī de."},{"zh":"我最喜歡小籠包。","en":"I like xiaolongbao the most.","py":"wǒ zuì xǐ huān xiǎo lóng bāo."},{"zh":"這家餐廳的小籠包最有名，每天都有很多人。","en":"This restaurant's xiaolongbao is the most famous — it's packed every day.","py":"zhè jiā cān tīng de xiǎo lóng bāo zuì yǒu míng, měi tiān dōu yǒu hěn duō rén."},{"zh":"我覺得臺灣最好吃的小吃是臭豆腐。","en":"I think Taiwan's best street food is stinky tofu.","py":"wǒ jué de tái wān zuì hǎo chī de xiǎo chī shì chòu dòu fǔ."}],"cy":"Name your favorite Taiwanese food using 最."},{"id":"g5-2","t":"真 vs 很","e":"真 = really! (exclamation, surprise); 很 = neutral 'very'.","tgt":["真","很"],"alt":["太","最"],"s":[{"zh":"這個真好吃！","en":"This is really delicious!","py":"zhè ge zhēn hǎo chī!"},{"zh":"你真會做飯。","en":"You really know how to cook.","py":"nǐ zhēn huì zuò fàn."},{"zh":"這個很好吃。","en":"This is (very) delicious.","py":"zhè ge hěn hǎo chī."},{"zh":"你做的甜點真好吃！你真會做飯！","en":"Your desserts are really delicious — you can really cook!","py":"nǐ zuò de tián diǎn zhēn hǎo chī! nǐ zhēn huì zuò fàn!"},{"zh":"這碗牛肉麵很大，湯也很好喝。","en":"This bowl of beef noodles is big, and the broth is great too.","py":"zhè wǎn niú ròu miàn hěn dà, tāng yě hěn hǎo hē."}],"cy":"React to a meal with 真, then describe it neutrally with 很."},{"id":"g5-3","t":"有一點 — a little (negative)","e":"有一點 + adjective implies mild complaint: 有一點辣 a bit (too) spicy.","tgt":["有一點"],"alt":["一點","很","真"],"s":[{"zh":"這個菜有一點辣。","en":"This dish is a little spicy.","py":"zhè ge cài yǒu yì diǎn là."},{"zh":"湯有一點鹹。","en":"The soup is a little salty.","py":"tāng yǒu yì diǎn xián."},{"zh":"這家店的菜有一點辣，可是真好吃。","en":"This place's food is a little spicy, but really good.","py":"zhè jiā diàn de cài yǒu yì diǎn là, kě shì zhēn hǎo chī."},{"zh":"今天我有一點忙，我們明天見面吧。","en":"I'm a bit busy today — let's meet tomorrow.","py":"jīn tiān wǒ yǒu yì diǎn máng, wǒ men míng tiān jiàn miàn ba."}],"cy":"Politely complain about a dish with 有一點."},{"id":"g5-4","t":"會 — learned ability","e":"會 = can (because you learned it): 我會做飯. Compare 能 (circumstances), 可以 (permission).","tgt":["會"],"alt":["能","可以","要"],"s":[{"zh":"我會做飯。","en":"I can cook.","py":"wǒ huì zuò fàn."},{"zh":"你會說中文嗎？","en":"Can you speak Chinese?","py":"nǐ huì shuō zhōng wén ma?"},{"zh":"她會做小籠包。","en":"She can make xiaolongbao.","py":"tā huì zuò xiǎo lóng bāo."},{"zh":"我會做一點臺灣菜，可是不會做小籠包。","en":"I can cook a little Taiwanese food, but not xiaolongbao.","py":"wǒ huì zuò yì diǎn tái wān cài, kě shì bú huì zuò xiǎo lóng bāo."},{"zh":"你會不會說中文？說得怎麼樣？","en":"Can you speak Chinese? How well?","py":"nǐ huì bú huì shuō zhōng wén? shuō dé zěn me yàng?"}],"cy":"Say two skills you have with 會 and one you don't (不會)."},{"id":"g5-5","t":"可是 and 所以","e":"可是 = but; 所以 = so/therefore.","tgt":["可是","所以"],"alt":["因為","還是"],"s":[{"zh":"我喜歡臭豆腐，可是我朋友不喜歡。","en":"I like stinky tofu, but my friend doesn't.","py":"wǒ xǐ huān chòu dòu fǔ, kě shì wǒ péng yǒu bù xǐ huān."},{"zh":"我怕辣，所以我不吃。","en":"I'm afraid of spicy food, so I don't eat it.","py":"wǒ pà là, suǒ yǐ wǒ bù chī."},{"zh":"這個很好吃，所以我常來。","en":"This is delicious, so I come often.","py":"zhè ge hěn hǎo chī, suǒ yǐ wǒ cháng lái."},{"zh":"我很喜歡吃辣，可是我朋友怕辣，所以我們點了不辣的菜。","en":"I love spicy food, but my friend can't handle it, so we ordered mild dishes.","py":"wǒ hěn xǐ huān chī là, kě shì wǒ péng yǒu pà là, suǒ yǐ wǒ men diǎn le bù là de cài."},{"zh":"這家店很有名，所以我們得早一點去。","en":"This place is famous, so we'd better go early.","py":"zhè jiā diàn hěn yǒu míng, suǒ yǐ wǒ men dé zǎo yì diǎn qù."}],"cy":"Make one sentence with 可是 and one with 所以 about food."},{"id":"g5-6","t":"Measure words 碗 and 家","e":"碗 bowls of food; 家 businesses/shops/restaurants.","tgt":["碗","家"],"alt":["杯","個","張"],"s":[{"zh":"我要一碗牛肉麵。","en":"I want one bowl of beef noodle soup.","py":"wǒ yào yī wǎn niú ròu miàn."},{"zh":"這家店很有名。","en":"This shop is very famous.","py":"zhè jiā diàn hěn yǒu míng."},{"zh":"那家餐廳不錯。","en":"That restaurant is pretty good.","py":"nà jiā cān tīng bù cuò."},{"zh":"我們去那家有名的店，一人點一碗牛肉麵吧。","en":"Let's hit that famous place — a bowl of beef noodles each.","py":"wǒ men qù nà jiā yǒu míng de diàn, yī rén diǎn yī wǎn niú ròu miàn ba."},{"zh":"這家餐廳的湯真不錯，我要再點一碗。","en":"The soup here is great — I'm ordering another bowl.","py":"zhè jiā cān tīng de tāng zhēn bù cuò, wǒ yào zài diǎn yī wǎn."}],"cy":"Order a bowl of something at a famous 店 using both 碗 and 家."},{"id":"g5-7","t":"得 — complement marker","e":"Verb + 得 + how well: 他做得很好. The 得 links a verb to its quality.","tgt":["得"],"alt":["的","了","地"],"s":[{"zh":"他做得很好。","en":"He does it very well.","py":"tā zuò dé hěn hǎo."},{"zh":"你說得對。","en":"You're right.","py":"nǐ shuō dé duì."},{"zh":"她吃得很少。","en":"She eats very little.","py":"tā chī dé hěn shǎo."},{"zh":"你中文說得真好，是在哪裡學的？","en":"Your Chinese is really good — where did you learn it?","py":"nǐ zhōng wén shuō dé zhēn hǎo, shì zài nǎ lǐ xué de?"},{"zh":"我媽媽做飯做得比餐廳的還好吃。","en":"My mom cooks even better than restaurants.","py":"wǒ mā mā zuò fàn zuò dé bǐ cān tīng de hái hǎo chī."}],"cy":"Compliment someone's cooking or Chinese with V + 得 + …"}],"6":[{"id":"g6-1","t":"在 — location verb","e":"在 states location: X 在 place; also 'at' before place + verb: 我在教室上課.","tgt":["在"],"alt":["有","是","到"],"s":[{"zh":"圖書館在哪裡？","en":"Where is the library?","py":"tú shū guǎn zài nǎ lǐ?"},{"zh":"學校在山上。","en":"The school is on the mountain.","py":"xué xiào zài shān shàng."},{"zh":"我在教室上課。","en":"I attend class in the classroom.","py":"wǒ zài jiào shì shàng kè."},{"zh":"他們在外面吃飯。","en":"They are eating outside.","py":"tā men zài wài miàn chī fàn."},{"zh":"我們學校在山上，前面有海，風景真美。","en":"Our school is on a mountain with the ocean in front — the view is gorgeous.","py":"wǒ men xué xiào zài shān shàng, qián miàn yǒu hǎi, fēng jǐng zhēn měi."},{"zh":"你現在在哪裡？我在圖書館裡面看書。","en":"Where are you right now? I'm in the library reading.","py":"nǐ xiàn zài zài nǎ lǐ? wǒ zài tú shū guǎn lǐ miàn kàn shū."}],"cy":"Say where you live and where you study using 在."},{"id":"g6-2","t":"Position words","e":"前面 front, 後面 back, 旁邊 beside, 裡面 inside, 外面 outside, 附近 nearby.","tgt":["前面","旁邊","附近","後面"],"alt":["裡面","外面"],"s":[{"zh":"學校前面有海。","en":"In front of the school there is the ocean.","py":"xué xiào qián miàn yǒu hǎi."},{"zh":"圖書館旁邊是教室。","en":"Beside the library is the classroom.","py":"tú shū guǎn páng biān shì jiào shì."},{"zh":"商店在宿舍附近。","en":"The shop is near the dormitory.","py":"shāng diàn zài sù shè fù jìn."},{"zh":"我的宿舍在圖書館後面，旁邊有一家商店。","en":"My dorm is behind the library, with a shop next door.","py":"wǒ de sù shè zài tú shū guǎn hòu miàn, páng biān yǒu yī jiā shāng diàn."},{"zh":"教室外面有很多學生在照相。","en":"Outside the classroom, lots of students are taking photos.","py":"jiào shì wài miàn yǒu hěn duō xué shēng zài zhào xiàng."}],"cy":"Describe what's around your home with two position words."},{"id":"g6-3","t":"這裡 / 那裡 / 哪裡","e":"Here / there / where.","tgt":["哪裡","這裡","那裡"],"alt":["什麼","誰"],"s":[{"zh":"你在哪裡？","en":"Where are you?","py":"nǐ zài nǎ lǐ?"},{"zh":"我在這裡。","en":"I'm here.","py":"wǒ zài zhè lǐ."},{"zh":"那裡的風景很美。","en":"The scenery there is very beautiful.","py":"nà lǐ de fēng jǐng hěn měi."},{"zh":"你知道游泳池在哪裡嗎？就在那裡，大樓的後面。","en":"Do you know where the pool is? Right there, behind the building.","py":"nǐ zhī dào yóu yǒng chí zài nǎ lǐ ma? jiù zài nà lǐ, dà lóu de hòu miàn."},{"zh":"這裡的東西比那裡的便宜。","en":"Things here are cheaper than over there.","py":"zhè lǐ de dōng xī bǐ nà lǐ de pián yi."}],"cy":"Ask where something is, then answer with 這裡/那裡."},{"id":"g6-4","t":"遠 and 近","e":"X 離 Y 遠/近 — far/near from. 離 marks the reference point.","tgt":["遠","近","離"],"alt":["快","慢"],"s":[{"zh":"學校離這裡遠嗎？","en":"Is the school far from here?","py":"xué xiào lí zhè lǐ yuǎn ma?"},{"zh":"宿舍離教室很近。","en":"The dormitory is very close to the classroom.","py":"sù shè lí jiào shì hěn jìn."},{"zh":"海離學校不遠。","en":"The ocean is not far from the school.","py":"hǎi lí xué xiào bù yuǎn."},{"zh":"我家離學校很近，走路十分鐘就到了。","en":"My place is close to school — a ten-minute walk.","py":"wǒ jiā lí xué xiào hěn jìn, zǒu lù shí fēn zhōng jiù dào le."},{"zh":"花蓮離臺北有一點遠，得坐火車去。","en":"Hualien is a bit far from Taipei — you have to take the train.","py":"huā lián lí tái běi yǒu yì diǎn yuǎn, dé zuò huǒ chē qù."}],"cy":"Say how far your home is from school using 離…遠/近."},{"id":"g6-5","t":"聽說 — I heard that…","e":"聽說 + clause reports hearsay.","tgt":["聽說"],"alt":["知道","覺得","想"],"s":[{"zh":"聽說花蓮的風景很美。","en":"I heard Hualien's scenery is beautiful.","py":"tīng shuō huā lián de fēng jǐng hěn měi."},{"zh":"聽說那裡的小吃很好吃。","en":"I heard the snacks there are delicious.","py":"tīng shuō nà lǐ de xiǎo chī hěn hǎo chī."},{"zh":"聽說你們學校附近的小吃又便宜又好吃。","en":"I hear the street food near your school is cheap and delicious.","py":"tīng shuō nǐ men xué xiào fù jìn de xiǎo chī yòu pián yi yòu hǎo chī."},{"zh":"聽說他下個月要回國了，是真的嗎？","en":"I heard he's going back home next month — is that true?","py":"tīng shuō tā xià gè yuè yào huí guó le, shì zhēn de ma?"}],"cy":"Report something you heard about Taiwan with 聽說."},{"id":"g6-6","t":"Measure words 樓 and 棟","e":"樓 floors (三樓 3rd floor); 棟 whole buildings.","tgt":["樓","棟"],"alt":["間","家","個"],"s":[{"zh":"我住在三樓。","en":"I live on the third floor.","py":"wǒ zhù zài sān lóu."},{"zh":"教室在五樓。","en":"The classroom is on the fifth floor.","py":"jiào shì zài wǔ lóu."},{"zh":"那棟大樓是圖書館。","en":"That building is the library.","py":"nà dòng dà lóu shì tú shū guǎn."},{"zh":"我住的宿舍有五棟，我住在三樓。","en":"My dorm complex has five buildings; I'm on the third floor.","py":"wǒ zhù de sù shè yǒu wǔ dòng, wǒ zhù zài sān lóu."},{"zh":"圖書館的二樓可以看書，不能吃東西。","en":"You can read on the library's second floor, but no eating.","py":"tú shū guǎn de èr lóu kě yǐ kàn shū, bù néng chī dōng xī."}],"cy":"Say which floor you live on and point out a building with 棟."}],"7":[{"id":"g7-1","t":"Telling time — 點 and 分","e":"X點Y分; 半 = half past. Time words go BEFORE the verb.","tgt":["點","分","半"],"alt":["號","月"],"s":[{"zh":"現在幾點？","en":"What time is it now?","py":"xiàn zài jǐ diǎn?"},{"zh":"你幾點下課？","en":"What time does your class end?","py":"nǐ jǐ diǎn xià kè?"},{"zh":"我們三點半見面。","en":"We meet at 3:30.","py":"wǒ men sān diǎn bàn jiàn miàn."},{"zh":"我早上八點上課，下午四點半下課。","en":"I start class at 8 a.m. and finish at 4:30 p.m.","py":"wǒ zǎo shàng bā diǎn shàng kè, xià wǔ sì diǎn bàn xià kè."},{"zh":"我們明天中午十二點在學校門口見面吧。","en":"Let's meet at noon tomorrow at the school gate.","py":"wǒ men míng tiān zhōng wǔ shí èr diǎn zài xué xiào mén kǒu jiàn miàn ba."}],"cy":"Say when you get up, start class, and eat dinner."},{"id":"g7-2","t":"從…到… — from…to…","e":"Works for time and places: 從三點到五點, 從學校到銀行.","tgt":["從","到"],"alt":["在","離"],"s":[{"zh":"從三點到五點我有課。","en":"From 3:00 to 5:00 I have class.","py":"cóng sān diǎn dào wǔ diǎn wǒ yǒu kè."},{"zh":"從星期一到星期五我上課。","en":"From Monday to Friday I attend class.","py":"cóng xīng qī yī dào xīng qī wǔ wǒ shàng kè."},{"zh":"從學校到銀行很近。","en":"From school to the bank is close.","py":"cóng xué xiào dào yín háng hěn jìn."},{"zh":"我從早上九點到晚上六點都有課，真忙。","en":"I have class from 9 a.m. to 6 p.m. — so busy.","py":"wǒ cóng zǎo shàng jiǔ diǎn dào wǎn shàng liù diǎn dōu yǒu kè, zhēn máng."},{"zh":"從我家到捷運站，走路只要五分鐘。","en":"From my place to the MRT, it's just a five-minute walk.","py":"cóng wǒ jiā dào jié yùn zhàn, zǒu lù zhǐ yào wǔ fēn zhōng."}],"cy":"Describe your class schedule with 從…到…"},{"id":"g7-3","t":"得 (děi) — must / have to","e":"得 before a verb = have to. Same character as complement 得(de) — context decides.","tgt":["得"],"alt":["要","會","能"],"s":[{"zh":"我得去銀行。","en":"I have to go to the bank.","py":"wǒ dé qù yín háng."},{"zh":"你得早一點來。","en":"You have to come earlier.","py":"nǐ dé zǎo yì diǎn lái."},{"zh":"明天我得上課。","en":"Tomorrow I have to attend class.","py":"míng tiān wǒ dé shàng kè."},{"zh":"我今天得去銀行，不能跟你們去KTV。","en":"I have to go to the bank today, so I can't join you at KTV.","py":"wǒ jīn tiān dé qù yín háng, bù néng gēn nǐ men qù K T V."},{"zh":"明天有書法課，我得早一點到學校。","en":"There's calligraphy class tomorrow — I have to get to school early.","py":"míng tiān yǒu shū fǎ kè, wǒ dé zǎo yì diǎn dào xué xiào."}],"cy":"List two things you have to do tomorrow with 得."},{"id":"g7-4","t":"剛 — just now","e":"剛 before the verb: it happened moments ago.","tgt":["剛"],"alt":["常","再","就"],"s":[{"zh":"我剛下課。","en":"I just finished class.","py":"wǒ gāng xià kè."},{"zh":"他剛到。","en":"He just arrived.","py":"tā gāng dào."},{"zh":"比賽剛結束。","en":"The game just ended.","py":"bǐ sài gāng jié shù."},{"zh":"我剛下課，現在要去吃午餐，你要一起來嗎？","en":"I just got out of class and I'm heading to lunch — want to come?","py":"wǒ gāng xià kè, xiàn zài yào qù chī wǔ cān, nǐ yào yì qǐ lái ma?"},{"zh":"他剛從臺南回來，帶了很多好吃的東西。","en":"He just got back from Tainan with lots of good food.","py":"tā gāng cóng tái nán huí lái, dài le hěn duō hǎo chī de dōng xī."}],"cy":"Say two things that just happened with 剛."},{"id":"g7-5","t":"每 — every","e":"每 + measure word + noun; usually pairs with 都: 我每天都上課.","tgt":["每","都"],"alt":["常","也"],"s":[{"zh":"我每天都上課。","en":"I have class every day.","py":"wǒ měi tiān dōu shàng kè."},{"zh":"每個星期六我去KTV。","en":"Every Saturday I go to KTV.","py":"měi gè xīng qī liù wǒ qù K T V."},{"zh":"我每天早上都喝一杯咖啡，喝了才能上課。","en":"I drink a coffee every morning — only then can I face class.","py":"wǒ měi tiān zǎo shàng dōu hē yī bēi kā fēi, hē le cái néng shàng kè."},{"zh":"他每個週末都去圖書館念書。","en":"He studies at the library every weekend.","py":"tā měi gè zhōu mò dōu qù tú shū guǎn niàn shū."}],"cy":"Describe a routine with 每…都…"},{"id":"g7-6","t":"…的時候 — when…","e":"Clause + 的時候 = when/while: 下課的時候.","tgt":["的時候"],"alt":["以後","以前"],"s":[{"zh":"下課的時候，你在哪裡？","en":"When class ended, where were you?","py":"xià kè de shí hòu, nǐ zài nǎ lǐ?"},{"zh":"我忙的時候，不能見面。","en":"When I'm busy, I can't meet.","py":"wǒ máng de shí hòu, bù néng jiàn miàn."},{"zh":"你有空的時候，我們去唱歌吧。","en":"When you're free, let's go sing.","py":"nǐ yǒu kòng de shí hòu, wǒ men qù chàng gē ba."},{"zh":"我上課的時候，不能看手機。","en":"I can't look at my phone during class.","py":"wǒ shàng kè de shí hòu, bù néng kàn shǒu jī."},{"zh":"我有空的時候，常去學校旁邊的茶館喝茶。","en":"When I'm free, I often go drink tea at the teahouse near school.","py":"wǒ yǒu kòng de shí hòu, cháng qù xué xiào páng biān de chá guǎn hē chá."}],"cy":"Say what you do 有空的時候 (when free)."},{"id":"g7-7","t":"有空 vs 有事","e":"有空 = free; 有事 = busy / have something on.","tgt":["有空","有事"],"alt":["有課","沒有"],"s":[{"zh":"你明天有空嗎？","en":"Are you free tomorrow?","py":"nǐ míng tiān yǒu kòng ma?"},{"zh":"我下午有空。","en":"I'm free in the afternoon.","py":"wǒ xià wǔ yǒu kòng."},{"zh":"對不起，我今天有事。","en":"Sorry, I'm busy today.","py":"duì bù qǐ, wǒ jīn tiān yǒu shì."},{"zh":"你星期五晚上有空嗎？我們去唱歌吧。","en":"Are you free Friday night? Let's go sing.","py":"nǐ xīng qī wǔ wǎn shàng yǒu kòng ma? wǒ men qù chàng gē ba."},{"zh":"不好意思，我今天有事，下次再一起去吧。","en":"Sorry, I've got something on today — next time.","py":"bù hǎo yì sī, wǒ jīn tiān yǒu shì, xià cì zài yì qǐ qù ba."}],"cy":"Invite a friend out, and decline politely using 有事."}],"8":[{"id":"g8-1","t":"坐 vs 騎 — transport","e":"坐 for vehicles you sit inside (火車/高鐵/捷運/公車/計程車); 騎 for ones you straddle (機車/腳踏車).","tgt":["坐","騎"],"alt":["開","走"],"s":[{"zh":"我坐火車去臺南。","en":"I take the train to Tainan.","py":"wǒ zuò huǒ chē qù tái nán."},{"zh":"他坐捷運上課。","en":"He takes the MRT to class.","py":"tā zuò jié yùn shàng kè."},{"zh":"我騎機車去學校。","en":"I ride a scooter to school.","py":"wǒ qí jī chē qù xué xiào."},{"zh":"在臺北，很多人騎機車上班，也有很多人坐捷運。","en":"In Taipei, lots of people scooter to work — and lots take the MRT.","py":"zài tái běi, hěn duō rén qí jī chē shàng bān, yě yǒu hěn duō rén zuò jié yùn."},{"zh":"我們坐高鐵去臺南吧，比火車快多了。","en":"Let's take the HSR to Tainan — way faster than the train.","py":"wǒ men zuò gāo tiě qù tái nán ba, bǐ huǒ chē kuài duō le."}],"cy":"Say how you get to school and how you'd travel to Tainan."},{"id":"g8-2","t":"比 — comparison","e":"A 比 B + adjective: 高鐵比火車快. Add amount after: 快兩個鐘頭.","tgt":["比"],"alt":["跟","比較","更"],"s":[{"zh":"高鐵比火車快。","en":"The HSR is faster than the train.","py":"gāo tiě bǐ huǒ chē kuài."},{"zh":"捷運比公車方便。","en":"The MRT is more convenient than the bus.","py":"jié yùn bǐ gōng chē fāng biàn."},{"zh":"高鐵比火車快兩個鐘頭。","en":"The HSR is two hours faster than the train.","py":"gāo tiě bǐ huǒ chē kuài liǎng gè zhōng tóu."},{"zh":"高鐵比火車貴，可是快兩個多鐘頭。","en":"The HSR costs more than the train, but it's over two hours faster.","py":"gāo tiě bǐ huǒ chē guì, kě shì kuài liǎng gè duō zhōng tóu."},{"zh":"我覺得夜市的東西比餐廳的便宜。","en":"I think night-market food is cheaper than restaurants.","py":"wǒ jué de yè shì de dōng xī bǐ cān tīng de pián yi."}],"cy":"Compare two ways to travel with 比."},{"id":"g8-3","t":"比較 — relatively / prefer","e":"比較 + adjective/verb softens comparison: 我比較喜歡坐火車.","tgt":["比較"],"alt":["比","最","更"],"s":[{"zh":"我比較喜歡坐火車。","en":"I prefer taking the train.","py":"wǒ bǐ jiào xǐ huān zuò huǒ chē."},{"zh":"高鐵比較舒服。","en":"The HSR is more comfortable.","py":"gāo tiě bǐ jiào shū fú."},{"zh":"這個比較好。","en":"This one is better.","py":"zhè ge bǐ jiào hǎo."},{"zh":"我比較喜歡騎機車，因為比較方便。","en":"I prefer riding a scooter — it's more convenient.","py":"wǒ bǐ jiào xǐ huān qí jī chē, yīn wèi bǐ jiào fāng biàn."},{"zh":"這兩家店，哪一家比較好吃？","en":"Of these two places, which one's better?","py":"zhè liǎng jiā diàn, nǎ yī jiā bǐ jiào hǎo chī?"}],"cy":"State a soft preference with 比較喜歡."},{"id":"g8-4","t":"又…又… — both…and…","e":"又 A 又 B stacks two qualities: 又快又舒服.","tgt":["又"],"alt":["也","都","和"],"s":[{"zh":"高鐵又快又舒服。","en":"The HSR is both fast and comfortable.","py":"gāo tiě yòu kuài yòu shū fú."},{"zh":"這個地方又遠又貴。","en":"This place is both far and expensive.","py":"zhè ge dì fāng yòu yuǎn yòu guì."},{"zh":"夜市的小吃又便宜又好吃。","en":"Night-market snacks are both cheap and delicious.","py":"yè shì de xiǎo chī yòu pián yi yòu hǎo chī."},{"zh":"坐高鐵又快又舒服，可是有一點貴。","en":"The HSR is fast and comfortable, but a bit pricey.","py":"zuò gāo tiě yòu kuài yòu shū fú, kě shì yǒu yì diǎn guì."}],"cy":"Describe something with 又…又…"},{"id":"g8-5","t":"怎麼 — how","e":"怎麼 + verb asks method: 怎麼去？ 怎麼買票？","tgt":["怎麼"],"alt":["為什麼","什麼","哪裡"],"s":[{"zh":"你怎麼去臺南？","en":"How do you get to Tainan?","py":"nǐ zěn me qù tái nán?"},{"zh":"怎麼買票？","en":"How do you buy tickets?","py":"zěn me mǎi piào?"},{"zh":"請問到故宮博物院怎麼走？坐公車可以到嗎？","en":"How do I get to the National Palace Museum? Can I take a bus?","py":"qǐng wèn dào gù gōng bó wù yuàn zěn me zǒu? zuò gōng chē kě yǐ dào ma?"},{"zh":"高鐵的車票怎麼買？網路上可以買嗎？","en":"How do you buy HSR tickets? Can you buy them online?","py":"gāo tiě de chē piào zěn me mǎi? wǎng lù shàng kě yǐ mǎi ma?"}],"cy":"Ask how to get somewhere and how to buy the ticket."},{"id":"g8-6","t":"或是 vs 還是","e":"或是 = or in statements; 還是 = or in questions.","tgt":["或是","還是"],"alt":["也是","可是"],"s":[{"zh":"你可以坐火車或是高鐵。","en":"You can take the train or the HSR.","py":"nǐ kě yǐ zuò huǒ chē huò shì gāo tiě."},{"zh":"你要坐火車還是高鐵？","en":"Do you want the train or the HSR?","py":"nǐ yào zuò huǒ chē hái shì gāo tiě?"},{"zh":"你可以坐捷運或是騎機車來我家。","en":"You can take the MRT or ride a scooter to my place.","py":"nǐ kě yǐ zuò jié yùn huò shì qí jī chē lái wǒ jiā."},{"zh":"我們這個週末去臺南還是花蓮？","en":"This weekend — Tainan or Hualien?","py":"wǒ men zhè ge zhōu mò qù tái nán hái shì huā lián?"}],"cy":"Give a friend two options (或是), then ask which they want (還是)."},{"id":"g8-7","t":"Duration — 鐘頭","e":"Verb + 要 + duration: 坐火車要四個鐘頭.","tgt":["鐘頭"],"alt":["點","分鐘","小時"],"s":[{"zh":"坐火車要四個鐘頭。","en":"The train takes four hours.","py":"zuò huǒ chē yào sì gè zhōng tóu."},{"zh":"高鐵只要一個半鐘頭。","en":"The HSR only takes an hour and a half.","py":"gāo tiě zhǐ yào yí gè bàn zhōng tóu."},{"zh":"從臺北坐火車到花蓮要三個鐘頭左右。","en":"The train from Taipei to Hualien takes about three hours.","py":"cóng tái běi zuò huǒ chē dào huā lián yào sān gè zhōng tóu zuǒ yòu."},{"zh":"我每天坐捷運差不多一個鐘頭。","en":"I spend about an hour a day on the MRT.","py":"wǒ měi tiān zuò jié yùn chà bu duō yí gè zhōng tóu."}],"cy":"Say how long your commute takes with 要…鐘頭/分鐘."}],"9":[{"id":"g9-1","t":"Days & dates","e":"星期+number (星期天 Sunday); dates: 月 + 號: 三月五號.","tgt":["星期","號","月"],"alt":["點","天"],"s":[{"zh":"我星期三有課。","en":"I have class on Wednesday.","py":"wǒ xīng qī sān yǒu kè."},{"zh":"星期六你有空嗎？","en":"Are you free on Saturday?","py":"xīng qī liù nǐ yǒu kòng ma?"},{"zh":"我的生日是三月五號。","en":"My birthday is March 5th.","py":"wǒ de shēng rì shì sān yuè wǔ hào."},{"zh":"我打算七月十號回國，八月一號再回來。","en":"I plan to go home on July 10th and come back August 1st.","py":"wǒ dǎ suàn qī yuè shí hào huí guó, bā yuè yī hào zài huí lái."},{"zh":"你的生日是幾月幾號？我們一起過吧。","en":"When's your birthday? Let's celebrate it together.","py":"nǐ de shēng rì shì jǐ yuè jǐ hào? wǒ men yì qǐ guò ba."}],"cy":"Say your birthday and one weekly commitment."},{"id":"g9-2","t":"打算 — to plan","e":"打算 + verb phrase directly (no 要): 我打算下個星期去臺東.","tgt":["打算"],"alt":["希望","想","要"],"s":[{"zh":"你打算什麼時候回國？","en":"When do you plan to return home?","py":"nǐ dǎ suàn shén me shí hòu huí guó?"},{"zh":"我打算下個星期去臺東。","en":"I plan to go to Taitung next week.","py":"wǒ dǎ suàn xià gè xīng qī qù tái dōng."},{"zh":"放假的時候，你打算做什麼？","en":"What do you plan to do on vacation?","py":"fàng jià de shí hòu, nǐ dǎ suàn zuò shén me?"},{"zh":"放假的時候，我打算跟朋友去臺東玩一個星期。","en":"Over the break, I plan to spend a week in Taitung with friends.","py":"fàng jià de shí hòu, wǒ dǎ suàn gēn péng yǒu qù tái dōng wán yí gè xīng qī."},{"zh":"你打算在臺灣學多久的中文？","en":"How long do you plan to study Chinese in Taiwan?","py":"nǐ dǎ suàn zài tái wān xué duō jiǔ de zhōng wén?"}],"cy":"Share your holiday plan with 打算."},{"id":"g9-3","t":"要是…就… — if…then…","e":"要是 A，(subject) 就 B: 就 comes after the subject in the result clause.","tgt":["要是","就"],"alt":["因為","所以"],"s":[{"zh":"要是明天下雨，我就不出去。","en":"If it rains tomorrow, I won't go out.","py":"yào shì míng tiān xià yǔ, wǒ jiù bù chū qù."},{"zh":"要是你有空，我們就一起去。","en":"If you're free, let's go together.","py":"yào shì nǐ yǒu kòng, wǒ men jiù yì qǐ qù."},{"zh":"要是你想去夜市，我就帶你去。","en":"If you want the night market, I'll take you.","py":"yào shì nǐ xiǎng qù yè shì, wǒ jiù dài nǐ qù."},{"zh":"要是週末不下雨，我們就去山上走走。","en":"If it doesn't rain this weekend, let's go walk in the mountains.","py":"yào shì zhōu mò bù xià yǔ, wǒ men jiù qù shān shàng zǒu zǒu."},{"zh":"要是你沒空，我們就下次再見面。","en":"If you're not free, we'll just meet next time.","py":"yào shì nǐ méi kòng, wǒ men jiù xià cì zài jiàn miàn."}],"cy":"Make an if-then plan for the weekend with 要是…就…"},{"id":"g9-4","t":"應該 — should","e":"應該 suggests (softer than must): 你應該去貓空看看.","tgt":["應該"],"alt":["得","會","要"],"s":[{"zh":"你應該去貓空看看。","en":"You should go check out Maokong.","py":"nǐ yīng gāi qù māo kōng kàn kàn."},{"zh":"我們應該早一點決定。","en":"We should decide earlier.","py":"wǒ men yīng gāi zǎo yì diǎn jué dìng."},{"zh":"你來臺灣，應該去夜市吃吃看臭豆腐。","en":"Since you're in Taiwan, you should try stinky tofu at a night market.","py":"nǐ lái tái wān, yīng gāi qù yè shì chī chī kàn chòu dòu fǔ."},{"zh":"我們應該早一點買車票，因為放假的時候人很多。","en":"We should buy tickets early — holidays get crowded.","py":"wǒ men yīng gāi zǎo yì diǎn mǎi chē piào, yīn wèi fàng jià de shí hòu rén hěn duō."}],"cy":"Give a friend two recommendations for Taipei with 應該."},{"id":"g9-5","t":"多久 — how long","e":"多久 asks duration: 你要去多久？","tgt":["多久"],"alt":["多少","幾點","什麼時候"],"s":[{"zh":"你要去多久？","en":"How long will you go for?","py":"nǐ yào qù duō jiǔ?"},{"zh":"從臺北到臺東要多久？","en":"How long from Taipei to Taitung?","py":"cóng tái běi dào tái dōng yào duō jiǔ?"},{"zh":"從你家走路到捷運站要多久？","en":"How long is the walk from your place to the MRT?","py":"cóng nǐ jiā zǒu lù dào jié yùn zhàn yào duō jiǔ?"},{"zh":"你打算在臺灣住多久？一年還是兩年？","en":"How long will you stay in Taiwan — one year or two?","py":"nǐ dǎ suàn zài tái wān zhù duō jiǔ? yī nián hái shì liǎng nián?"}],"cy":"Ask a classmate how long they'll study Chinese with 多久."},{"id":"g9-6","t":"還 — still / in addition","e":"還 = still (還在/還沒) or additionally (還想去…).","tgt":["還"],"alt":["就","再","又"],"s":[{"zh":"你還在學校嗎？","en":"Are you still at school?","py":"nǐ hái zài xué xiào ma?"},{"zh":"我還沒決定。","en":"I still haven't decided.","py":"wǒ hái méi jué dìng."},{"zh":"我想去夜市，還想去茶館。","en":"I want the night market, and also a teahouse.","py":"wǒ xiǎng qù yè shì, hái xiǎng qù chá guǎn."},{"zh":"我還沒去過貓空，聽說那裡的茶館很特別。","en":"I still haven't been to Maokong — I hear the teahouses there are special.","py":"wǒ hái méi qù guò māo kōng, tīng shuō nà lǐ de chá guǎn hěn tè bié."},{"zh":"我想吃小籠包，還想去逛夜市。","en":"I want xiaolongbao — and to wander a night market too.","py":"wǒ xiǎng chī xiǎo lóng bāo, hái xiǎng qù guàng yè shì."}],"cy":"Say something you still haven't done with 還沒."},{"id":"g9-7","t":"有時候 — sometimes","e":"有時候 before the clause: 有時候我在家看電視.","tgt":["有時候"],"alt":["常","每天","的時候"],"s":[{"zh":"有時候我在家看電視。","en":"Sometimes I watch TV at home.","py":"yǒu shí hòu wǒ zài jiā kàn diàn shì."},{"zh":"我有時候會去那家茶館。","en":"I sometimes go to that teahouse.","py":"wǒ yǒu shí hòu huì qù nà jiā chá guǎn."},{"zh":"我有時候自己做飯，有時候去外面吃。","en":"Sometimes I cook, sometimes I eat out.","py":"wǒ yǒu shí hòu zì jǐ zuò fàn, yǒu shí hòu qù wài miàn chī."},{"zh":"他有時候坐捷運上課，有時候騎機車。","en":"Sometimes he MRTs to class, sometimes he scooters.","py":"tā yǒu shí hòu zuò jié yùn shàng kè, yǒu shí hòu qí jī chē."}],"cy":"Describe two 'sometimes' habits with 有時候."}],"10":[{"id":"n10-1","t":"VV 看 · try and see","e":"Double a one-syllable action verb and add 看 to mean 'give it a try and see' — try VV-ing and see what happens. No object can follow VV看; put the object first as the topic instead.","pat":"Double a one-syllable action verb and add 看: 吃吃看, 穿穿看, 試試看 (L12). Means \"give it a try and see\". Rules: no object after VV看 (喝喝看咖啡 ✗; put the object first as a topic: 這杯咖啡，你喝喝看), and plain VV without 看 is just \"do a little\" (看看書、喝喝咖啡), no trying implied.","tgt":["VV看"],"alt":["V了"],"s":[{"zh":"這杯咖啡很香，你喝喝看。","en":"This coffee smells great, try it and see.","py":"zhè bēi kā fēi hěn xiāng, nǐ hē hē kàn."},{"zh":"聽說你唱歌唱得很好，我想聽聽看。","en":"I heard you sing well, I'd like to listen and see.","py":"tīng shuō nǐ chàng gē chàng dé hěn hǎo, wǒ xiǎng tīng tīng kàn."},{"zh":"那家餐廳的菜很好吃，我想去吃吃看。","en":"That restaurant's food is tasty, I want to go try it.","py":"nà jiā cān tīng de cài hěn hǎo chī, wǒ xiǎng qù chī chī kàn."},{"zh":"臺灣的夜市很有名，這個週末我想去逛逛看。","en":"Taiwan's night markets are famous, I want to go check one out this weekend.","py":"tái wān de yè shì hěn yǒu míng, zhè ge zhōu mò wǒ xiǎng qù guàng guàng kàn."},{"zh":"這杯咖啡，你喝喝看。","en":"This coffee — try it and see. (object fronted as topic)","py":"zhè bēi kā fēi, nǐ hē hē kàn."}],"cy":"Write your own sentence using VV看 (e.g. 試試看) to suggest trying something.","ov":"Where this goes next (9/8): the same \"give it a go\" idea comes back in B2 L3 — 我沒學過中文，可是想學學看。 It pairs naturally with that lesson's 沒 V 過. But two-syllable verbs can't take 看 this way — they reduplicate as ABAB instead (練習練習, 休息休息, B2 L3 point 5). One-syllable verb → VV看; two-syllable verb → ABAB. ✗練習練習看.","tw":"吃吃看 / 試試看 are extremely common here; night-market vendors say it to you constantly. Trad/simp: 聽 → 听, 逛 same, 廳 → 厅","src":"B1L10"},{"id":"n10-2","t":"Vs Vs 的 · reduplicated state verbs","e":"Doubling a one-syllable state verb and adding 的 makes a warm, subjective description (praise or complaint) rather than a neutral fact stated with 很. 的 is required and it never combines with 很.","pat":"Vs → VsVs + 的. Same job as 很 but subjective and warm: this is how you praise or complain, not how you describe neutrally. Rules: 的 is required (香香 alone ✗), and never combine with 很 (很香香的 ✗). Two doubled Vs in a row drop the first 的: 香香甜甜的.","tgt":["VsVs的"],"alt":["很+Vs"],"s":[{"zh":"這碗牛肉湯香香的。","en":"This bowl of beef soup smells nice.","py":"zhè wǎn niú ròu tāng xiāng xiāng de."},{"zh":"熱熱的咖啡，真香。","en":"Nice hot coffee, really fragrant.","py":"rè rè de kā fēi, zhēn xiāng."},{"zh":"那個地方有很多高高的大樓。","en":"That place has lots of tall buildings.","py":"nà ge dì fāng yǒu hěn duō gāo gāo de dà lóu."},{"zh":"那種水果香香甜甜的。","en":"That kind of fruit is nice and fragrant and sweet.","py":"nà zhǒng shuǐ guǒ xiāng xiāng tián tián de."}],"cy":"Write your own sentence using a reduplicated state verb + 的 (e.g. 熱熱的, 高高的) to praise or comment warmly on something.","ov":"Related: two-syllable Vs double as AABB (乾乾淨淨) in B2 L2.","tw":"Trad/simp: 湯 → 汤, 熱 → 热, 樓 → 楼, 種 → 种","src":"B1L10"},{"id":"n10-3","t":"Clause + 的 + N · clauses as noun modifiers","e":"A whole clause can modify a noun by sitting in front of it with 的, the same slot an adjective would occupy — there is no separate word for 'which/that/who' in Chinese; the modifier always precedes the noun.","pat":"A whole clause can sit in front of a noun with 的, exactly where an adjective would: [我拍]的照片 = the photos [I took]. Chinese has no \"which / that / who\"; the modifier always comes before the noun and 的 sits right before the noun. Read these right-to-left: find the noun after 的, then everything before it is the description.","tgt":["的"],"alt":["的話","得","地"],"s":[{"zh":"這些是我拍的照片。","en":"These are the photos I took.","py":"zhè xiē shì wǒ pāi de zhào piān."},{"zh":"穿黃衣服的這個人是老闆。","en":"The person wearing yellow clothes is the boss.","py":"chuān huáng yī fú de zhè ge rén shì lǎo bǎn."},{"zh":"現在去那裡玩的人比較少。","en":"The people who go there to play now are fewer.","py":"xiàn zài qù nà lǐ wán de rén bǐ jiào shǎo."},{"zh":"他喝的茶是烏龍茶。","en":"The tea he drinks is oolong tea.","py":"tā hē de chá shì wū lóng chá."},{"zh":"買這種手機的人很多。","en":"There are a lot of people who buy this kind of phone.","py":"mǎi zhè zhǒng shǒu jī de rén hěn duō."},{"zh":"不能上網的手機很不方便。","en":"A phone that can't get online is very inconvenient.","py":"bù néng shàng wǎng de shǒu jī hěn bù fāng biàn."},{"zh":"不來上課的同學不能去看籃球比賽。","en":"Classmates who don't come to class can't go watch the basketball game.","py":"bù lái shàng kè de tóng xué bù néng qù kàn lán qiú bǐ sài."}],"cy":"Write your own sentence using a clause + 的 + noun (e.g. describing 'the person who...' or 'the thing I...').","ov":"","tw":"Trad/simp: 黃 → 黄, 闆 → 板, 烏龍 → 乌龙, 網 → 网, 賽 → 赛","src":"B1L10"},{"id":"n10-4","t":"Sentence-final 了 · change of situation","e":"了 placed at the very end of a sentence signals that the overall situation has changed from before — it got expensive, I now can, I no longer. This is different from the 了 right after a verb, which marks a completed action (introduced in L13).","pat":"了 at the very end of the sentence = \"things are different now\": it got expensive, I can now, I no longer. Keep this separate from the 了 right after a verb (completed action, L13). Negative is 不…了 = \"not anymore\" (不喝了), never 沒…了. Question: …了嗎？","tgt":["句尾了"],"alt":["V了","快...了","得...了"],"s":[{"zh":"咖啡貴了。","en":"Coffee has gotten expensive.","py":"kā fēi guì le."},{"zh":"現在有手機的人多了。","en":"Now there are more people with phones (than before).","py":"xiàn zài yǒu shǒu jī de rén duō le."},{"zh":"我會打網球了。","en":"I can play tennis now (I couldn't before).","py":"wǒ huì dǎ wǎng qiú le."},{"zh":"我現在喜歡吃越南麵了。","en":"I like eating Vietnamese noodles now (I didn't used to).","py":"wǒ xiàn zài xǐ huān chī yuè nán miàn le."},{"zh":"我媽媽不喝咖啡了。","en":"My mom doesn't drink coffee anymore.","py":"wǒ mā mā bù hē kā fēi le."},{"zh":"他不想買那支手機了。","en":"He doesn't want to buy that phone anymore.","py":"tā bù xiǎng mǎi nà zhī shǒu jī le."},{"zh":"你想吃午餐了嗎？","en":"Do you feel like eating lunch now?","py":"nǐ xiǎng chī wǔ cān le ma?"},{"zh":"你們不去臺東了嗎？","en":"Are you not going to Taidong anymore?","py":"nǐ men bù qù tái dōng le ma?"}],"cy":"Write your own sentence using sentence-final 了 to describe a change (e.g. something you can now do, or no longer do).","ov":"The 了 family, in order (9/8): 咖啡貴了 (here: situation changed) → 我買了水果 (B1 L13 point 2: one event finished) → 我住了三年 (B1 L14 point 1: how long it ran) → 我住了三年了 (B1 L14 point 2: and still ongoing) → 快下雨了 (B1 L14 point 3: about to happen) → 我寫得差不多了 (B2 L3 point 1: nearly done). This lesson's 了 is the first on that list and stays useful throughout — four of the six items are really this same end-of-sentence 了. Sort any 了 by where it sits: end of sentence = world has changed; right after the verb = event is done.","tw":"Trad/simp: 網球 → 网球, 麵 → 面, 臺東 → 台东","src":"B1L10"},{"id":"n10-5","t":"因為…，所以… · because…, so…","e":"因為 introduces the cause and 所以 introduces the result; unlike English, Chinese normally uses both words together in the same sentence.","pat":"因為 + cause，所以 + result. Unlike English, both words are normally used together. 因為 can also come second (我很開心，因為…), and in casual speech one half is often dropped. If the subject is the same in both halves it usually appears only once.","tgt":["因為","所以"],"alt":["雖然","但是","因此"],"s":[{"zh":"因為現在去玩的人比較少，所以旅館不太貴。","en":"Because fewer people go there to play now, hotels aren't too expensive.","py":"yīn wèi xiàn zài qù wán de rén bǐ jiào shǎo, suǒ yǐ lǚ guǎn bù tài guì."},{"zh":"因為火車太慢了，所以我想坐高鐵。","en":"Because the train is too slow, I want to take the high-speed rail instead.","py":"yīn wèi huǒ chē tài màn le, suǒ yǐ wǒ xiǎng zuò gāo tiě."},{"zh":"因為我不會做飯，所以常去餐廳吃飯。","en":"Because I can't cook, I often eat at restaurants.","py":"yīn wèi wǒ bú huì zuò fàn, suǒ yǐ cháng qù cān tīng chī fàn."},{"zh":"因為我很喜歡中國古代的東西，所以去參觀故宮。","en":"Because I really like ancient Chinese things, I went to visit the Palace Museum.","py":"yīn wèi wǒ hěn xǐ huān zhōng guó gǔ dài de dōng xī, suǒ yǐ qù cān guān gù gōng."}],"cy":"Write your own sentence using 因為…所以… to explain a reason and result.","ov":"","tw":"為 in 因為 is 4th tone here (yīnwèi). Trad/simp: 因為 → 因为, 車 → 车, 鐵 → 铁, 參觀 → 参观, 宮 → 宫","src":"B1L10"}],"11":[{"id":"n11-1","t":"來 + (Place) + VP · come to do something","e":"來 + verb phrase means 'come (here) to do X' — the mirror image of 去 + VP ('go to do X') from L3. 來 moves toward the speaker's location, 去 moves away. Negation, modal verbs, and time words all go before 來.","pat":"來 + VP = \"come (here) to do VP\". Mirror image of 去 + VP from L3: 來 moves toward the speaker, 去 moves away. Negation, 會/要/想, and time words all go before 來: 不來上課, 常來吃飯.","tgt":["來"],"alt":["去","到","在"],"s":[{"zh":"我的朋友來我家吃晚飯。","en":"My friend comes to my house to eat dinner.","py":"wǒ de péng yǒu lái wǒ jiā chī wǎn fàn."},{"zh":"我來學中文。","en":"I've come to study Chinese.","py":"wǒ lái xué zhōng wén."},{"zh":"我明天有事，不來上課。","en":"I have something on tomorrow, I won't come to class.","py":"wǒ míng tiān yǒu shì, bù lái shàng kè."},{"zh":"你要來參觀故宮博物院嗎？","en":"Do you want to come visit the National Palace Museum?","py":"nǐ yào lái cān guān gù gōng bó wù yuàn ma?"}],"cy":"Write your own sentence using 來 + place + VP to say someone comes somewhere to do something.","ov":"Forward — the same 來／去 comes back in B2 L6, in a different slot (family). Here 來 is the main verb and leads the phrase: 我的朋友來我家吃晚飯。 In B2 L6 it becomes a tail hanging off the end of 到 + place: 我要到美國去。／哥哥要到臺灣來。 The idea never changes — 來 = toward where I'm standing, 去 = away from it — but two things do: the position flips from front to back, and in B2 L6 it is optional (從台北開到台南 is complete with neither). Trap: 來／去 lands after the place, not before it. ✓搬到樓上來 ✗搬來到樓上。 B2 L7 (provisional) extends it once more to V + 出／進／過 + 來／去 — 走出來, 開過來.","tw":"Hard pinyin: 參觀 cānguān — to visit/tour a place, not a person (visiting a person is 看 or 拜訪 bàifǎng); 故宮博物院 Gùgōng Bówùyuàn — the National Palace Museum in 士林 Shìlín, Taipei. Trad/simp: 來 → 来, 參觀 → 参观, 故宮 → 故宫, 飯 → 饭","src":"B1L11"},{"id":"n11-2","t":"S + Time/Place + 就 … (了) · sooner than expected","e":"就 placed right before the verb signals that something happened earlier, faster, or closer than expected. The time/distance expression comes before 就; a final 了 is common but optional.","pat":"就 in front of the verb says \"earlier / faster / closer than you'd expect\". The time or distance sits before 就; the final 了 is usual but optional, meaning is the same. This is the same 就 you'll meet as \"only then\" 才's opposite in B2 L3: 就 = sooner than expected, 才 = later than expected.","tgt":["就"],"alt":["才","都","再"],"s":[{"zh":"走路走兩分鐘就到了！","en":"Walking just two minutes and you're there!","py":"zǒu lù zǒu liǎng fēn zhōng jiù dào le!"},{"zh":"從台南去，30分鐘就到了。(從台北去，要50分鐘。)","en":"Going from Tainan, 30 minutes and you're there. (From Taipei it takes 50 minutes.)","py":"cóng tái nán qù, 3 0 fēn zhōng jiù dào le. ( cóng tái běi qù, yào 5 0 fēn zhōng. )"},{"zh":"每天都5點下課，可是星期五四點半就下課了。","en":"Every day class ends at 5, but on Friday it ended already at 4:30.","py":"měi tiān dōu 5 diǎn xià kè, kě shì xīng qī wǔ sì diǎn bàn jiù xià kè le."},{"zh":"安同等一下就到了。","en":"Antong will be here in just a moment.","py":"ān tóng děng yī xià jiù dào le."},{"zh":"我們十點下課，可是小美九點就回家了。","en":"We get out of class at ten, but Xiaomei already went home at nine.","py":"wǒ men shí diǎn xià kè, kě shì xiǎo měi jiǔ diǎn jiù huí jiā le."}],"cy":"Write your own sentence using 就(了) to say something happened sooner than expected.","ov":"就 vs 才 — the pair the exam actually targets (competition, B2 L3). One sentence, one word swapped, and the clock doesn't move: 他八點就來了 = he came at eight — early. 他八點才來 = he came at eight — late. 走路五分鐘就到了 (closer than thought) / 走路五十分鐘才到 (further than thought). Test ①: would you say \"already\" (→就) or \"not until/only\" (→才) in English? Test ② — 才 refuses the final 了. 就 normally takes one (五分鐘就到了); 才 normally doesn't. ✗他九點才回家了 ✓他九點才回家。","tw":"Hard pinyin: 台南 Táinán; 台北 Táiběi — 台 is the everyday form in Taiwan, 臺 the formal one (臺北, 臺灣); 星期 xīngqí in Taiwan, xīngqī on the mainland, same characters, 2nd-tone 期 here; 安同 Āntóng — 馬安同, the American student in the textbook cast. Trad/simp: 鐘 → 钟, 從 → 从","src":"B1L11"},{"id":"n11-3","t":"有 + N + VP · existential subject","e":"A Chinese subject is normally definite; an indefinite subject (someone, a student, three people) must be introduced with 有. Negated with 沒有, never 不有; question form is 有沒有.","pat":"A Chinese subject is normally definite (the person, my friend). An indefinite subject (someone, a student, three people) has to be introduced by 有. Negate with 沒有, never 不有. Question: 有沒有人…？","tgt":["有"],"alt":["是","在","的"],"s":[{"zh":"有人住這裡。","en":"Someone lives here.","py":"yǒu rén zhù zhè lǐ."},{"zh":"沒有人住這裡。","en":"No one lives here.","py":"méi yǒu rén zhù zhè lǐ."},{"zh":"有人要一起吃晚飯嗎？","en":"Does anyone want to eat dinner together?","py":"yǒu rén yào yì qǐ chī wǎn fàn ma?"},{"zh":"早上有一個小姐打電話給你。","en":"This morning a woman called you.","py":"zǎo shàng yǒu yí gè xiǎo jiě dǎ diàn huà gěi nǐ."},{"zh":"有三個人在房間裡面看書。","en":"There are three people in the room reading.","py":"yǒu sān gè rén zài fáng jiān lǐ miàn kàn shū."},{"zh":"有沒有人想去KTV唱歌？","en":"Is there anyone who wants to go sing at KTV?","py":"yǒu méi yǒu rén xiǎng qù K T V chàng gē?"},{"zh":"地上有一支手機。","en":"There's a phone on the floor. (focus on the floor)","py":"dì shàng yǒu yī zhī shǒu jī."},{"zh":"有一支手機在地上。","en":"There's a phone — it's on the floor. (focus on the phone)","py":"yǒu yī zhī shǒu jī zài dì shàng."}],"cy":"Write your own sentence using 有 + N + VP to introduce an indefinite subject.","ov":"Sidebar — the 給 in 早上有一個小姐打電話給你 (family; forward to B2 L6). Not part of this pattern, but this lesson is where 給 first shows up. B1 L11: 打電話給你 — 打電話 has no object to hand over, so 給 does nothing but name who's on the receiving end. B2 L6: V給+人+東西 — now a real thing changes hands, trailing at the end with no marker: 王先生賣給他一輛機車。／他送給白如玉一些甜點。 Same 給 both times, pointing at whoever ends up with something; B2 L6 adds the thing. There it also rides inside 把: 我要把這包茶送給老師。","tw":"Hard pinyin: 打電話給你 dǎ diànhuà gěi nǐ — Taiwan puts 給+person after the verb; the mainland pattern is usually 給你打電話. Trad/simp: 沒 → 没, 間 → 间, 裡 → 里","src":"B1L11"},{"id":"n11-4","t":"會 · two meanings","e":"會 has two distinct meanings: 會₁ (from L5) is an acquired skill ('can'), while 會₂ (this lesson) means 'will / is likely to' about the future. Both negate the same way with 不會; a time word is the usual giveaway for 會₂.","pat":"會₁ (L5) = an acquired skill, \"can\". 會₂ (this lesson) = \"will / is likely to\". Same negation 不會 for both; context tells you which. A time word (明天, 週末, 等一下) is the usual giveaway for 會₂.","tgt":["會"],"alt":["要","想","能"],"s":[{"zh":"我會說中文。","en":"I can speak Chinese. (會₁ skill)","py":"wǒ huì shuō zhōng wén."},{"zh":"他不會打籃球。","en":"He can't play basketball. (會₁)","py":"tā bú huì dǎ lán qiú."},{"zh":"這個週末，我會去他家吃飯。","en":"This weekend I will go to his place to eat. (會₂ future/likely)","py":"zhè ge zhōu mò, wǒ huì qù tā jiā chī fàn."},{"zh":"他明天不會去上書法課。","en":"He won't be going to calligraphy class tomorrow. (會₂)","py":"tā míng tiān bú huì qù shàng shū fǎ kè."}],"cy":"Write two sentences using 會, one for skill (會₁) and one for future likelihood (會₂).","ov":"","tw":"Hard pinyin: 書法 shūfǎ — calligraphy. Trad/simp: 會 → 会, 週末 → 周末, 籃球 → 篮球, 書 → 书 (書法 same word both sides)","src":"B1L11"},{"id":"n11-5","t":"Omitting nouns · zero pronoun","e":"Once something is known from context or was just mentioned, it can be dropped: a predictable subject (e.g. 請進, obviously 'you'), or an object on its second mention. Leaving these in is a classic 'textbook Chinese' tell.","pat":"Once something is known from context or was just said, drop it. Two common cases: a predictable subject (請進 — obviously \"you\"), and an object on its second mention (我也常去). Leaving nouns in where a native speaker would drop them is one of the clearest \"textbook Chinese\" tells.","tgt":[],"alt":["你","它","這個"],"s":[{"zh":"歡迎，歡迎。來，來，來，(你)請進！","en":"Welcome, welcome! Come, come, come, (you) please come in!","py":"huān yíng, huān yíng. lái, lái, lái, ( nǐ ) qǐng jìn!"},{"zh":"他常去運動，我也常去(運動)。","en":"He often goes to exercise, I also often go (exercise).","py":"tā cháng qù yùn dòng, wǒ yě cháng qù ( yùn dòng )."}],"cy":"Write your own two-clause sentence where the second clause drops a repeated subject or object.","ov":"","tw":"","src":"B1L11"}],"12":[{"id":"n12-1","t":"先…，再… · first…, then…","e":"先 + VP1，再 + VP2 sequences two actions done by the same subject. 再 here means 'then/next', not 'again'. Both are adverbs and sit right before their verbs.","pat":"先 + VP₁，再 + VP₂. Sequence of two actions by the same subject. 再 here means \"then / next\", not \"again\". Both are adverbs, so they sit right before the verb.","tgt":["先","再"],"alt":["又","就","才"],"s":[{"zh":"今天早上她先買早餐，再去上課。","en":"This morning she first bought breakfast, then went to class.","py":"jīn tiān zǎo shàng tā xiān mǎi zǎo cān, zài qù shàng kè."},{"zh":"我先去學校上課，再去圖書館看書。","en":"I'll first go to school for class, then go to the library to read.","py":"wǒ xiān qù xué xiào shàng kè, zài qù tú shū guǎn kàn shū."}],"cy":"Write your own sentence using 先…，再… to sequence two actions.","ov":"","tw":"Hard pinyin: 先 xiān; 再 zài — here \"then/next\", not \"again\"; 早餐 zǎocān; 圖書館 túshūguǎn. Trad/simp: 圖書館 → 图书馆","src":"B1L12"},{"id":"n12-2","t":"S 是 + focus + V 的 · focusing a past event","e":"When a past event is already known and you want to highlight the who/when/where/how of it, put 是 right before that focus and 的 at the end of the sentence. Only used for past events, never for things that haven't happened yet.","pat":"The event already happened; what you're asking about or stressing is the who / when / where / how (誰／什麼時候／哪裡／怎麼). Put 是 right before that focus, 的 at the end. Past events only — never for something that hasn't happened yet. Teacher's wording: 說以前的事，不可以說以後的事。","tgt":["是...的"],"alt":["了","過","在"],"s":[{"zh":"昨天我是坐公車去學校的。","en":"Yesterday it was by bus that I went to school.","py":"zuó tiān wǒ shì zuò gōng chē qù xué xiào de."},{"zh":"學費是公司替我付的。","en":"It was the company that paid the tuition for me.","py":"xué fèi shì gōng sī tì wǒ fù de."},{"zh":"她是怎麼去的？","en":"How was it that she went?","py":"tā shì zěn me qù de?"},{"zh":"她是不是週末去的？","en":"Was it on the weekend that she went, or not?","py":"tā shì bú shì zhōu mò qù de?"},{"zh":"她是自己去的嗎？","en":"Was it by herself that she went?","py":"tā shì zì jǐ qù de ma?"},{"zh":"這杯咖啡是在哪裡買的？","en":"Where was it that (someone) bought this coffee?","py":"zhè bēi kā fēi shì zài nǎ lǐ mǎi de?"},{"zh":"你是在哪裡買這杯咖啡的？","en":"Where was it that you bought this coffee?","py":"nǐ shì zài nǎ lǐ mǎi zhè bēi kā fēi de?"}],"cy":"Write your own sentence using 是…的 to focus on the how/when/where/who of a past event.","ov":"Competition — 是…的 vs 了 (the finished-action 了, B1 L13). Both point at the past; they answer different questions. 你昨天去哪裡了？ — did it happen/what happened? The event itself is the news. 你昨天是怎麼去的？ — we both know you went; you're filling in the how/when/where/who. Minimal pair: 我坐公車去學校了 = I went to school by bus (reporting the trip). 我是坐公車去學校的 = it was by bus that I went (the going is old news). Test: if both of you already know the thing happened and you're only settling a detail, it's 是…的; if the event is the news, it's 了. They don't combine — ✗我是坐公車去的了。 The 了 family runs B1 L13 → B1 L14 → B2 L3; this is the one pattern that competes with it rather than joining it.","tw":"Hard pinyin: 公車 gōngchē — the Taiwan word for a city bus; mainland 公交車 gōngjiāochē, in Taiwan you also hear 搭公車; 學費 xuéfèi — tuition; 替 tì — on behalf of/for someone; 付 fù — to pay; 週末 zhōumò — Taiwan writes 週末, mainland writes 周末, same reading. In speech, 是 is often dropped (你哪裡買的？), 的 never is. Trad/simp: 費 → 费, 麼 → 么, 裡 → 里, 車 → 车","src":"B1L12"},{"id":"n12-3","t":"以後 / 以前 · time word and \"after / before X\"","e":"以後/以前 have two jobs: as a standalone time word meaning 'in the future/in the past', or attached after a time or event to mean 'after/before that'. Word order is reversed from English — the reference point comes first, then 以後/以前.","pat":"Two jobs. (a) Standalone time word = \"in the future / in the past\", placed before or after the subject. (b) Attached to a time or event = \"after / before that\": Time + 以後, VP + 以後. Note the word order is the reverse of English: the thing you're measuring from comes first, then 以後.","tgt":["以後","以前"],"alt":["後來","然後","之前"],"s":[{"zh":"以前，我不喜歡吃芒果。","en":"In the past, I didn't like eating mango. (time word)","py":"yǐ qián, wǒ bù xǐ huān chī máng guǒ."},{"zh":"以後她還想跟他們一起住嗎？","en":"In the future, will she still want to live with them?","py":"yǐ hòu tā hái xiǎng gēn tā men yì qǐ zhù ma?"},{"zh":"來臺灣以後，我喜歡吃芒果了。","en":"After coming to Taiwan, I've come to like eating mango.","py":"lái tái wān yǐ hòu, wǒ xǐ huān chī máng guǒ le."},{"zh":"九點以後，我開始上班。","en":"After nine o'clock, I start work.","py":"jiǔ diǎn yǐ hòu, wǒ kāi shǐ shàng bān."},{"zh":"他們六點半以後吃晚飯。","en":"They eat dinner after six thirty.","py":"tā men liù diǎn bàn yǐ hòu chī wǎn fàn."}],"cy":"Write your own sentence using 以後 or 以前, both as a standalone time word and attached after an event.","ov":"","tw":"Hard pinyin: 芒果 mángguǒ — mango; 臺灣 Táiwān — 臺 is the formal/official form used on documents here, 台灣 is what everyone actually writes; mainland 台湾. Trad/simp: 後 → 后, 還 → 还, 點 → 点, 開 → 开","src":"B1L12"},{"id":"n12-4","t":"好 / 難 + V · easy to / hard to","e":"好/難 + V forms a new state verb meaning 'good/easy to V' or 'hard to V', which then takes 很 and negates with 不. With sensory verbs, 好 means 'good to' (好吃, 好看); with action verbs, 好 means 'easy to' (好做, 好找).","pat":"好/難 + V makes a new state verb (Vs), so it takes 很 and is negated with 不: 不好找, 不難學. With sensory verbs (吃喝看聽) 好 = \"good to\": 好吃 tasty, 好看 good-looking. With action verbs 好 = \"easy to\": 好做 easy to make, 好找 easy to find.","tgt":["好+V","難+V"],"alt":["V起來","容易","難以"],"s":[{"zh":"這種衣服，我覺得很好看。","en":"I think these clothes look good.","py":"zhè zhǒng yī fú, wǒ jué de hěn hǎo kàn."},{"zh":"小籠包很好吃，可是很難做。","en":"Xiaolongbao is tasty, but hard to make.","py":"xiǎo lóng bāo hěn hǎo chī, kě shì hěn nán zuò."},{"zh":"水煮蛋很好做，小籠包很難做。","en":"A boiled egg is easy to make, xiaolongbao is hard to make.","py":"shuǐ zhǔ dàn hěn hǎo zuò, xiǎo lóng bāo hěn nán zuò."},{"zh":"好學／難學　好寫／難寫　好做／難做　好找／難找　好唱／難唱","en":"easy/hard to learn, write, make, find, sing (teacher's slide list)","py":"hào xué ／ nán xué hǎo xiě ／ nán xiě hǎo zuò ／ nán zuò hǎo zhǎo ／ nán zhǎo hǎo chàng ／ nán chàng"}],"cy":"Write your own sentence using 好+V or 難+V to say something is easy or hard to do.","ov":"Competition — 好／難 + V vs V起來 + Vs (B2 L1 point 2). Both turn a verb into a verdict about the thing, and in most sentences either sounds fine: 中文字好學嗎？／中文字學起來怎麼樣？ 這支筆好寫。／這支筆寫起來很不錯。 小籠包很難做。／小籠包做起來很麻煩。 What actually differs: 好／難+V IS the verdict — a finished Vs with only two settings, easy or hard, ready to take 很 and 不 (很好找、不難學). V起來 leaves the verdict slot empty — it only names the way you're judging, and you supply whatever Vs you want after it: 看起來很美、吃起來非常甜、穿起來很不舒服. So 好吃 is locked at \"good\", while 吃起來 can be followed by 甜、苦、鹹 — anything. Test: 這支筆好寫。 is complete; ✗這支筆寫起來。 is not. Don't stack them: ✗好吃起來. Both patterns take one-syllable verbs only (學、寫、做、找、吃、看).","tw":"Hard pinyin: 種 zhǒng — measure word, kind/type of; 小籠包 xiǎolóngbāo — soup dumplings, the Taipei specialty, simplified 小笼包; 水煮蛋 shuǐzhǔdàn — a boiled egg; 煮 zhǔ — to boil/cook. Trad/simp: 難 → 难, 學 → 学, 寫 → 写, 籠 → 笼","src":"B1L12"}],"13":[{"id":"n13-1","t":"一…，就… · as soon as","e":"一 + VP1，就 + VP2 says the second thing happens immediately or automatically right after the first. Subjects can be the same or different across the two clauses.","pat":"一 + VP₁，就 + VP₂. The second thing happens immediately or automatically after the first. Subjects can be the same or different (爸爸一到家，我們就…). Compare with V了…就 in L15, which is looser.","tgt":["一...就"],"alt":["V了...就","先...再","才"],"s":[{"zh":"我一有問題，就打電話給房東。","en":"As soon as I have a problem, I call the landlord.","py":"wǒ yī yǒu wèn tí, jiù dǎ diàn huà gěi fáng dōng."},{"zh":"爸爸一到家，我們就吃飯。","en":"As soon as Dad gets home, we eat.","py":"bà bà yī dào jiā, wǒ men jiù chī fàn."},{"zh":"他一到家，就睡覺。","en":"As soon as he gets home, he goes to sleep.","py":"tā yī dào jiā, jiù shuì jiào."},{"zh":"他們一到餐廳，就看菜單。","en":"As soon as they get to the restaurant, they look at the menu.","py":"tā men yī dào cān tīng, jiù kàn cài dān."}],"cy":"Write your own sentence using 一…，就… to describe something that happens immediately after another event.","ov":"Compare with V了…就 in L15, which is looser (merely sequential rather than immediate).","tw":"Hard pinyin: 一 yī — the base reading of this 一…就… 一; it still takes normal sandhi in speech: 一有 yì yǒu, 一到 yí dào; 房東 fángdōng — landlord; 菜單 càidān — menu. Trad/simp: 問題 → 问题, 電話 → 电话, 東 → 东, 覺 → 觉, 廳 → 厅, 單 → 单","src":"B1L13"},{"id":"n13-2","t":"V 了 / 沒 V · completed action","e":"S + V + 了 + O marks a single finished action. Negative is 沒 + V with no 了 (never 沒喝了). Two equivalent question forms exist: S+V(+O)+了嗎？ or S+V+了(+O)+沒有？ 了 is incompatible with habitual 常.","pat":"S + V + 了 + O for a finished action. Negative is 沒 + V with no 了 (沒喝, never 沒喝了). Two equivalent question forms: S + V (+O) + 了嗎？ or S + V + 了 (+O) + 沒有？","tgt":["V了"],"alt":["是...的","沒","不"],"s":[{"zh":"他吃了三個西瓜。","en":"He ate three watermelons.","py":"tā chī le sān gè xī guā."},{"zh":"小姐買了蘋果。","en":"The young woman bought apples.","py":"xiǎo jiě mǎi le píng guǒ."},{"zh":"我沒喝那杯咖啡。","en":"I didn't drink that coffee.","py":"wǒ méi hē nà bēi kā fēi."},{"zh":"我要買水果。→ 我買了水果。→ 我常買水果。→ ✗我常買了水果。","en":"I want to buy fruit (future) → I bought fruit (completed) → I often buy fruit (habitual) → ✗ungrammatical mixing of 了 with habitual 常.","py":"wǒ yào mǎi shuǐ guǒ. → wǒ mǎi le shuǐ guǒ. → wǒ cháng mǎi shuǐ guǒ. → ✗ wǒ cháng mǎi le shuǐ guǒ."},{"zh":"她買東西了嗎？= 她買了東西沒有？","en":"Did she buy things? (two equivalent question forms)","py":"tā mǎi dōng xī le ma? = tā mǎi le dōng xī méi yǒu?"},{"zh":"你今天喝咖啡了嗎？= 你今天喝了咖啡沒有？","en":"Did you drink coffee today? (two equivalent question forms)","py":"nǐ jīn tiān hē kā fēi le ma? = nǐ jīn tiān hē le kā fēi méi yǒu?"},{"zh":"明天我有事，不去上課。","en":"I have something on tomorrow, I won't go to class. (不 = intention)","py":"míng tiān wǒ yǒu shì, bù qù shàng kè."},{"zh":"他肚子很餓，因為他沒吃飯。","en":"He's very hungry because he didn't eat. (沒 = event didn't happen)","py":"tā dǔ zi hěn è, yīn wèi tā méi chī fàn."},{"zh":"他說中文不難。(✗他說中文沒難)","en":"He says Chinese isn't hard. (state verb takes 不, not 沒)","py":"tā shuō zhōng wén bù nán. ( ✗ tā shuō zhōng wén méi nán )"},{"zh":"他還沒決定放假去哪裡旅行。(✗他不決定...)","en":"He hasn't yet decided where to travel on vacation. (undecided event takes 還沒, not 不)","py":"tā hái méi jué dìng fàng jià qù nǎ lǐ lǚ xíng. ( ✗ tā bù jué dìng . . . )"}],"cy":"Write your own sentence using V了 for a completed action, and one using 沒V to negate it.","ov":"The 了 family — where this one sits (9/8): 咖啡貴了 (B1 L10 point 4) / 我買了水果 (here) / 我住了三年 (B1 L14 point 1) / 我住了三年了 (B1 L14 point 2) / 快下雨了 (B1 L14 point 3) / 我寫作業寫得差不多了 (B2 L3 point 1). Sort any 了 by where it sits: right after the verb = event finished or clock ran that long; end of sentence = situation changed. What's new here vs B1 L10: L10's 了 was end-of-sentence (change, no event); this lesson adds the verb-attached 了 that closes a single event. Everything in B1 L14 and B2 L3 combines these two. Trap: this L13 了 drops under 沒 (沒喝, never ✗沒喝了); the end-of-sentence one negates as 不…了 = \"not anymore\". The one pattern that competes with 了 instead of joining the family: 是…的 (B1 L12 point 2) — 我坐公車去學校了 (trip is the news) vs 我是坐公車去學校的 (bus is the news); they never combine — ✗我是坐公車去的了。","tw":"Hard pinyin: 西瓜 xīguā — watermelon, same word in Taiwan and mainland; 肚子 dùzi — stomach/belly; 決定 juédìng — to decide, negated with 沒 since it's an event; 放假 fàngjià — to have time off/a holiday; 旅行 lǚxíng — to travel. Trad/simp: 沒 → 没, 還 → 还, 飯 → 饭, 買 → 买, 蘋果 → 苹果, 個 → 个, 餓 → 饿, 決定 → 决定, 旅行 (same)","src":"B1L13"},{"id":"n13-3","t":"QW + 都 · all-inclusive","e":"A question word (誰/什麼/哪裡/什麼時候) + 都, or 怎麼 + V + 都, turns the question word into 'any-' (anyone/anything/anywhere/anytime/any way). In negatives, 都 or 也 both work.","pat":"什麼／誰／哪裡／什麼時候 + 都, or 怎麼 + V + 都. The question word stops being a question and means \"anything / anyone / anywhere / anytime / any way\". In negatives 都 or 也 both work (什麼都沒吃 = 什麼也沒吃).","tgt":["QW+都"],"alt":["不/沒+V+QW","也","才"],"s":[{"zh":"誰都喜歡收到生日禮物。(= 每一個人都喜歡)","en":"Everyone likes receiving birthday gifts.","py":"shéi dōu xǐ huān shōu dào shēng rì lǐ wù. ( = měi yí gè rén dōu xǐ huān )"},{"zh":"誰都喜歡漂亮的地方。","en":"Everyone likes pretty places.","py":"shéi dōu xǐ huān piào liàng de dì fāng."},{"zh":"台灣哪裡都有便利商店。","en":"There are convenience stores everywhere in Taiwan.","py":"tái wān nǎ li dōu yǒu biàn lì shāng diàn."},{"zh":"她什麼都想買。","en":"She wants to buy everything.","py":"tā shén me dōu xiǎng mǎi."},{"zh":"我什麼時候都有空。","en":"I'm free any time.","py":"wǒ shén me shí hòu dōu yǒu kòng."},{"zh":"你那麼漂亮，怎麼穿都好看！","en":"You're so pretty, you look good no matter how you dress!","py":"nǐ nà me piào liàng, zěn me chuān dōu hǎo kàn!"},{"zh":"我什麼都沒吃。","en":"I didn't eat anything.","py":"wǒ shén me dōu méi chī."},{"zh":"我哪裡都不想去。","en":"I don't want to go anywhere.","py":"wǒ nǎ li dōu bù xiǎng qù."},{"zh":"我怎麼坐都不舒服。","en":"No matter how I sit, I'm not comfortable.","py":"wǒ zěn me zuò dōu bù shū fú."}],"cy":"Write your own sentence using QW + 都 to say 'any-' something (anyone, anything, anywhere).","ov":"Contrast (L15): 不／沒 + V + QW = \"not much / nothing in particular\", the non-committal cousin of this all-inclusive pattern.","tw":"Hard pinyin: 收到 shōudào — to receive; 禮物 lǐwù — gift, same word Taiwan/mainland (simp. 礼物); 便利商店 biànlì shāngdiàn — Taiwan's standard word for convenience store, often shortened to 超商 chāoshāng; mainland says 便利店 biànlìdiàn; 有空 yǒu kòng — 空 is kòng \"free time\" here, not kōng \"empty\". Trad/simp: 誰 → 谁, 哪裡 → 哪里, 麼 → 么, 時候 → 时候, 禮物 → 礼物, 灣 → 湾, 歡 → 欢","src":"B1L13"},{"id":"n13-4","t":"多 / 少 + V + (一點) + O · more / less than usual","e":"多/少 goes before the verb (unlike English 'eat more'), with optional 一點 to soften. Common in giving advice: 你應該多…、少….","pat":"多/少 goes before the verb (not after, as in English \"eat more\"). 一點 is optional and softens it. Common in advice: 你應該多…、少…。","tgt":["多+V","少+V"],"alt":["V+多","V+少","一點"],"s":[{"zh":"週末我想多睡一點覺，少看一點書。","en":"On the weekend I want to sleep a bit more and read a bit less.","py":"zhōu mò wǒ xiǎng duō shuì yì diǎn jué, shǎo kàn yì diǎn shū."},{"zh":"他最近沒錢，應該少買東西。","en":"He's short on money lately, he should buy less stuff.","py":"tā zuì jìn méi qián, yīng gāi shǎo mǎi dōng xī."},{"zh":"他覺得很冷，他應該多穿(一點)衣服。","en":"He feels cold, he should wear a bit more clothing.","py":"tā jué de hěn lěng, tā yīng gāi duō chuān ( yì diǎn ) yī fú."}],"cy":"Write your own sentence using 多+V or 少+V to give advice.","ov":"","tw":"Trad/simp: 點 → 点, 錢 → 钱, 應該 → 应该","src":"B1L13"},{"id":"n13-5","t":"…，是不是…？ · seeking confirmation","e":"是不是 placed in front of the guess you want confirmed means 'is it that…?' / 'right?' — unlike the neutral question particle 嗎, 是不是 already has an answer in mind.","pat":"是不是 in front of the guess you want confirmed = \"is it that…?\" / \"right?\". Different from 嗎, which is a neutral question; 是不是 already has an answer in mind.","tgt":["是不是"],"alt":["嗎","對不對","好不好"],"s":[{"zh":"你不想跟我出去，是不是不喜歡我？","en":"You don't want to go out with me — is it that you don't like me?","py":"nǐ bù xiǎng gēn wǒ chū qù, shì bú shì bù xǐ huān wǒ?"},{"zh":"她是不是週末去的？","en":"Wasn't it on the weekend that she went?","py":"tā shì bú shì zhōu mò qù de?"}],"cy":"Write your own sentence using 是不是 to seek confirmation of a guess.","ov":"","tw":"","src":"B1L13"},{"id":"n13-6","t":"A 跟 B 一樣 (+ Vs / VP) · the same as","e":"A 跟 B 一樣 says A is the same as B; adding a state verb after 一樣 specifies in what way (一樣高, 一樣好喝). The two negative forms differ: A跟B不一樣 means they differ, while A不跟B一樣 means A matches something else instead.","pat":"A 跟 B 一樣 = A is the same as B. Add a Vs after 一樣 to say in what way: 一樣高, 一樣好喝. Two negatives with different meanings: A 跟 B 不一樣 (they differ) vs A 不跟 B 一樣 (A matches something else, not B).","tgt":["跟...一樣"],"alt":["比...更","沒有...那麼","和"],"s":[{"zh":"爸爸的衣服跟弟弟的一樣。","en":"Dad's clothes are the same as younger brother's.","py":"bà bà de yī fú gēn dì di de yī yàng."},{"zh":"他的手機跟我的一樣。","en":"His phone is the same as mine.","py":"tā de shǒu jī gēn wǒ de yī yàng."},{"zh":"左邊的大樓跟右邊的大樓一樣高。","en":"The building on the left is as tall as the one on the right.","py":"zuǒ biān de dà lóu gēn yòu biān de dà lóu yī yàng gāo."},{"zh":"這種紅茶跟我常喝的紅茶一樣好喝。","en":"This kind of black tea tastes as good as the black tea I usually drink.","py":"zhè zhǒng hóng chá gēn wǒ cháng hē de hóng chá yī yàng hǎo hē."},{"zh":"豬腳麵線跟蛋糕一樣，都是生日的時候吃的東西。","en":"Pig's-feet noodles and cake are alike — both are things eaten on birthdays.","py":"zhū jiǎo miàn xiàn gēn dàn gāo yī yàng, dōu shì shēng rì de shí hòu chī de dōng xī."},{"zh":"星期一跟星期二不一樣熱，星期一比較熱。","en":"Monday and Tuesday aren't equally hot — Monday is hotter. (totally different)","py":"xīng qī yī gēn xīng qī èr bù yí yàng rè, xīng qī yī bǐ jiào rè."},{"zh":"星期一不跟星期二一樣熱，跟星期三一樣熱。","en":"Monday isn't as hot as Tuesday, it's as hot as Wednesday. (matches something else instead)","py":"xīng qī yī bù gēn xīng qī èr yī yàng rè, gēn xīng qī sān yī yàng rè."}],"cy":"Write your own sentence using A跟B一樣(+Vs) to compare two things as equal.","ov":"Where this goes next — the comparison ladder (9/8): 跟…一樣 is rung one, and the rest of Book 1 just changes what hangs on the end: 安同跟月美一樣高 (here, equal) → 安同沒有月美那麼高 (B1 L14 point 5, less) → 安同比月美高 (B1 L14, more) → 安同比月美更高 (B1 L14 point 4, even more) → 安同比月美高一點／多了 (B1 L15 point 5, by how much). The frame never changes; only the tail does. Trap that carries across all of them: never put 很 in front of the Vs in a 比 sentence — ✗安同比月美很高. The degree word goes after the Vs (B1 L15 point 5).","tw":"跟 is the default linker here; mainland speech often uses 和. The teacher's own example, 豬腳麵線 zhūjiǎo miànxiàn, is Taiwan-only pig-trotter thin noodles, the traditional Taiwanese birthday dish eaten to wash away bad luck — no mainland equivalent, where birthday noodles are 長壽麵 chángshòumiàn. Hard pinyin: 手機 shǒujī — mobile phone, everyday word both sides (Taiwan's formal/official term is 行動電話 xíngdòng diànhuà, simp. 移动电话); 大樓 dàlóu — multi-storey building; 紅茶 hóngchá — black tea; 蛋糕 dàngāo — cake. Trad/simp: 樣 → 样, 邊 → 边, 樓 → 楼, 紅 → 红, 熱 → 热, 較 → 较, 機 → 机, 種 → 种, 這 → 这, 豬腳麵線 → 猪脚面线, 長壽麵 → 长寿面","src":"B1L13"}],"14":[{"id":"n14-1","t":"V 了 + time duration · how long something lasted","e":"The verb takes 了 and a duration expression right after it to say how long an action lasted; if there's an object, either repeat the verb or put the duration before the object with 的.","pat":"V 了 + duration (units: 分鐘, 鐘頭/小時, 天, 個星期, 個月, 年)","tgt":["了"],"alt":["過","在","著"],"s":[{"zh":"昨天外面下了一天的雨。","en":"It rained outside for a whole day yesterday.","py":"zuó tiān wài miàn xià le yī tiān de yǔ."},{"zh":"週末我們看電影看了三個鐘頭。","en":"We watched a movie for three hours over the weekend.","py":"zhōu mò wǒ men kàn diàn yǐng kàn le sān gè zhōng tóu."},{"zh":"他們去紐約玩了10天。","en":"They went to New York and stayed for 10 days.","py":"tā men qù niǔ yuē wán le 1 0 tiān."},{"zh":"他在美國住了10年。","en":"He lived in America for 10 years.","py":"tā zài měi guó zhù le 1 0 nián."},{"zh":"他在臺灣住了3年9個月。","en":"He lived in Taiwan for 3 years and 9 months.","py":"tā zài tái wān zhù le 3 nián 9 gè yuè."}],"cy":"Write a sentence saying how long you did something, using V 了 + duration.","ov":"First stop in the 了 family this lesson — see point 2's callout for the full spiral: B1 L10 (situation-change 了) → B1 L13 (finished-event 了) → this point (duration, action over) → point 2 (double 了, still going) → point 3 (快…了, about to happen) → B2 L3 (V得差不多了, nearly done).","tw":"Trad/simp: 鐘頭 → 钟头, 紐約 → 纽约, 國 → 国. Taiwan note: 鐘頭 zhōngtóu (colloquial 'hour') and 小時 are both common in Taiwan; mainland prefers 小時 xiǎoshí.","src":"B1L14"},{"id":"n14-2","t":"V 了 + duration + 了 · still going on","e":"Adding a second, sentence-final 了 after V了+duration turns a closed-off past stretch of time into one that continues up to right now — the single most testable point in the lesson.","pat":"S + (VO) + V 了 + duration + 了 — one 了 = closed period in the past; two 了 = the stretch reaches today","tgt":["了"],"alt":["過","已經","著"],"s":[{"zh":"我學中文學了半年了。","en":"I've been studying Chinese for half a year (and still am).","py":"wǒ xué zhōng wén xué le bàn nián le."},{"zh":"他旅行了一個星期了。","en":"He's been traveling for a week (and still is).","py":"tā lǚ xíng le yí gè xīng qī le."},{"zh":"我在台北住了三年。","en":"I lived in Taipei for three years. (implies: not anymore)","py":"wǒ zài tái běi zhù le sān nián."},{"zh":"我(已經)在台北住了三年了。","en":"I've (already) lived in Taipei for three years (and still do).","py":"wǒ ( yǐ jīng ) zài tái běi zhù le sān nián le."},{"zh":"他們學唱歌學了多久了？","en":"How long have they been learning to sing (and still are)?","py":"tā men xué chàng gē xué le duō jiǔ le?"}],"cy":"Write a sentence with V 了 + duration + 了 describing something you've been doing that's still ongoing.","ov":"The 了 family — three of its jobs land in this one lesson (9/8): 咖啡貴了 (B1 L10, situation changed) → 我買了水果 (B1 L13, one event finished) → 我住了三年 (point 1 here, how long it ran, and it's over) → 我住了三年了 (this point, and I still live there) → 快下雨了 (point 3 here, about to change) → 我寫得差不多了 (B2 L3, nearly done). Sorting test: where does 了 sit? On the verb = finished/duration; sentence-final = situation changed; one of each = a stretch reaching today. What changed from B1 L13: that 了 just closes an event; here it gets a duration bolted on, and the sentence-final 了 drags that stretch up to the present. 住了三年 (moved out) vs 住了三年了 (still there) is the whole exam question.","tw":"Trad/simp: 學 → 学, 已經 → 已经. Taiwan note: 星期 is read xīngqí in Taiwan (2nd-tone qí) vs mainland xīngqī.","src":"B1L14"},{"id":"n14-3","t":"快 / 要 / 快要 … 了 · about to","e":"快, 要, and 快要 are interchangeable markers placed before a verb phrase, with sentence-final 了, to say something is about to happen — this 了 signals imminent change, not a completed action.","pat":"快／要／快要 + VP + 了 = something is about to happen (all three interchangeable)","tgt":["快","要","快要"],"alt":["已經","在","過"],"s":[{"zh":"快中午了！","en":"It's almost noon!","py":"kuài zhōng wǔ le!"},{"zh":"快可以吃飯了！","en":"We can eat soon!","py":"kuài kě yǐ chī fàn le!"},{"zh":"外面的風很大，大概快下雨了。","en":"The wind outside is strong, it's probably about to rain.","py":"wài miàn de fēng hěn dà, dà gài kuài xià yǔ le."},{"zh":"快下雨了。","en":"It's about to rain.","py":"kuài xià yǔ le."},{"zh":"要下雨了。","en":"It's going to rain.","py":"yào xià yǔ le."},{"zh":"快要下雨了。","en":"It's about to rain.","py":"kuài yào xià yǔ le."},{"zh":"因為那個家的人快回來了！","en":"Because that family's people are about to come back!","py":"yīn wèi nà ge jiā de rén kuài huí lái le!"},{"zh":"我快到了！","en":"I'm almost there!","py":"wǒ kuài dào le!"}],"cy":"Write a sentence using 快/要/快要…了 to say something is about to happen.","ov":"Fourth appearance of 了 in this lesson's family (see point 2) — this is the sentence-final 'change is coming' 了, distinct from the completed-action/duration 了 in points 1–2.","tw":"Trad/simp: 風 → 风, 來 → 来.","src":"B1L14"},{"id":"n14-4","t":"A 比 B 更 + Vs · even more","e":"更 inserted into a 比 comparison says A is even more Vs than B, presupposing that B is already quite Vs; without 更, 比 just states A > B.","pat":"A 比 B 更 Vs = even more Vs (presupposes B is already Vs)","tgt":["更"],"alt":["很","比較","非常"],"s":[{"zh":"妹妹的房間很大，可是我的房間比妹妹的更大。","en":"My sister's room is big, but mine is even bigger than hers.","py":"mèi mèi de fáng jiān hěn dà, kě shì wǒ de fáng jiān bǐ mèi mèi de gèng dà."},{"zh":"他很高，他姐姐比他更高。","en":"He's tall, but his older sister is even taller than him.","py":"tā hěn gāo, tā jiě jiě bǐ tā gèng gāo."},{"zh":"上次的颱風很可怕。這次的颱風比上次的更可怕。","en":"Last time's typhoon was scary. This one is even scarier than last time's.","py":"shàng cì de tái fēng hěn kě pà. zhè cì de tái fēng bǐ shàng cì de gèng kě pà."}],"cy":"Write a sentence using A 比 B 更 Vs to say A is even more [adjective] than B.","ov":"Fourth rung of the comparison ladder (see point 5's callout): 跟…一樣 (B1 L13, equal) → 沒有…這麼 (point 5 here, less) → 比 (more) → 比…更 (this point, even more) → 比…得多／多了 (B1 L15, by how much).","tw":"Trad/simp: 颱風 → 台风. Taiwan note: 颱風 is the everyday word for typhoon in Taiwan daily life; written 台风 on the mainland.","src":"B1L14"},{"id":"n14-5","t":"Comparing actions: VOV 得 比 … / 沒有 … 這麼","e":"To compare how well two people do an action, repeat the verb and hang the comparison on 得 (VOV得比). To say A isn't as Vs as B, use 沒有 (這麼／那麼) — the negative of 比. These fill out the four-way comparison ladder: 跟…一樣 (equal) / 沒有 (less) / 比 (more) / 比…更 (even more).","pat":"(a) S₁ VOV 得比 S₂ Vs. (b) A 沒有 B (這麼／那麼) Vs = A is not as Vs as B","tgt":["沒有","得"],"alt":["不比","很","一樣"],"s":[{"zh":"他吃飯吃得比我多。","en":"He eats more than I do.","py":"tā chī fàn chī dé bǐ wǒ duō."},{"zh":"我寫中文字寫得比他好。","en":"I write Chinese characters better than he does.","py":"wǒ xiě zhōng wén zì xiě dé bǐ tā hǎo."},{"zh":"張小姐有沒有陳小姐這麼／那麼高？","en":"Is Miss Zhang as tall as Miss Chen?","py":"zhāng xiǎo jiě yǒu méi yǒu chén xiǎo jiě zhè me ／ nà me gāo?"},{"zh":"張小姐沒有陳小姐這麼高。","en":"Miss Zhang is not as tall as Miss Chen.","py":"zhāng xiǎo jiě méi yǒu chén xiǎo jiě zhè me gāo."},{"zh":"張小姐沒陳小姐高。","en":"Miss Zhang is not as tall as Miss Chen. (short form)","py":"zhāng xiǎo jiě méi chén xiǎo jiě gāo."},{"zh":"騎機車沒有開車舒服。","en":"Riding a scooter is not as comfortable as driving.","py":"qí jī chē méi yǒu kāi chē shū fú."},{"zh":"騎機車跟開車一樣舒服。","en":"Riding a scooter is just as comfortable as driving. (equal, contrast)","py":"qí jī chē gēn kāi chē yī yàng shū fú."},{"zh":"騎機車比開車舒服。","en":"Riding a scooter is more comfortable than driving. (more)","py":"qí jī chē bǐ kāi chē shū fú."},{"zh":"騎機車比較舒服。","en":"Riding a scooter is more comfortable. (shortcut, B side dropped)","py":"qí jī chē bǐ jiào shū fú."},{"zh":"坐飛機比開車更舒服。","en":"Taking a plane is even more comfortable than driving. (even more)","py":"zuò fēi jī bǐ kāi chē gèng shū fú."}],"cy":"Write two sentences: one with VOV得比 comparing how well someone does something, one with 沒有…這麼 saying A isn't as Vs as B.","ov":"Completes the B1 L14 comparison ladder alongside point 4: 跟…一樣 (B1 L13, equal) → 沒有…這麼 (this point, less) → 比 (more) → 比…更 (point 4, even more). B1 L15 point 5 adds the final rung: 比…一點／很多／得多／多了 (by how much).","tw":"Trad/simp: 沒 → 没, 騎機車 → 骑机车. Taiwan note: 機車 jīchē is the Taiwan word for scooter/motorbike (mainland says 摩托車 mótuōchē; as slang 機車 also means 'annoying'). 張/陳 simplify to 张/陈 — 陳 is the most common surname in Taiwan.","src":"B1L14"}],"15":[{"id":"n15-1","t":"不 / 沒 + V + QW · non-committal","e":"Putting a question word (什麼/多少/哪裡/幾個) after a negated verb turns it into a vague, deflecting answer — 'not much / not anywhere in particular' — rather than a real question.","pat":"不／沒 + V + 什麼／多少／哪裡／幾個","tgt":["沒","不"],"alt":["都","也","什麼都"],"s":[{"zh":"大家都說他的工作很好，但是他真的沒什麼錢。","en":"Everyone says his job is great, but he really doesn't have much money.","py":"dà jiā dōu shuō tā de gōng zuò hěn hǎo, dàn shì tā zhēn de méi shén me qián."},{"zh":"上個週末我很不舒服，所以沒吃多少東西。","en":"I felt unwell last weekend, so I didn't eat much.","py":"shàng gè zhōu mò wǒ hěn bù shū fú, suǒ yǐ méi chī duō shǎo dōng xī."},{"zh":"妳有多少錢？我沒有多少錢。","en":"How much money do you have? Not much.","py":"nǐ yǒu duō shǎo qián? wǒ méi yǒu duō shǎo qián."},{"zh":"你們說了什麼？我們沒說什麼。","en":"What did you all say? Not much.","py":"nǐ men shuō le shén me? wǒ men méi shuō shén me."},{"zh":"你在看什麼？我沒看什麼。","en":"What are you looking at? Nothing much.","py":"nǐ zài kàn shén me? wǒ méi kàn shén me."},{"zh":"我不想去哪裡。","en":"I don't particularly want to go anywhere.","py":"wǒ bù xiǎng qù nǎ lǐ."},{"zh":"我什麼都喜歡吃。","en":"I like eating everything. (all-inclusive, contrast)","py":"wǒ shén me dōu xǐ huān chī."}],"cy":"Write a sentence using 不/沒 + V + QW to give a vague, non-committal answer.","ov":"Competes with B1 L13's QW + 都 (all-inclusive): 我什麼都沒吃 (ate nothing at all) vs 我沒吃什麼 (didn't eat much, vague deflection). Choosing wrong changes the meaning from total exclusion to a soft dodge.","tw":"Trad/simp: 錢 → 钱, 麼 → 么, 沒 → 没, 幾 → 几.","src":"B1L15"},{"id":"n15-2","t":"S 把 O V 了 · disposal","e":"把 pulls the object in front of the verb to focus on what happened to it (it got eaten, sold, drunk); the object must be definite, and the verb needs something after it — here, 了.","pat":"S + 把 + O + V + 了","tgt":["把"],"alt":["被","一","的"],"s":[{"zh":"誰把我買的咖啡喝了？","en":"Who drank the coffee I bought?","py":"shuí bǎ wǒ mǎi de kā fēi hē le?"},{"zh":"房東要把房子賣了，所以我得找一個新房子。","en":"The landlord is going to sell the house, so I have to find a new place.","py":"fáng dōng yào bǎ fáng zi mài le, suǒ yǐ wǒ dé zhǎo yí gè xīn fáng zi."},{"zh":"我吃了西瓜。","en":"I ate watermelon. (fact, contrast)","py":"wǒ chī le xī guā."},{"zh":"我把西瓜吃了。","en":"I ate up the watermelon. (it's gone)","py":"wǒ bǎ xī guā chī le."},{"zh":"弟弟把我的咖啡喝了。","en":"My little brother drank my coffee.","py":"dì di bǎ wǒ de kā fēi hē le."},{"zh":"我想把手機賣了。","en":"I want to sell the phone. (✓ definite)","py":"wǒ xiǎng bǎ shǒu jī mài le."},{"zh":"我想把那支手機賣了。","en":"I want to sell that phone. (✓ definite)","py":"wǒ xiǎng bǎ nà zhī shǒu jī mài le."},{"zh":"我想把一支手機賣了。","en":"✗ ungrammatical — 一支手機 is indefinite, which fails after 把.","py":"wǒ xiǎng bǎ yī zhī shǒu jī mài le."}],"cy":"Write a sentence using 把 to say what happened to a specific (definite) object.","ov":"First door into 把; directly extended in B2 L6 (current class lesson), where the pattern becomes A 把 B + V + 到／在／給 + location/person (把書放在桌子上, 把錢給他, 把東西搬到樓下). The definiteness rule for O carries over unchanged.","tw":"Trad/simp: 賣 → 卖, 東 → 东, 機 → 机.","src":"B1L15"},{"id":"n15-3","t":"V 了 … (以後)，就 … · after doing X, then Y","e":"了 attaches right after the first verb (before its object), and 就 introduces what happens next — a sequence, not necessarily an immediate one.","pat":"V₁ 了 (O) (以後)，就 V₂","tgt":["了","就"],"alt":["一","才","以後"],"s":[{"zh":"請你等一下，我下了課，就去找你。","en":"Please wait a moment — once I finish class, I'll come find you.","py":"qǐng nǐ děng yí xià, wǒ xià le kè, jiù qù zhǎo nǐ."},{"zh":"他每天晚上吃了飯，就到樓下運動。","en":"Every night after he eats, he goes downstairs to exercise.","py":"tā měi tiān wǎn shàng chī le fàn, jiù dào lóu xià yùn dòng."},{"zh":"他吃了飯以後，就吃藥。","en":"After he eats, he takes medicine.","py":"tā chī le fàn yǐ hòu, jiù chī yào."},{"zh":"他吃了藥以後，就睡覺。","en":"After he takes medicine, he goes to sleep.","py":"tā chī le yào yǐ hòu, jiù shuì jiào."},{"zh":"她是不是寫了功課以後，就吃飯？","en":"Does she eat after finishing her homework?","py":"tā shì bú shì xiě le gōng kè yǐ hòu, jiù chī fàn?"},{"zh":"我一吃藥，就去睡覺。","en":"As soon as I take medicine, I go to sleep. (immediate, contrast)","py":"wǒ yī chī yào, jiù qù shuì jiào."},{"zh":"我吃了藥，就去睡覺。","en":"After I took the medicine, I went to sleep. (sequential, not necessarily immediate)","py":"wǒ chī le yào, jiù qù shuì jiào."}],"cy":"Write a sentence using V了…就… to describe what you do right after finishing something.","ov":"Competes with B1 L13's 一…就… (immediate): 我一吃藥，就去睡覺 (right now, immediately) vs 我吃了藥，就去睡覺 (after, not necessarily immediately). Same 就, different first half changes the timing.","tw":"Trad/simp: 後 → 后, 樓 → 楼, 藥 → 药, 覺 → 觉. Taiwan note: 藥局 yàojú is Taiwan's word for pharmacy (not mainland 藥店/藥房); 功課 gōngkè is Taiwan's normal word for homework (mainland usually 作業).","src":"B1L15"},{"id":"n15-4","t":"一點 vs 有一點","e":"一點 has three distinct jobs depending on position: after a verb before a noun it's 'a small amount of'; after an adjective it's 'a bit more' (neutral/positive); moved in front of the adjective as 有一點 it becomes a mild complaint ('a bit too').","pat":"V + 一點 + N (a small amount) / Vs + 一點 (a bit more) / 有一點 + Vs (a bit too, complaint)","tgt":["一點","有一點"],"alt":["有點","一些","很"],"s":[{"zh":"今天很熱，我想喝一點冰的東西。","en":"It's hot today, I want to drink something a little cold.","py":"jīn tiān hěn rè, wǒ xiǎng hē yì diǎn bīng de dōng xī."},{"zh":"我不舒服，得吃一點藥。","en":"I'm not feeling well, I need to take a little medicine.","py":"wǒ bù shū fú, dé chī yì diǎn yào."},{"zh":"我喝了一點珍珠奶茶，現在覺得開心一點了。","en":"I drank a little bubble tea, and now I feel a bit happier.","py":"wǒ hē le yì diǎn zhēn zhū nǎi chá, xiàn zài jué de kāi xīn yì diǎn le."},{"zh":"我喜歡苦一點的。","en":"I like it a bit more bitter.","py":"wǒ xǐ huān kǔ yì diǎn de."},{"zh":"甜一點的，更好。","en":"A bit sweeter would be even better.","py":"tián yì diǎn de, gèng hǎo."},{"zh":"我想喝熱一點的咖啡。","en":"I want to drink slightly hotter coffee.","py":"wǒ xiǎng hē rè yì diǎn de kā fēi."},{"zh":"那杯咖啡有一點大，你能幫我喝嗎？","en":"That coffee is a bit too much, can you help me drink it?","py":"nà bēi kā fēi yǒu yì diǎn dà, nǐ néng bāng wǒ hē ma?"},{"zh":"我覺得紅茶有一點甜。","en":"I think the black tea is a bit too sweet. (complaint)","py":"wǒ jué de hóng chá yǒu yì diǎn tián."},{"zh":"紅茶，我要甜一點。","en":"For the black tea, I'd like it a bit sweeter. (request)","py":"hóng chá, wǒ yào tián yì diǎn."},{"zh":"這個衣服有一點貴。","en":"These clothes are a bit too expensive.","py":"zhè ge yī fú yǒu yì diǎn guì."},{"zh":"這個衣服比那個衣服貴一點。","en":"These clothes are a little more expensive than those.","py":"zhè ge yī fú bǐ nà ge yī fú guì yì diǎn."},{"zh":"外面有一點黑，應該要下雨了。","en":"It's a bit dark outside, it's probably going to rain.","py":"wài miàn yǒu yì diǎn hēi, yīng gāi yào xià yǔ le."}],"cy":"Write two sentences: one using V + 一點 + N and one using 有一點 + Vs as a mild complaint.","ov":"Extended in B2 L2: the Vs+一點 half becomes a command, V + Vs + 一點 (請說慢一點, 吃快一點!) — same 'a bit more' meaning, now aimed at telling someone to act differently. The 有一點 complaint half does NOT travel there (✗請說有一點慢).","tw":"Trad/simp: 點 → 点, 熱 → 热, 開 → 开, 貴 → 贵. Taiwan note: 有點 is commonly heard as the short form of 有一點 (有點貴).","src":"B1L15"},{"id":"n15-5","t":"A 比 B + Vs + 一點 / 很多 / 得多 / 多了 · by how much","e":"Adding a degree word after the adjective in a 比 comparison says by how much A exceeds B, on a scale from slight to large.","pat":"A 比 B Vs + 一點／很多／得多／多了 — scale: 一點 < 很多 ≈ 得多 < 多了","tgt":["一點","很多","得多"],"alt":["很","更","非常"],"s":[{"zh":"右邊的珍珠奶茶比左邊的貴一點。","en":"The bubble tea on the right is a little more expensive than the one on the left. (35 vs 45 元)","py":"yòu biān de zhēn zhū nǎi chá bǐ zuǒ biān de guì yì diǎn."},{"zh":"安同比月美高一點。","en":"Antong is a little taller than Yuemei. (160 vs 153)","py":"ān tóng bǐ yuè měi gāo yì diǎn."},{"zh":"安同比月美高很多／得多。","en":"Antong is much taller than Yuemei. (170 vs 150)","py":"ān tóng bǐ yuè měi gāo hěn duō ／ dé duō."},{"zh":"安同比月美高多了。","en":"Antong is a lot taller than Yuemei. (190 vs 150)","py":"ān tóng bǐ yuè měi gāo duō le."},{"zh":"臺北101比我的學校高多了。","en":"Taipei 101 is way taller than my school.","py":"tái běi 1 0 1 bǐ wǒ de xué xiào gāo duō le."},{"zh":"從我家去學校比去銀行近得多。","en":"Going to school from my house is much closer than going to the bank.","py":"cóng wǒ jiā qù xué xiào bǐ qù yín háng jìn dé duō."}],"cy":"Write a sentence using A 比 B + Vs + 一點/很多/得多/多了 to say by how much A exceeds B.","ov":"Final rung of the comparison ladder: 跟…一樣 (B1 L13, equal) → 沒有…這麼 / 比…更 (B1 L14, less / even more) → this point (by how much). One frame, five settings across three lessons.","tw":"Trad/simp: 邊 → 边, 銀 → 银. Taiwan note: 臺北 is the formal/official variant of 台北, used officially in Taiwan. 銀行's 行 is read háng here, not xíng.","src":"B1L15"},{"id":"n15-6","t":"Note · Separable verbs (textbook VII)","e":"Some verb-object compounds (like 睡覺, 看病) split apart when 了, a duration, or a measure word needs to go in the middle — the insert goes between V and O, not after the whole compound.","pat":"VO compound splits: V + 了／duration／measure + O","tgt":["睡覺","看病"],"alt":["睡覺了","看病了"],"s":[{"zh":"睡覺 → 睡了八個小時的覺","en":"to sleep → slept for eight hours","py":"shuì jiào → shuì le bā gè xiǎo shí de jué"},{"zh":"看病 → 看了病","en":"to see a doctor → saw a doctor","py":"kàn bìng → kàn le bìng"},{"zh":"發燒、生病、感冒、上課、唱歌、吃飯","en":"run a fever, get sick, catch a cold, attend class, sing, eat — all separable (V-SEP) verbs","py":"fā shāo, shēng bìng, gǎn mào, shàng kè, chàng gē, chī fàn"},{"zh":"睡了三個小時的覺","en":"slept for three hours","py":"shuì le sān gè xiǎo shí de jué"},{"zh":"上了兩堂課","en":"attended two class periods","py":"shàng le liǎng táng kè"}],"cy":"Write a sentence using a separable verb (like 睡覺 or 上課) with 了 or a duration inserted in the middle.","ov":"","tw":"","src":"B1L15"}],"16":[{"id":"n16-1","t":"從 Place 往 Direction + V · from X, go toward Y","e":"從 marks the starting point and 往 marks the direction to head (前/後/左/右/外/北, etc.) before the motion verb; 就 in the following clause means 'and then you're there'.","pat":"從 + starting point, 往 + direction, + motion verb (往前走, 往右轉, 過馬路)","tgt":["從","往"],"alt":["到","在","離"],"s":[{"zh":"你從這裡往前走，就到學校了。","en":"Go straight ahead from here, and you'll reach the school.","py":"nǐ cóng zhè lǐ wǎng qián zǒu, jiù dào xué xiào le."},{"zh":"從旅館的窗戶(裡面)往外看，有藍色的海。","en":"Looking out from inside the hotel window, there's a blue sea.","py":"cóng lǚ guǎn de chuāng hù ( lǐ miàn ) wǎng wài kàn, yǒu lán sè de hǎi."},{"zh":"從這裡往前走，就有一家超商。","en":"Go straight ahead from here, and there's a convenience store.","py":"cóng zhè lǐ wǎng qián zǒu, jiù yǒu yī jiā chāo shāng."}],"cy":"Write a sentence using 從…往… to give directions from a starting point toward a direction.","ov":"Extended in B2 L6: here it's 從 + start + 往 + direction + V (從這裡往前走 — which way to head, no endpoint named). In B2 L6 it becomes 從 + start + V + 到 + endpoint (從台北騎到花蓮 — where you ended up, direction not named). 往 answers 'which way?', 到 answers 'and got where?' — don't swap them (✗從這裡到前走, ✗從台北騎往花蓮).","tw":"Trad/simp: 從 → 从, 館 → 馆, 戶 → 户, 藍 → 蓝, 轉 → 转. Taiwan note: 超商 chāoshāng (short for 便利商店) is Taiwan-only for convenience store; mainland says 便利店. 窗戶's 戶 gets a full 4th tone in Taiwan vs a neutralized one on the mainland. Taipei addresses read 路→段→巷→弄→號.","src":"B2L1"},{"id":"n16-2","t":"V 起來 + Vs · judging by doing","e":"V起來 names the sense you're using to judge something (看起來 looks, 吃起來 tastes, 聽起來 sounds) and the Vs after it gives the verdict; restricted to one-syllable verbs.","pat":"V + 起來 + (不) Vs — one-syllable verbs only (看/聽/喝/吃/聞/摸/笑/坐/穿/寫/說/念/學/住/逛/走)","tgt":["起來"],"alt":["得","著","過"],"s":[{"zh":"這支筆寫／用起來很不錯。","en":"This pen is quite good to write/use with.","py":"zhè zhī bǐ xiě ／ yòng qǐ lái hěn bú cuò."},{"zh":"他做的蛋糕吃起來非常甜。","en":"The cake he made tastes very sweet.","py":"tā zuò de dàn gāo chī qǐ lái fēi cháng tián."},{"zh":"高跟鞋看起來很美，可是穿起來很不舒服。","en":"High heels look beautiful, but they're uncomfortable to wear.","py":"gāo gēn xié kàn qǐ lái hěn měi, kě shì chuān qǐ lái hěn bù shū fú."},{"zh":"這杯咖啡看起來不苦，可是喝起來非常苦。","en":"This coffee doesn't look bitter, but it tastes very bitter.","py":"zhè bēi kā fēi kàn qǐ lái bù kǔ, kě shì hē qǐ lái fēi cháng kǔ."},{"zh":"聽起來不難，做起來很難。","en":"It sounds easy, but it's hard to do.","py":"tīng qǐ lái bù nán, zuò qǐ lái hěn nán."}],"cy":"Write a sentence using V起來+Vs to say how something seems based on doing/experiencing it.","ov":"Connects back to B1 L12 point 4 (好／難 + V): 中文字學起來怎麼樣？ = 中文字好學嗎？ — same job (judging how a verb goes), different shape. 好／難+V is itself the verdict with only two settings (easy/hard); V起來 only names the way you're judging and leaves the verdict open to any Vs (吃起來 can be 甜/苦/鹹, while 好吃 is locked at 'good'). Test: 這支筆好寫 stands alone; ✗這支筆寫起來 does not — it's still waiting for a Vs. Don't stack them: ✗好吃起來.","tw":"Trad/simp: 來 → 来, 筆 → 笔, 錯 → 错, 聽 → 听.","src":"B2L1"},{"id":"n16-3","t":"V 著 · ongoing state","e":"著 attached to a verb marks a state that continues after the action completes (standing, seated, holding, wearing) — contrast with 在+V, which is the action still in progress.","pat":"V + 著 = ongoing state (站著, 坐著, 拿著, 穿著, 開著); V+著+O+VP = doing VP while in that state","tgt":["著"],"alt":["在","了","過"],"s":[{"zh":"搭捷運的時候，他喜歡站著。","en":"When taking the MRT, he likes to stand.","py":"dā jié yùn de shí hòu, tā xǐ huān zhàn zhù."},{"zh":"孩子在玩的時候，大人看著他們比較好。","en":"While the kids are playing, it's better for adults to keep watching them.","py":"hái zi zài wán de shí hòu, dà rén kàn zhù tā men bǐ jiào hǎo."},{"zh":"她穿著衣服拍照。","en":"She has her clothes on while taking photos.","py":"tā chuān zhù yī fú pāi zhào."},{"zh":"她在穿衣服。","en":"She is in the middle of putting her clothes on. (contrast: action in progress)","py":"tā zài chuān yī fú."},{"zh":"她穿著衣服。","en":"She has her clothes on. (contrast: state after finishing)","py":"tā chuān zhù yī fú."}],"cy":"Write a sentence using V著 to describe an ongoing state (standing, sitting, holding, wearing).","ov":"Contrasts directly with 在 + V: 在穿衣服 = the action from start to finish (putting clothes on); 穿著衣服 = after finishing, still in that state (has them on). The same instinct — checking whether you mean the action or the resulting state/location — resurfaces in B2 L6's 到 vs 在 competition (moving verbs take 到, placing verbs take 在).","tw":"Trad/simp: 著 → 着 (same pronunciation zhe in both). Taiwan note: 捷運 jiéyùn (MRT) is Taiwan-only; mainland says 地鐵. 搭捷運／搭公車 is the normal Taiwan collocation, mainland more often 坐地鐵.","src":"B2L1"},{"id":"n16-4","t":"一邊 …，一邊 … · doing two things at once","e":"一邊 before each of two verb phrases says the same subject is doing both actions simultaneously; the main action usually comes second.","pat":"一邊 + VP₁，一邊 + VP₂","tgt":["一邊"],"alt":["又","再","就"],"s":[{"zh":"我喜歡一邊吃飯，一邊看電視。","en":"I like eating while watching TV.","py":"wǒ xǐ huān yī biān chī fàn, yī biān kàn diàn shì."},{"zh":"一邊準備考試，一邊聊天不太好。","en":"It's not great to chat while studying for an exam.","py":"yī biān zhǔn bèi kǎo shì, yī biān liáo tiān bù tài hǎo."},{"zh":"他一邊看地圖，一邊走路。","en":"He walks while looking at a map.","py":"tā yī biān kàn dì tú, yī biān zǒu lù."},{"zh":"他一邊聽音樂，一邊畫畫。","en":"He listens to music while drawing.","py":"tā yī biān tīng yīn yuè, yī biān huà huà."}],"cy":"Write a sentence using 一邊…一邊… to describe two things you do at the same time.","ov":"","tw":"Trad/simp: 邊 → 边, 電視 → 电视, 準備 → 准备, 圖 → 图, 樂 → 乐, 畫 → 画.","src":"B2L1"},{"id":"n16-5","t":"A 離 B + 遠 / 近 · distance from","e":"離 is a preposition meaning '(measured) from', used for static distance between two places — not to be confused with 從, which marks a starting point for movement.","pat":"A 離 B + 很遠／很近／不遠／近一點","tgt":["離"],"alt":["從","往","到"],"s":[{"zh":"我家離學校很遠，每天都要花很多時間搭車。","en":"My house is far from school, so I have to spend a lot of time on transport every day.","py":"wǒ jiā lí xué xiào hěn yuǎn, měi tiān dōu yào huā hěn duō shí jiān dā chē."},{"zh":"我想住在離學校近一點的地方。","en":"I want to live somewhere a bit closer to school.","py":"wǒ xiǎng zhù zài lí xué xiào jìn yì diǎn de dì fāng."},{"zh":"師大離台北101不遠。","en":"NTNU is not far from Taipei 101.","py":"shī dà lí tái běi 1 0 1 bù yuǎn."},{"zh":"老師的家離台北101很遠。","en":"The teacher's home is far from Taipei 101.","py":"lǎo shī de jiā lí tái běi 1 0 1 hěn yuǎn."},{"zh":"你家離…遠不遠／近不近？","en":"Is your house far from / close to…?","py":"nǐ jiā lí … yuǎn bù yuǎn ／ jìn bù jìn?"},{"zh":"你家離什麼地方很近？","en":"What place is your house close to?","py":"nǐ jiā lí shén me dì fāng hěn jìn?"}],"cy":"Write a sentence using A離B+遠/近 to describe the distance between two places.","ov":"Competes with 從 (point 1): 離 is static distance measurement ('(measured) from'), while 從 marks a starting point for movement. Don't swap them.","tw":"Trad/simp: 離 → 离, 遠 → 远, 師 → 师.","src":"B2L1"}],"17":[{"id":"n17-1","t":"一點也／都不 + Vs · not at all","e":"一點也不 (or 一點都不) before an adjective/verb phrase says 'not even a little' — stronger than 不太, the opposite end of the scale from 非常. With an object, the object slots between 一點 and 也不.","pat":"一點 + 也／都 + 不／沒 + Vs/VP; with an object: S + 一點 + O + 也不 + V","tgt":["一點","也不"],"alt":["不太","很","非常"],"s":[{"zh":"這杯珍珠奶茶一點也不好喝。","en":"This bubble tea is not tasty at all.","py":"zhè bēi zhēn zhū nǎi chá yì diǎn yě bù hǎo hē."},{"zh":"他一點也不餓。","en":"He's not hungry at all.","py":"tā yì diǎn yě bù è."},{"zh":"這支手機看起來一點也不好用。","en":"This phone doesn't look easy to use at all.","py":"zhè zhī shǒu jī kàn qǐ lái yì diǎn yě bù hǎo yòng."},{"zh":"我一點珍珠奶茶也不喝。","en":"I don't drink any bubble tea at all. (object between 一點 and 也不)","py":"wǒ yì diǎn zhēn zhū nǎi chá yě bù hē."},{"zh":"安同一點咖啡也不喝。","en":"Antong doesn't drink any coffee at all.","py":"ān tóng yī diǎn kā fēi yě bù hē."},{"zh":"我一點甜點也不喜歡吃。","en":"I don't like eating any dessert at all.","py":"wǒ yì diǎn tián diǎn yě bù xǐ huān chī."}],"cy":"Write a sentence using 一點也不+Vs to say something is not the case at all.","ov":"Anchors the bottom of the intensity scale from point 3 (不太): 非常 > 很 > 不錯 > 不太 > 不 > 一點也不. Also the extreme end of the 一點 family started in B1 L15 — 一點 as 'a small amount' vs 一點也不 as 'not even a little' are opposite uses of the same word.","tw":"Trad/simp: 點 → 点, 餓 → 饿, 機 → 机, 甜點 → 甜点.","src":"B2L2"},{"id":"n17-2","t":"還是 … 吧！ · you'd better","e":"After weighing options out loud, 還是 + the better choice + 吧 softens the conclusion into a suggestion — 'let's go with / you'd better'. Distinct from the 還是 that appears in A還是B? either/or questions.","pat":"還是 + better choice + 吧","tgt":["還是","吧"],"alt":["或是","應該","要"],"s":[{"zh":"外面下雨了，(你不要走路，)還是搭捷運吧！","en":"It's raining outside, you'd better take the MRT instead!","py":"wài miàn xià yǔ le, ( nǐ bú yào zǒu lù, ) hái shì dā jié yùn ba!"},{"zh":"明天還要上課，你還是早一點睡吧！","en":"You still have class tomorrow, you'd better go to sleep a bit earlier!","py":"míng tiān hái yào shàng kè, nǐ hái shì zǎo yì diǎn shuì ba!"},{"zh":"這家餐廳的菜不太好吃，你還是去別家吧！","en":"This restaurant's food isn't very good, you'd better go to another one!","py":"zhè jiā cān tīng de cài bù tài hǎo chī, nǐ hái shì qù bié jiā ba!"},{"zh":"高鐵1490元2小時，台鐵850元4.5小時……還是坐高鐵吧！","en":"HSR is 1490 for 2 hours, TRA is 850 for 4.5 hours... let's just take the HSR!","py":"gāo tiě 1 4 9 0 yuán 2 xiǎo shí, tái tiě 8 5 0 yuán 4 . 5 xiǎo shí … … hái shì zuò gāo tiě ba!"}],"cy":"Write a sentence using 還是…吧 to suggest the better of two options.","ov":"Watch for the unrelated 還是 in A還是B? either/or questions — same word, a different job from this softened-suggestion use.","tw":"Trad/simp: 還 → 还, 捷運 → 捷运, 鐵 → 铁. Taiwan note: 捷運 jiéyùn (MRT), 高鐵 (THSR) and 台鐵 (TRA) are Taiwan-only transit words.","src":"B2L2"},{"id":"n17-3","t":"不太 + Vs · not very","e":"不太 before an adjective is the polite way to say something negative — it sits one step above a flat 不 on the intensity scale, so 不太冷 still admits some cold.","pat":"不太 + Vs = 'not very'. Scale: 非常 > 很 > 不錯 > 不太 > 不 > 一點也不","tgt":["不太"],"alt":["不","一點也不","很"],"s":[{"zh":"你覺得台灣的冬天冷不冷？台灣的冬天不太冷。","en":"Do you think Taiwan's winter is cold? Taiwan's winter isn't very cold.","py":"nǐ jué de tái wān de dōng tiān lěng bù lěng? tái wān de dōng tiān bù tài lěng."},{"zh":"這家餐廳的菜不太好吃。","en":"This restaurant's food isn't very good.","py":"zhè jiā cān tīng de cài bù tài hǎo chī."}],"cy":"Write a sentence using 不太+Vs to politely say something isn't very [adjective].","ov":"Sits in the middle of the intensity scale that point 1 (一點也不) anchors at the bottom: 非常 > 很 > 不錯 > 不太 > 不 > 一點也不.","tw":"Trad/simp: 灣 → 湾.","src":"B2L2"},{"id":"n17-4","t":"V + Vs 一點 · giving instructions","e":"Vs+一點 attached directly to an action verb (no 得, no object) turns it into a command or request about how to do something, e.g. 說慢一點 'speak a bit slower'.","pat":"V + Vs + 一點, no 得, no object","tgt":["一點"],"alt":["得","有一點","很"],"s":[{"zh":"你說話說得太快了，請說慢一點。","en":"You're speaking too fast, please speak a bit slower.","py":"nǐ shuō huà shuō dé tài kuài le, qǐng shuō màn yì diǎn."},{"zh":"吃快一點！我們沒時間了！","en":"Eat a bit faster! We don't have time!","py":"chī kuài yì diǎn! wǒ men méi shí jiān le!"},{"zh":"上課時間已經到了，他得走快一點。","en":"Class time has arrived, he has to walk a bit faster.","py":"shàng kè shí jiān yǐ jīng dào le, tā dé zǒu kuài yì diǎn."},{"zh":"下課時間快到了，他得寫快一點。","en":"Class is about to end, he has to write a bit faster.","py":"xià kè shí jiān kuài dào le, tā dé xiě kuài yì diǎn."},{"zh":"他說話說得太快了，我想請他說慢一點。","en":"He speaks too fast, I want to ask him to speak a bit slower.","py":"tā shuō huà shuō dé tài kuài le, wǒ xiǎng qǐng tā shuō màn yì diǎn."}],"cy":"Write a command using V+Vs+一點 (no 得, no object) telling someone to do something differently.","ov":"Extends B1 L15's Vs+一點 (comparative 'a bit more of a quality', e.g. 熱一點的咖啡) by hanging it on an action verb to make it a command aimed at someone: 說慢一點. The meaning of 一點 hasn't changed, it just picked up a verb in front. The 有一點 complaint half from B1 L15 does NOT travel here — ✗請說有一點慢. Also no 得 in a command: 請說得慢一點 describes how he speaks, it doesn't ask him to slow down. Quick test: 有一點 in front of the Vs = complaint; Vs + 一點 after = request.","tw":"Trad/simp: 說話 → 说话, 時間 → 时间, 寫 → 写.","src":"B2L2"},{"id":"n17-5","t":"AABB reduplication of two-syllable Vs","e":"Doubling both syllables of a two-syllable state adjective (AB → AABB) makes it vivid and pleasant; it fits three frames (AABB的N, AABB地V, V得AABB的) and never takes 很／非常／不太, since the doubling already carries the intensity.","pat":"AABB的+N / AABB地+V / V得+AABB(的) — state verbs only; rejects 很／非常／不太","tgt":["輕輕鬆鬆","乾乾淨淨"],"alt":["練習練習","很輕鬆","非常乾淨"],"s":[{"zh":"輕鬆 → 輕輕鬆鬆","en":"relaxed → nice and relaxed","py":"qīng sōng → qīng qīng sōng sōng"},{"zh":"漂亮 → 漂漂亮亮","en":"pretty → all dolled up","py":"piào liàng → piāo piāo liàng liàng"},{"zh":"舒服 → 舒舒服服","en":"comfortable → nice and comfy","py":"shū fú → shū shū fú fú"},{"zh":"乾淨 → 乾乾淨淨","en":"clean → squeaky clean","py":"gān jìng → gān gān jìng jìng"},{"zh":"快樂 → 快快樂樂","en":"happy → happy and cheerful","py":"kuài lè → kuài kuài lè lè"},{"zh":"客氣 → 客客氣氣","en":"polite → very politely","py":"kè qì → kè kè qì qì"},{"zh":"開心 → 開開心心","en":"happy → happily","py":"kāi xīn → kāi kāi xīn xīn"},{"zh":"大家都想住乾乾淨淨的房子。","en":"Everyone wants to live in a nice clean house. (AABB的N)","py":"dà jiā dōu xiǎng zhù gān gān jìng jìng de fáng zi."},{"zh":"很多人都想輕輕鬆鬆地學中文。","en":"Many people want to learn Chinese in a relaxed way. (AABB地V)","py":"hěn duō rén dōu xiǎng qīng qīng sōng sōng dì xué zhōng wén."},{"zh":"我們要去餐廳，開開心心地吃飯。","en":"We're going to the restaurant to eat happily. (AABB地V)","py":"wǒ men yào qù cān tīng, kāi kāi xīn xīn dì chī fàn."},{"zh":"可是如果你不好好地學，就一定不能學中文學得輕輕鬆鬆的。","en":"But if you don't study properly, you definitely won't be able to learn Chinese in a relaxed way. (V得AABB的)","py":"kě shì rú guǒ nǐ bù hǎo hǎo dì xué, jiù yí dìng bù néng xué zhōng wén xué dé qīng qīng sōng sōng de."},{"zh":"那家旅館住起來舒舒服服的。","en":"That hotel is nice and comfortable to stay in. (V得AABB的)","py":"nà jiā lǚ guǎn zhù qǐ lái shū shū fú fú de."}],"cy":"Write a sentence using an AABB reduplicated adjective (e.g. 乾乾淨淨的房間) in one of the three frames.","ov":"Competes with B2 L3's ABAB reduplication (練習練習): discriminator is state verb → AABB (乾淨→乾乾淨淨, ✗乾淨乾淨) vs action verb → ABAB (練習→練習練習, ✗練練習習). Each rejects a different intensifier: AABB rejects 很／非常／不太 (✗很乾乾淨淨); ABAB rejects 一點／一下 (✗練習練習一下).","tw":"Trad/simp: 輕鬆 → 轻松, 乾淨 → 干净, 快樂 → 快乐, 客氣 → 客气, 開心 → 开心.","src":"B2L2"},{"id":"n17-6","t":"部 vs 邊 · region vs side","e":"部 places something inside the region it's part of (北部 = the northern part of Taiwan itself); 邊 places something outside, relative to a neighboring place (北邊 = to the north of somewhere else).","pat":"A 在 B 的 X部 = A is within B, in its X region. A 在 B 的 X邊 = A is outside B, on its X side.","tgt":["部","邊"],"alt":["裡","外","方"],"s":[{"zh":"台北在台灣的北部。","en":"Taipei is in the northern part of Taiwan. (inside)","py":"tái běi zài tái wān de běi bù."},{"zh":"台北在台南的北邊。","en":"Taipei is to the north of Tainan. (outside, relative)","py":"tái běi zài tái nán de běi biān."},{"zh":"東部、西部、南部、北部、中部","en":"east, west, south, north, and central regions","py":"dōng bù, xī bù, nán bù, běi bù, zhōng bù"},{"zh":"東邊、西邊、南邊、北邊、東南邊、西北邊","en":"east, west, south, north, southeast, and northwest sides","py":"dōng biān, xī biān, nán biān, běi biān, dōng nán biān, xī běi biān"},{"zh":"羅盤方位：東北、西北、東南、西南","en":"compass directions: northeast, northwest, southeast, southwest (plus 部／邊: 東北部, 西南邊)","py":"luó pán fāng wèi: dōng běi, xī běi, dōng nán, xī nán"}],"cy":"Write two sentences: one using 部 to place something within a region, one using 邊 to place something outside relative to another place.","ov":"","tw":"Trad/simp: 邊 → 边, 東 → 东. Taiwan note: 北部／中部／南部／東部 are how Taiwanese people commonly divide the island in everyday speech (weather, travel, politics).","src":"B2L2"}],"18":[{"id":"n18-1","t":"差不多 · about the same / almost done","e":"差不多 does three jobs: comparing two things as roughly equal, marking an action as nearly finished (V得差不多了), and modifying a state verb or number to mean 'about/roughly'.","pat":"① A 和／跟 B 差不多 = roughly the same. ② V 得差不多了 = almost finished (80–99% done). ③ 差不多 + Vs/number = about, roughly.","tgt":["差不多"],"alt":["一樣","幾乎","快...了"],"s":[{"zh":"我哥哥跟我差不多高。","en":"My older brother is about as tall as me.","py":"wǒ gē gē gēn wǒ chà bu duō gāo."},{"zh":"他們差不多高。","en":"They're about the same height.","py":"tā men chà bu duō gāo."},{"zh":"捷運站和商店差不多近。","en":"The MRT station and the store are about equally close.","py":"jié yùn zhàn hé shāng diàn chà bu duō jìn."},{"zh":"我們開始學中文的時間差不多。","en":"We started learning Chinese at about the same time.","py":"wǒ men kāi shǐ xué zhōng wén de shí jiān chà bù duō."},{"zh":"我寫作業寫得差不多了。","en":"I've almost finished my homework.","py":"wǒ xiě zuò yè xiě dé chà bu duō le."},{"zh":"晚飯做得差不多了，可以準備吃飯了！","en":"Dinner's almost done, we can get ready to eat!","py":"wǎn fàn zuò dé chà bu duō le, kě yǐ zhǔn bèi chī fàn le!"},{"zh":"買得差不多了，我們去付錢吧！","en":"We've bought almost everything, let's go pay!","py":"mǎi dé chà bu duō le, wǒ men qù fù qián ba!"},{"zh":"我差不多學了五個月了。","en":"I've studied for about five months.","py":"wǒ chà bu duō xué le wǔ gè yuè le."}],"cy":"Write one sentence comparing two things with 跟…差不多, then one using V得差不多了 for something you're almost finished with.","ov":"The 了 at the end of V得差不多了 belongs to the 了 family: 咖啡貴了 (B1 L10 pt.4) → 我買了水果 (B1 L13 pt.2) → 我住了三年 (B1 L14 pt.1) → 我住了三年了 (B1 L14 pt.2) → 快下雨了 (B1 L14 pt.3) → 我寫作業寫得差不多了 (here, the last rung). This is sentence-final 了 ('nearly there, things have changed'), not the completed-action 了 from B1 L13, which is exactly why it can't be negated with 沒 (✗沒寫得差不多了 — say 還沒寫完 instead). Shape note: it's V + 得 + 差不多 + 了, the same V得 frame as 說得很快, so an object must be handled by repeating the verb (寫作業寫得差不多了, ✗寫得作業差不多了).","tw":"捷運站 (jiéyùnzhàn) is the Taiwan word for MRT station — mainland says 地鐵站 (dìtiězhàn). 作業 (homework) appears here, but in Taiwan you'll hear 功課 (gōngkè) at least as often.","src":"B2L3"},{"id":"n18-2","t":"V 過 / 沒 V 過 · have (never) done before","e":"Marks whether you have ever had a particular experience. The negative keeps 過 (unlike 了, which drops under negation).","pat":"V + 過 = experience, 'have ever done'. 沒 V 過 keeps 過. 還沒 V 過 = haven't yet. Question: V 過…嗎？ or V 過…沒有？","tgt":["過"],"alt":["了","已經","曾經"],"s":[{"zh":"他來台灣這麼久了，還沒去過台北101。","en":"He's been in Taiwan so long, but he still hasn't been to Taipei 101.","py":"tā lái tái wān zhè me jiǔ le, hái méi qù guò tái běi 1 0 1."},{"zh":"你吃過芒果冰嗎？","en":"Have you ever had mango shaved ice?","py":"nǐ chī guò máng guǒ bīng ma?"},{"zh":"我沒學過中文，可是想學學看。","en":"I've never studied Chinese, but I'd like to give it a try.","py":"wǒ méi xué guò zhōng wén, kě shì xiǎng xué xué kàn."}],"cy":"Write a question with V過…嗎 asking if you've ever done something, then a negative sentence with 沒 V過.","ov":"學學看 in the third example is B1 L10's VV看 (one-syllable verb doubled + 看 = 'give it a try and see'): 吃吃看, 試試看, 喝喝看. It pairs naturally with 沒V過 — you haven't done it, so you try it. Two carry-overs from B1 L10: no object after VV看 (front it instead: 中文，我想學學看), and plain VV with no 看 just means 'do a little' with no trying implied. For two-syllable verbs there's no 看 version at all — use this lesson's own ABAB (point 5) instead: 練習練習 ✓, ✗練習練習看.","tw":"過 (guò) keeps its full 4th tone in Taiwan as the experience marker; mainland speech usually reduces it to a neutral guo.","src":"B2L3"},{"id":"n18-3","t":"Topic，S 想起來了 / 沒想起來 · recall","e":"Puts the thing you're trying to remember first as the topic, then states whether it came back to you (想起來了) or didn't (沒想起來).","pat":"[Thing you're recalling as topic], S 想起來了 (it came back to me) / S 沒想起來 (it didn't). Short objects can go in the middle (想起他的名字來了), but topic-first is what the class uses.","tgt":["想起來"],"alt":["記得","想到","知道"],"s":[{"zh":"那個人的名字，我想起來了。","en":"That person's name — I've remembered it now.","py":"nà ge rén de míng zì, wǒ xiǎng qǐ lái le."},{"zh":"可是我是怎麼認識他的，我沒想起來。","en":"But how I know him — I couldn't recall.","py":"kě shì wǒ shì zěn me rèn shí tā de, wǒ méi xiǎng qǐ lái."},{"zh":"剛剛我們在路上看見的那個人叫什麼名字？我想起來了，他叫月美。","en":"What was the name of the person we just saw on the road? I remember now — he's called Yueměi.","py":"gāng gāng wǒ men zài lù shàng kàn jiàn de nà ge rén jiào shén me míng zì? wǒ xiǎng qǐ lái le, tā jiào yuè měi."}],"cy":"Write a sentence naming something you're trying to recall as the topic, then say whether it came back to you (想起來了) or not (沒想起來).","ov":"","tw":"剛剛 (gānggāng, 'just now') is the everyday Taiwan choice; mainland speech often reaches for 剛才 (gāngcái) instead. 認識 keeps a full 4th tone on 識 in Taiwan; mainland standard is neutral rènshi.","src":"B2L3"},{"id":"n18-4","t":"才 · merely / later than expected","e":"才 has two faces: before a verb or bare number it means 'only/merely' (less than you'd think); with a time expression it means 'not until' (later than expected). It contrasts with 就 (sooner/earlier than expected) and with 只 (purely quantitative, no judgment).","pat":"才 + (V) + number = 'only/merely'. S + time + 才 + VP = 'not until', later than expected. 才 can sit directly before a bare number (才一百塊 ✓); 只 cannot (只一百塊 ✗).","tgt":["才"],"alt":["就","只","再"],"s":[{"zh":"這件衣服，網路上才(賣)兩百塊錢。","en":"This piece of clothing is only 200 dollars online.","py":"zhè jiàn yī fú, wǎng lù shàng cái ( mài ) liǎng bǎi kuài qián."},{"zh":"你看！我買的這件衣服才200塊。","en":"Look! The clothes I bought were only 200 dollars.","py":"nǐ kàn! wǒ mǎi de zhè jiàn yī fú cái 2 0 0 kuài."},{"zh":"他每天都吃四個包子，今天他才吃了一個。","en":"He eats four buns every day, but today he only ate one.","py":"tā měi tiān dōu chī sì gè bāo zi, jīn tiān tā cái chī le yí gè."},{"zh":"這本書才賣一百塊。","en":"This book only sells for 100 dollars.","py":"zhè běn shū cái mài yì bǎi kuài."},{"zh":"這本書才一百塊。","en":"This book is only 100 dollars.","py":"zhè běn shū cái yì bǎi kuài."},{"zh":"我訂了這件衣服，可是一個月以後才收到。","en":"I ordered these clothes, but I didn't receive them until a month later.","py":"wǒ dìng le zhè jiàn yī fú, kě shì yí gè yuè yǐ hòu cái shōu dào."},{"zh":"安同七歲才會寫字，如玉五歲就會了。","en":"Antong couldn't write until age 7; Ruyu could already at 5.","py":"ān tóng qī suì cái huì xiě zì, rú yù wǔ suì jiù huì le."},{"zh":"為什麼安同每天都很晚才睡覺？","en":"Why doesn't Antong go to sleep until so late every day?","py":"wèi shén me ān tóng měi tiān dōu hěn wǎn cái shuì jiào?"},{"zh":"哥哥一歲就會說話，弟弟兩歲才會說話。","en":"The older brother could talk at age 1; the younger brother not until age 2.","py":"gē gē yī suì jiù huì shuō huà, dì di liǎng suì cái huì shuō huà."},{"zh":"哥哥一歲就會走路，弟弟兩歲半才會走路。","en":"The older brother could walk at 1; the younger brother not until 2.5.","py":"gē gē yī suì jiù huì zǒu lù, dì di liǎng suì bàn cái huì zǒu lù."},{"zh":"哥哥四歲就會看書、寫字，弟弟六歲才會。","en":"The older brother could read and write at 4; the younger brother not until 6.","py":"gē gē sì suì jiù huì kàn shū, xiě zì, dì di liù suì cái huì."},{"zh":"哥哥三歲就會自己吃飯，弟弟五歲才會自己吃飯。","en":"The older brother could feed himself at 3; the younger brother not until 5.","py":"gē gē sān suì jiù huì zì jǐ chī fàn, dì di wǔ suì cái huì zì jǐ chī fàn."}],"cy":"Write a pair of sentences: one using 就 for something that happened sooner than expected, one using 才 for something later than expected.","ov":"才 is the mirror of B1 L11's 就: 就 = sooner/earlier/cheaper than expected, 才 = later/slower/less than expected. 七歲才會 vs 五歲就會 is the pair to memorize. This is the competition pair named directly in the project's overlap map (B1 L11 → B2 L3).","tw":"網路 (wǎnglù) is both a Taiwan word and Taiwan reading for 'the internet'; mainland says 網絡/网络 (wǎngluò). 才 (cái) is rising 2nd tone — don't let it slide to 4th-tone cài (菜). 塊 (kuài) is the spoken unit for NT dollars; the formal written form is 元 (yuán).","src":"B2L3"},{"id":"n18-5","t":"ABAB reduplication of two-syllable action verbs","e":"Doubling a two-syllable action verb (AB → ABAB) softens it to mean 'do a bit of / give it a try' — the same job 一下 or 一點 does after a one-syllable verb, but for action verbs specifically, not state verbs.","pat":"AB → ABAB for two-syllable action verbs: 'do a bit of / give it a try'. Rejects 一點／一下 (don't stack them: 練習練習一下 ✗).","tgt":["練習練習"],"alt":["一下","一點"],"s":[{"zh":"練習 → 練習練習","en":"to practice → practice a bit","py":"liàn xí → liàn xí liàn xí"},{"zh":"認識 → 認識認識","en":"to get to know → get to know a bit","py":"rèn shí → rèn shí rèn shí"},{"zh":"了解 → 了解了解","en":"to understand → look into a bit","py":"liǎo jiě → liǎo jiě liǎo jiě"},{"zh":"準備 → 準備準備","en":"to prepare → prepare a bit","py":"zhǔn bèi → zhǔn bèi zhǔn bèi"},{"zh":"參觀 → 參觀參觀","en":"to visit/tour → have a look around","py":"cān guān → cān guān cān guān"},{"zh":"關心 → 關心關心","en":"to care about → show a bit of care","py":"guān xīn → guān xīn guān xīn"},{"zh":"休息 → 休息休息","en":"to rest → rest a bit","py":"xiū xī → xiū xī xiū xī"},{"zh":"那裡有一個新的博物館，我想去參觀參觀。","en":"There's a new museum there, I'd like to go have a look around.","py":"nà lǐ yǒu yí gè xīn de bó wù guǎn, wǒ xiǎng qù cān guān cān guān."},{"zh":"我要練習練習剛學的漢字，明天我們有聽寫。","en":"I want to practice the characters I just learned a bit; we have dictation tomorrow.","py":"wǒ yào liàn xí liàn xí gāng xué de hàn zì, míng tiān wǒ men yǒu tīng xiě."},{"zh":"下星期放假，我要好好地休息休息。","en":"Next week is a holiday, I want to rest properly.","py":"xià xīng qī fàng jià, wǒ yào hǎo hǎo dì xiū xī xiū xī."}],"cy":"Take a two-syllable action verb from this lesson and use it in ABAB form to mean 'do a bit of it'.","ov":"Keep the two reduplications straight: Vs → AABB (輕輕鬆鬆, B2 L2) takes state verbs and rejects 很／非常／不太; V → ABAB (練習練習, here) takes action verbs and rejects 一點／一下. Each reduplication already carries its own degree, so nothing stacks on top of either one. This is the AABB/ABAB competition pair from the project's overlap map (B2 L2 → B2 L3).","tw":"休息 gives 息 a full 2nd tone in Taiwan; mainland standard is neutral xiūxi. 認識 keeps a full 4th tone on 識 in Taiwan; mainland neutral rènshi. 漢字 (Hànzì) — in Taiwan you'll more often hear 國字 (guózì) for 'Chinese characters'.","src":"B2L3"}],"19":[{"id":"n19-1","t":"除了 A (以外)，都… / 也／還… · except for / in addition to","e":"除了 sets up either an exception or an inclusion — which one depends entirely on what follows. 都 after it means 'everyone/everything except A'; 也/還 after it means 'A and also'.","pat":"除了 X 以外，都… = everything except X. 除了 X 以外，也／還… = X and also. 以外 is optional in speech. If the subject is the same, 除了…以外 usually goes after the subject.","tgt":["除了...都","除了...也/還"],"alt":["只有","要是...就","不但...而且"],"s":[{"zh":"除了星期天以外，我每天都打工。","en":"Except for Sunday, I work part-time every day.","py":"chú le xīng qī tiān yǐ wài, wǒ měi tiān dōu dǎ gōng."},{"zh":"除了他以外，大家都來了。","en":"Except for him, everyone came.","py":"chú le tā yǐ wài, dà jiā dōu lái le."},{"zh":"除了英文以外，她還會說法文。","en":"Besides English, she can also speak French.","py":"chú le yīng wén yǐ wài, tā hái huì shuō fǎ wén."},{"zh":"除了打工，他也在念書。","en":"Besides working part-time, he's also studying.","py":"chú le dǎ gōng, tā yě zài niàn shū."}],"cy":"Write one sentence with 除了…都 (an exception) and one with 除了…也/還 (an addition).","ov":"","tw":"還 → 还, 會 → 会, 念書 → 念书 (simplified forms to log).","src":"B2L4"},{"id":"n19-2","t":"當 + role · to work as, to serve as","e":"當 plus a job or role noun means to work as or serve in that role — it is not the equivalent of 是.","pat":"當 + job/role noun = be / work as. Not 是. 當老師, 當助教, 當爸爸.","tgt":["當"],"alt":["是","做","成為"],"s":[{"zh":"我暑假想當助教。","en":"I want to work as a teaching assistant this summer.","py":"wǒ shǔ jià xiǎng dāng zhù jiào."},{"zh":"她在公司當主任，薪水很高。","en":"She works as a director at the company; the pay is high.","py":"tā zài gōng sī dāng zhǔ rèn, xīn shuǐ hěn gāo."},{"zh":"他以後想當老師。","en":"He wants to be a teacher in the future.","py":"tā yǐ hòu xiǎng dāng lǎo shī."}],"cy":"Write a sentence saying what role you want to 當 (work as) in the future.","ov":"","tw":"當 is pronounced dāng here (dàng is a different word/reading). 薪水 (salary) is the Taiwan word; mainland says 工資.","src":"B2L4"},{"id":"n19-3","t":"按照 + N · according to","e":"A preposition phrase meaning 'according to' a rule, standard, or what someone said; it goes before the verb it modifies.","pat":"按照 + (rule / standard / what someone said) + VP.","tgt":["按照"],"alt":["根據","照著","依照"],"s":[{"zh":"鐘點費按照小時算。","en":"Hourly pay is calculated according to the hour.","py":"zhōng diǎn fèi àn zhào xiǎo shí suàn."},{"zh":"按照學校的規定，學生一個星期只能打工二十個小時。","en":"According to school regulations, students can only work 20 hours a week.","py":"àn zhào xué xiào de guī dìng, xué shēng yí gè xīng qī zhǐ néng dǎ gōng èr shí gè xiǎo shí."},{"zh":"我們按照他說的做就好。","en":"We'll just do it according to what he said.","py":"wǒ men àn zhào tā shuō de zuò jiù hǎo."}],"cy":"Write a sentence describing a rule or standard using 按照.","ov":"","tw":"Taiwan note: the student work-permit reality is 20 hrs/week during term, exactly as in the example sentence.","src":"B2L4"},{"id":"n19-4","t":"算 · to calculate / to count as","e":"算 means to calculate or work out (as with pay), and pairs naturally with 按照 in talk about wages.","pat":"算 = calculate (算錢, 算起來 = when you add it up). Pairs naturally with 按照 in pay talk. 算了 (forget it) is a different, very common idiom.","tgt":["算"],"alt":["計算","算了","當作"],"s":[{"zh":"他們是按照小時算錢的。","en":"They calculate pay by the hour.","py":"tā men shì àn zhào xiǎo shí suàn qián de."},{"zh":"這份工作的薪水怎麼算？","en":"How is the pay for this job calculated?","py":"zhè fèn gōng zuò de xīn shuǐ zěn me suàn?"},{"zh":"一個小時一百六十塊，一天八個小時，算起來一天一千二百八十塊。","en":"160 dollars an hour, 8 hours a day — adding it up, that's 1,280 dollars a day.","py":"yí gè xiǎo shí yì bǎi liù shí kuài, yī tiān bā gè xiǎo shí, suàn qǐ lái yī tiān yī qiān èr bǎi bā shí kuài."}],"cy":"Write a sentence using 算起來 to add something up, noting that 算了 means something completely different ('forget it').","ov":"","tw":"","src":"B2L4"},{"id":"n19-5","t":"…，然後… · and then (sequence)","e":"然後 starts the second clause in a sequence of actions, similar to 再 in 先…再… but usable across longer stretches and even with different subjects.","pat":"然後 starts the second clause, like 再 in 先…再… (B1 L12), but usable with longer stretches and different subjects. 先…，然後… is the common combination.","tgt":["然後"],"alt":["再","接著","於是"],"s":[{"zh":"我先寫履歷表，然後去面談。","en":"First I'll write my resume, then go to the interview.","py":"wǒ xiān xiě lǚ lì biǎo, rán hòu qù miàn tán."},{"zh":"主任先介紹了工作的情形，然後說明薪水怎麼算。","en":"The director first introduced the work situation, then explained how pay is calculated.","py":"zhǔ rèn xiān jiè shào le gōng zuò de qíng xíng, rán hòu shuō míng xīn shuǐ zěn me suàn."}],"cy":"Write a two-step sequence using 先…，然後…","ov":"然後 does the same job as 再 in B1 L12's 先…再…, but can span longer stretches and different subjects — worth logging as a family with 先…再….","tw":"履歷表 (resume/CV) is the Taiwan term; mainland uses 簡歷. 面談 (interview) is Taiwan usage.","src":"B2L4"},{"id":"n19-6","t":"沒想到 · unexpectedly","e":"An exclamation meaning 'I didn't expect that…', usually placed at the start of the sentence with the subject often dropped.","pat":"沒想到 + clause = 'I didn't expect that…'. Sentence-initial, subject often dropped. Positive cousin 想到 = to think of.","tgt":["沒想到"],"alt":["以為","沒想起來","誰知道"],"s":[{"zh":"沒想到面談那麼順利！","en":"I didn't expect the interview to go so smoothly!","py":"méi xiǎng dào miàn tán nà me shùn lì!"},{"zh":"我沒想到他馬上就答應了。","en":"I didn't expect that he'd agree right away.","py":"wǒ méi xiǎng dào tā mǎ shàng jiù dā yìng le."}],"cy":"Write a sentence starting with 沒想到 to express surprise about an unexpected outcome.","ov":"Keep this apart from B2 L7's 以為 (a belief that turned out wrong — the mistake is in the speaker's own head) and B2 L3's 想起來/沒想起來 (recall of something forgotten) — three related but distinct 想/以為 expressions that are easy to blur together.","tw":"","src":"B2L4"}],"20":[{"id":"n20-1","t":"Vs + 得不得了 · extremely","e":"A degree complement stronger than 非常, meaning 'extremely'. Used only with state verbs and feeling verbs.","pat":"Vs + 得 + 不得了 = extremely Vs, stronger than 非常. It's a degree complement, so it goes after the Vs with 得, same slot as 得很／得多. Only for Vs and feeling verbs (高興, 開心, 累). 不得了 on its own = 'oh no / terrible'.","tgt":["得不得了"],"alt":["非常","得很","極了"],"s":[{"zh":"喜宴上的人多得不得了。","en":"There were an extreme number of people at the wedding banquet.","py":"xǐ yàn shàng de rén duō dé bù dé le."},{"zh":"新娘漂亮得不得了。","en":"The bride was extremely beautiful.","py":"xīn niáng piào liàng dé bù dé le."},{"zh":"這家餐廳熱鬧得不得了。","en":"This restaurant is extremely lively.","py":"zhè jiā cān tīng rè nào dé bù dé le."},{"zh":"他高興得不得了，因為他要結婚了。","en":"He's extremely happy because he's getting married.","py":"tā gāo xìng dé bù dé le, yīn wèi tā yào jié hūn le."}],"cy":"Write a sentence describing something with Vs得不得了 to say it's extremely so.","ov":"","tw":"熱鬧 → 热闹, 興 → 兴, 結婚 → 结婚 (simplified forms to log).","src":"B2L5"},{"id":"n20-2","t":"有 V 有 V · doing both, lively","e":"A fixed phrase pattern joining two one-syllable verbs after 有 to describe a lively scene where both things are happening.","pat":"有 + V₁ + 有 + V₂ with two one-syllable verbs = 'there was V₁-ing and V₂-ing', a set phrase for a lively scene. Fixed pairs only, don't invent new ones at this level: 有說有笑, 有吃有喝.","tgt":["有...有..."],"alt":["又...又...","一邊...一邊..."],"s":[{"zh":"客人們有說有笑，很熱鬧。","en":"The guests were chatting and laughing, very lively.","py":"kè rén men yǒu shuō yǒu xiào, hěn rè nào."},{"zh":"喜宴上有吃有喝，大家都很開心。","en":"At the wedding banquet there was eating and drinking, everyone was happy.","py":"xǐ yàn shàng yǒu chī yǒu hē, dà jiā dōu hěn kāi xīn."}],"cy":"Use one of the fixed 有V有V phrases (有說有笑 or 有吃有喝) to describe a lively scene.","ov":"","tw":"","src":"B2L5"},{"id":"n20-3","t":"另外 · another / in addition","e":"另外 has two uses: 另外 + number + measure + noun means 'a further one on top of what's there' (so it can take a number); at the start of a clause, 另外 means 'in addition, besides'. It contrasts with 別的, which means 'a different one instead' and never takes a number.","pat":"另外 + 一 + M + N = another one (a further one). 另外，…／另外還… at the start of a clause = in addition, besides.","tgt":["另外"],"alt":["別的","其他","再"],"s":[{"zh":"這件禮服太正式了，我想看另外一件。","en":"This dress is too formal, I'd like to see another one.","py":"zhè jiàn lǐ fú tài zhèng shì le, wǒ xiǎng kàn lìng wài yī jiàn."},{"zh":"我們送了紅包，另外還送了一個禮物。","en":"We gave a red envelope, and on top of that also gave a gift.","py":"wǒ men sòng le hóng bāo, lìng wài hái sòng le yí gè lǐ wù."},{"zh":"我不要這個，給我別的。","en":"I don't want this one, give me a different one.","py":"wǒ bú yào zhè ge, gěi wǒ bié de."},{"zh":"另外兩位老師也來了。","en":"Two other/additional teachers also came.","py":"lìng wài liǎng wèi lǎo shī yě lái le."}],"cy":"Write one sentence with 另外 + number + measure word (an additional item that counts), and one with 別的 (a different one, no number).","ov":"別的 vs 另外 is a competition asked and answered in B2 L6 class (9/7). 別的 = a different one instead — it swaps out what you just named and stays vague, so it never counts: ✓別的地方、別的人 ✗別的三本書。 另外 = a further one on top of what's already there — it adds, and because it adds it can count: ✓另外一件、另外兩位老師、另外三本書。 Test: if English would let you say 'another two…', it's 另外; if you mean 'some other one, not this one', it's 別的. Full write-up lives in B2 L6 Ⅲ (V 在); this is the same answer, anchored here where 另外 is first taught.","tw":"","src":"B2L5"},{"id":"n20-4","t":"送 vs 給 · giving a gift / seeing someone off","e":"送 does several jobs — give as a free gift, see someone off / go partway with them, or comp something — while 給 is just the plain 'hand over'. Neither is 請, which means to pay for someone.","pat":"送 + person + gift = give as a present (給 is just hand over). 送 + person (+ 到 place) = see someone off / take them somewhere.","tgt":["送"],"alt":["給","請","賣"],"s":[{"zh":"朋友結婚，我送他們一個紅包。","en":"When a friend gets married, I give them a red envelope.","py":"péng yǒu jié hūn, wǒ sòng tā men yí gè hóng bāo."},{"zh":"喜宴以後，新人在門口送客人。","en":"After the banquet, the newlyweds see off the guests at the door.","py":"xǐ yàn yǐ hòu, xīn rén zài mén kǒu sòng kè rén."},{"zh":"我送你到捷運站。","en":"I'll walk you to the MRT station.","py":"wǒ sòng nǐ dào jié yùn zhàn."},{"zh":"老闆送了一盤小菜。","en":"The boss threw in a free side dish.","py":"lǎo bǎn sòng le yī pán xiǎo cài."},{"zh":"今天我請你。","en":"Today it's my treat (I'll pay).","py":"jīn tiān wǒ qǐng nǐ."},{"zh":"我請客。","en":"I'm treating/paying.","py":"wǒ qǐng kè."}],"cy":"Write a sentence using 送 to give a free gift, and a separate sentence using 請 to say you're paying for someone.","ov":"送 is one word doing three jobs (family): ① hand over a gift free of charge (送他們一個紅包) ② see someone off / go partway with them (送客人／送你到捷運站) ③ comp something (老闆送了一盤小菜). Trap: 送 is not 'pay for someone' — that's 請 (今天我請你／我請客). A shop that takes your money 賣給 you; only what costs nothing is 送給. Forward to B2 L6 (family: 給): B2 L6 gives the full frame V給+人+東西 (王先生賣給他一輛機車). Why 送他們一個紅包 has no 給: 給 may drop after verbs that hand something outward (賣、送、付) — 送他們一個紅包 = 送給他們一個紅包, both correct. Verbs that don't hand outward keep 給: 買給我一本書、做給我一個蛋糕 — ✗買我一本書、✗做我一個蛋糕. In B2 L6 the same 送給 also rides inside 把: 我要把這包茶送給老師。","tw":"紅包 → 红包, 禮物 → 礼物, 捷運 → 捷运 (simplified forms). 捷運 is the Taiwan word for the MRT/metro.","src":"B2L5"},{"id":"n20-5","t":"祝 + person + blessing · wedding phrases","e":"祝 introduces a wish or blessing for someone, followed by a fixed four-character phrase — the same shape as 祝你生日快樂 from B1 L13.","pat":"祝 + (person) + four-character blessing, same shape as B1 L13's 祝你生日快樂. 祝福 is the noun/verb 'blessing'; 祝 is what you say. 句 is the measure for utterances: 一句話, 幾句祝福的話.","tgt":["祝"],"alt":["希望","祝福","恭喜"],"s":[{"zh":"祝你們百年好合！","en":"Wishing you a hundred years of harmony (a happy marriage)!","py":"zhù nǐ men bǎi nián hǎo hé!"},{"zh":"祝你們早生貴子！","en":"Wishing you an early birth of a noble child (children soon)!","py":"zhù nǐ men zǎo shēng guì zi!"},{"zh":"大家都對新人說了幾句祝福的話。","en":"Everyone said a few words of blessing to the newlyweds.","py":"dà jiā dōu duì xīn rén shuō le jǐ jù zhù fú de huà."}],"cy":"Write a sentence using 祝 + someone + a blessing, following the same shape as 祝你生日快樂.","ov":"Same shape as B1 L13's 祝你生日快樂 — 祝 + person + fixed blessing phrase.","tw":"At a Taiwanese 喜宴 you'll say 恭喜！ when you hand over the 紅包 at the door (收禮台), and the four-character blessings go in the 紅包 card or the toast.","src":"B2L5"},{"id":"n20-6","t":"Measure words 件 / 句 / 位","e":"件 is used for clothes and also for matters/events; 句 measures sentences/utterances; 位 is the polite measure word for people.","pat":"件 for clothes and for matters/events (一件事, 一件喜事). 句 for sentences. 位 for people when being polite (幾位？ at a restaurant).","tgt":["件","句","位"],"alt":["個","張","人"],"s":[{"zh":"一件西裝、一件禮服、一件喜事","en":"a suit, a formal dress, a happy occasion","py":"yī jiàn xī zhuāng, yī jiàn lǐ fú, yī jiàn xǐ shì"},{"zh":"一句話、幾句祝福","en":"a sentence/remark, a few words of blessing","py":"yī jù huà, jǐ jù zhù fú"},{"zh":"一位客人、幾位親戚","en":"a guest, a few relatives (polite)","py":"yī wèi kè rén, jǐ wèi qīn qī"}],"cy":"Write three short phrases, one using each measure word 件, 句, and 位.","ov":"","tw":"裝 → 装, 親戚 → 亲戚 (simplified forms to log).","src":"B2L5"}],"21":[{"id":"n21-1","t":"Ⅰ. 到 · destination marker: V + 到 + place","e":"A movement verb followed by 到 + place states where the thing or person ended up as a result of that action — only for verbs where something actually travels through space, in contrast to placing verbs, which take 在 instead.","pat":"movement verb + 到 + place. The thing (or person) ends up at that place as a result of the verb. The 到-phrase comes after the verb; 不／沒 goes before the verb, not before 到.","tgt":["到"],"alt":["在","去","給"],"s":[{"zh":"他在踢足球，踢著踢著就踢到學校外面了。","en":"He was playing football, and after kicking it around for a while it ended up outside the school.","py":"tā zài tī zú qiú, tī zhù tī zhù jiù tī dào xué xiào wài miàn le."},{"zh":"馬安同上星期從台北騎機車騎到花蓮。","en":"Last week Ma Antong rode his scooter from Taipei to Hualien.","py":"mǎ ān tóng shàng xīng qī cóng tái běi qí jī chē qí dào huā lián."},{"zh":"這個蛋糕，我打算拿到學校請同學吃。","en":"I plan to take this cake to school and treat my classmates.","py":"zhè ge dàn gāo, wǒ dǎ suàn ná dào xué xiào qǐng tóng xué chī."},{"zh":"我在師大下車，沒搭到台北火車站。","en":"I got off at NTNU — I didn't ride all the way to Taipei Main Station.","py":"wǒ zài shī dà xià chē, méi dā dào tái běi huǒ chē zhàn."},{"zh":"張老師跟他太太決定不搬到西班牙了。","en":"Teacher Zhang and his wife decided not to move to Spain after all.","py":"zhāng lǎo shī gēn tā tài tài jué dìng bù bān dào xī bān yá le."},{"zh":"我的書，妳明天會拿到學校給我嗎？","en":"My book — will you bring it to school for me tomorrow?","py":"wǒ de shū, nǐ míng tiān huì ná dào xué xiào gěi wǒ ma?"},{"zh":"本子和筆，你是不是都放到背包裡了？","en":"The notebook and the pen — did you put them all in your backpack?","py":"běn zi hé bǐ, nǐ shì bú shì dōu fàng dào bēi bāo lǐ le?"},{"zh":"我要到美國去。","en":"I'm going to go to America.","py":"wǒ yào dào měi guó qù."},{"zh":"哥哥要到臺灣來。","en":"Older brother is coming to Taiwan.","py":"gē gē yào dào tái wān lái."},{"zh":"他們打算走到哪裡去？","en":"Where are they planning to walk to?","py":"tā men dǎ suàn zǒu dào nǎ lǐ qù?"},{"zh":"棒球，他們不小心打到樹上了。","en":"They accidentally hit the baseball into the tree.","py":"bàng qiú, tā men bù xiǎo xīn dǎ dào shù shàng le."},{"zh":"從山下爬到山上，需要3個鐘頭。","en":"Climbing from the foot of the mountain to the top takes 3 hours.","py":"cóng shān xià pá dào shān shàng, xū yào 3 gè zhōng tóu."},{"zh":"從捷運站走路走到學校，只需要九分鐘。","en":"Walking from the MRT station to school only takes nine minutes.","py":"cóng jié yùn zhàn zǒu lù zǒu dào xué xiào, zhǐ xū yào jiǔ fēn zhōng."},{"zh":"我們昨天聊到很晚。","en":"We chatted until late last night.","py":"wǒ men zuó tiān liáo dào hěn wǎn."},{"zh":"他工作到十點。","en":"He worked until 10 o'clock.","py":"tā gōng zuò dào shí diǎn."},{"zh":"我看書看到十二點才睡。","en":"I read until midnight before going to sleep.","py":"wǒ kàn shū kàn dào shí èr diǎn cái shuì."},{"zh":"我昨天把行李從機場帶到旅館了。","en":"Yesterday I brought the luggage from the airport to the hotel.","py":"wǒ zuó tiān bǎ xíng lǐ cóng jī chǎng dài dào lǚ guǎn le."},{"zh":"這封信我要寄到美國去。","en":"I want to mail this letter to America.","py":"zhè fēng xìn wǒ yào jì dào měi guó qù."},{"zh":"他每天早上跑到河邊公園，再走回學校。","en":"Every morning he runs to the riverside park, then walks back to school.","py":"tā měi tiān zǎo shàng pǎo dào hé biān gōng yuán, zài zǒu huí xué xiào."},{"zh":"從台北飛到東京，大概三個小時。","en":"Flying from Taipei to Tokyo takes about three hours.","py":"cóng tái běi fēi dào dōng jīng, dà gài sān gè xiǎo shí."},{"zh":"你可以幫我把這箱書搬到樓上去嗎？","en":"Can you help me move this box of books upstairs?","py":"nǐ kě yǐ bāng wǒ bǎ zhè xiāng shū bān dào lóu shàng qù ma?"},{"zh":"老闆說會把午飯送到辦公室來。","en":"The boss said he'd have lunch delivered to the office.","py":"lǎo bǎn shuō huì bǎ wǔ fàn sòng dào bàn gōng shì lái."}],"cy":"Write a sentence naming a movement verb + 到 + a destination place that the thing/person ends up at.","ov":"This is the same 到 that reappears inside Ⅳ's 把 pattern (A 把 B V 到 + place) — the two are one idea, taught together. To distinguish from Ⅲ's V+在: 到 goes with moving verbs (搬, 拿, 送, 踢, 騎, 開 — things that travel), 在 goes with placing verbs (放, 留, 存, 寫 — things that get set down and stay). This is the book's own explicit rule and the most exam-likely discrimination in the lesson. Forward: the same 到+place+來/去 shape returns in B2 L7 point 4, which drops the explicit 到+place and keeps only a bare direction (走出來, 開過來, 丟進去) — the 'where am I standing' test carries over unchanged.","tw":"機車 (jīchē) is the Taiwan word for a scooter; mainland says 摩托車 (mótuōchē). 星期 is read xīngqí in Taiwan vs xīngqī on the mainland. 搭 (dā) is the normal Taiwan verb for taking public transport. 鐘頭 (zhōngtóu) is Taiwan-colloquial for 'an hour'; mainland prefers 小時. 捷運 (jiéyùn) is the Taiwan word for the metro/MRT; mainland 地鐵.","src":"B2L6"},{"id":"n21-2","t":"Ⅱ. 給 · indirect object marker: V + 給 + person + thing","e":"Double-object verbs like 賣, 送, 付 need both a thing that changes hands and a person who ends up with it. 給 marks the receiver right after the verb, while the thing itself carries no marker and sits at the end.","pat":"V給 + 人 + 東西. The person comes straight after 給; the thing trails at the end with nothing marking it.","tgt":["給"],"alt":["到","跟","為"],"s":[{"zh":"王先生賣給他一輛機車。","en":"Mr. Wang sold him a motorcycle.","py":"wáng xiān shēng mài gěi tā yī liàng jī chē."},{"zh":"田中誠一付給房東三個月的房租。","en":"Tanaka paid the landlord three months' rent.","py":"tián zhōng chéng yī fù gěi fáng dōng sān gè yuè de fáng zū."},{"zh":"他從法國回來，送給白如玉一些法國甜點。","en":"He came back from France and gave Bai Ruyu some French sweets.","py":"tā cóng fǎ guó huí lái, sòng gěi bái rú yù yī xiē fǎ guó tián diǎn."},{"zh":"他想賣給我朋友這個電腦。","en":"He wants to sell this computer to my friend.","py":"tā xiǎng mài gěi wǒ péng yǒu zhè ge diàn nǎo."},{"zh":"他想賣這個電腦給我朋友。","en":"He wants to sell this computer to my friend.","py":"tā xiǎng mài zhè ge diàn nǎo gěi wǒ péng yǒu."},{"zh":"這個電腦，他想賣給我朋友。","en":"This computer — he wants to sell it to my friend.","py":"zhè ge diàn nǎo, tā xiǎng mài gěi wǒ péng yǒu."},{"zh":"房東不租給她了。","en":"The landlord won't rent to her anymore.","py":"fáng dōng bù zū gěi tā le."},{"zh":"田中誠一還沒付給房東上個月的房租。","en":"Tanaka hasn't yet paid the landlord last month's rent.","py":"tián zhōng chéng yī hái méi fù gěi fáng dōng shàng gè yuè de fáng zū."},{"zh":"你的腳踏車，賣給白如玉了沒有？","en":"Your bike — have you sold it to Bai Ruyu yet?","py":"nǐ de jiǎo tà chē, mài gěi bái rú yù le méi yǒu?"},{"zh":"下個月的學費，你付給學校了沒有？","en":"Next month's tuition — have you paid the school yet?","py":"xià gè yuè de xué fèi, nǐ fù gěi xué xiào le méi yǒu?"},{"zh":"不踢給你，踢給我！","en":"Don't kick it to you, kick it to me!","py":"bù tī gěi nǐ, tī gěi wǒ!"},{"zh":"客人付給老闆一百塊。","en":"The customer paid the boss 100 dollars.","py":"kè rén fù gěi lǎo bǎn yì bǎi kuài."},{"zh":"老闆拿給客人豬肉。","en":"The boss handed the customer the pork.","py":"lǎo bǎn ná gěi kè rén zhū ròu."},{"zh":"老闆送給這位太太豬肉嗎？不是，老闆賣給她豬肉。","en":"Did the boss give this lady pork as a gift? No, the boss sold her pork.","py":"lǎo bǎn sòng gěi zhè wèi tài tài zhū ròu ma? bú shì, lǎo bǎn mài gěi tā zhū ròu."},{"zh":"老闆付給這位太太錢嗎？不是，客人付給老闆錢。","en":"Did the boss pay this lady money? No, the customer paid the boss money.","py":"lǎo bǎn fù gěi zhè wèi tài tài qián ma? bú shì, kè rén fù gěi lǎo bǎn qián."},{"zh":"先生：我要送給你這個。","en":"Sir: I want to give you this.","py":"xiān shēng: wǒ yào sòng gěi nǐ zhè ge."},{"zh":"先生做給小姐這個禮物嗎？不是，先生買給小姐這個禮物。","en":"Did the man make this gift for the lady himself? No, the man bought this gift for the lady.","py":"xiān shēng zuò gěi xiǎo jiě zhè ge lǐ wù ma? bú shì, xiān shēng mǎi gěi xiǎo jiě zhè ge lǐ wù."},{"zh":"我送給他一個蛋糕。","en":"I gave him a cake, free of charge.","py":"wǒ sòng gěi tā yí gè dàn gāo."},{"zh":"我做給他一個蛋糕。","en":"I made him a cake (did the work for him).","py":"wǒ zuò gěi tā yí gè dàn gāo."},{"zh":"我做了一個蛋糕送給他。","en":"I made a cake and gave it to him.","py":"wǒ zuò le yí gè dàn gāo sòng gěi tā."}],"cy":"Write the same double-object sentence three ways: basic V給+person+thing, person moved to the back, and thing fronted as topic.","ov":"The 給 family so far: B1 L11 打電話給你 (給 tacks a recipient onto a verb that has no thing to hand over) → here, B2 L6, V給+人+東西 (a real thing changes hands) → and inside Ⅳ's 把: 把這包茶送給老師. Same 給 each time, marking whoever ends up with something. When 給 can drop: only with verbs of giving outward (賣, 送, 付) — 我要賣我朋友這個電腦 ✓. With verbs like 做, 買 it can't drop when there's a made/bought thing for someone — 我做他一個蛋糕 ✗, 哥哥買我一本書 ✗ both need 給.","tw":"腳踏車 (jiǎotàchē) is the Taiwan word for a bicycle; mainland 自行車 (zìxíngchē). 法國 is read Fàguó in Taiwan vs Fǎguó on the mainland.","src":"B2L6"},{"id":"n21-3","t":"Ⅲ. V + 在 · resultant location: where the thing ends up","e":"A placing verb followed by 在 + location states where the object is set down and stays — contrast with 到, used for moving verbs where the thing travels there.","pat":"placing verb + 在 + location. The object is placed and stays there. Verbs: 放 (put), 留 (leave), 存 (save/deposit), 寫 (write), 裝 (install), 住 (live).","tgt":["在"],"alt":["到","給","把"],"s":[{"zh":"那張椅子，請你放在樓下。","en":"That chair — please put it downstairs.","py":"nà zhāng yǐ zi, qǐng nǐ fàng zài lóu xià."},{"zh":"這些複雜的漢字，我要寫在本子上。","en":"I'm going to write these complicated characters in my notebook.","py":"zhè xiē fù zá de hàn zì, wǒ yào xiě zài běn zi shàng."},{"zh":"履歷表先留在我這裡。","en":"Leave the resume with me for now.","py":"lǚ lì biǎo xiān liú zài wǒ zhè lǐ."},{"zh":"傘，白如玉放在學校。","en":"The umbrella — Bai Ruyu left it at school.","py":"sǎn, bái rú yù fàng zài xué xiào."},{"zh":"書別放在椅子上。","en":"Don't put the book on the chair.","py":"shū bié fàng zài yǐ zi shàng."},{"zh":"我沒留甜點在桌子上。","en":"I didn't leave any dessert on the table.","py":"wǒ méi liú tián diǎn zài zhuō zi shàng."},{"zh":"他的錢沒存在銀行裡。","en":"His money isn't deposited in the bank.","py":"tā de qián méi cún zài yín háng lǐ."},{"zh":"電視，你打算放在哪裡？","en":"The TV — where are you planning to put it?","py":"diàn shì, nǐ dǎ suàn fàng zài nǎ lǐ?"},{"zh":"我給你的資料，你存在電腦裡沒有？","en":"The files I gave you — did you save them on the computer?","py":"wǒ gěi nǐ de zī liào, nǐ cún zài diàn nǎo lǐ méi yǒu?"},{"zh":"她把背包放在教室裡。","en":"She put her backpack in the classroom (on purpose).","py":"tā bǎ bēi bāo fàng zài jiào shì lǐ."},{"zh":"她把背包忘在教室裡。","en":"She left her backpack in the classroom (forgot it there).","py":"tā bǎ bēi bāo wàng zài jiào shì lǐ."},{"zh":"你的錢都花在哪裡？","en":"Where do you spend all your money?","py":"nǐ de qián dōu huā zài nǎ lǐ?"},{"zh":"你的時間都用在什麼地方？","en":"What do you spend all your time on?","py":"nǐ de shí jiān dōu yòng zài shén me dì fāng?"}],"cy":"Write a sentence with a placing verb (放/留/存/寫) + 在 + a location, saying where something ends up and stays.","ov":"到 vs 在 is the exam-likely discrimination named directly under Ⅰ: 到 goes with moving verbs (搬, 拿, 送, 踢, 騎, 開 — things that travel), 在 with placing verbs (放, 留, 存, 寫, 裝 — things that get set down). Extension: 忘在 = left it there unintentionally, contrasted with 放在 (on purpose); and V在 + an abstract 'place' (花在, 用在) shows money and time can also 'end up' somewhere. Also feeds directly into Ⅳ's 把 pattern as the 在-ending option.","tw":"隨身碟 (suíshēndié) is the Taiwan word for a USB stick; mainland U盤.","src":"B2L6"},{"id":"n21-4","t":"Ⅳ. 把 · moving an object to a location: A 把 B + V + 到／在／給 + place or person","e":"把 fronts a definite object so the sentence can end on where it went, where it was placed, or who received it. It is not itself a verb — it's a marker flagging the noun after it as the object, letting the real verb (which follows) carry the result.","pat":"A 把 B + Verb + 到／在／給 + Location. Rules: (1) object of 把 is definite. (2) 不／沒／別／還沒 go before 把, never before the verb. (3) 到 with moving verbs, 在 with placing verbs, 給 with people. (4) Questions: 是不是把… or 把…了沒有.","tgt":["把"],"alt":["被","將","拿"],"s":[{"zh":"我把球踢到學校外面了。","en":"I kicked the ball outside the school.","py":"wǒ bǎ qiú tī dào xué xiào wài miàn le."},{"zh":"他想把公司搬到台南。","en":"He wants to move the company to Tainan.","py":"tā xiǎng bǎ gōng sī bān dào tái nán."},{"zh":"我打算把這個蛋糕拿到學校請同學吃。","en":"I plan to take this cake to school to treat my classmates.","py":"wǒ dǎ suàn bǎ zhè ge dàn gāo ná dào xué xiào qǐng tóng xué chī."},{"zh":"我要把這包茶送給老師。","en":"I want to give this pack of tea to the teacher.","py":"wǒ yào bǎ zhè bāo chá sòng gěi lǎo shī."},{"zh":"請妳把那件衣服拿給白如玉。","en":"Please take that piece of clothing to Bai Ruyu.","py":"qǐng nǐ bǎ nà jiàn yī fú ná gěi bái rú yù."},{"zh":"我打算把舊車賣給高先生。","en":"I plan to sell the old car to Mr. Gao.","py":"wǒ dǎ suàn bǎ jiù chē mài gěi gāo xiān shēng."},{"zh":"請你把那張椅子放在樓下。","en":"Please put that chair downstairs.","py":"qǐng nǐ bǎ nà zhāng yǐ zi fàng zài lóu xià."},{"zh":"我要把媽媽給我的錢存在銀行裡。","en":"I want to deposit the money my mom gave me in the bank.","py":"wǒ yào bǎ mā mā gěi wǒ de qián cún zài yín háng lǐ."},{"zh":"他沒把資料帶到學校來，可是還好我帶了。","en":"He didn't bring the files to school, but luckily I did.","py":"tā méi bǎ zī liào dài dào xué xiào lái, kě shì hái hǎo wǒ dài le."},{"zh":"別把那本書賣給別人，賣給我吧。","en":"Don't sell that book to someone else, sell it to me.","py":"bié bǎ nà běn shū mài gěi bié rén, mài gěi wǒ ba."},{"zh":"我還沒把這個月的房租拿給房東。","en":"I haven't given this month's rent to the landlord yet.","py":"wǒ hái méi bǎ zhè ge yuè de fáng zū ná gěi fáng dōng."},{"zh":"別把隨身碟放在桌子上。","en":"Don't leave the USB stick on the table.","py":"bié bǎ suí shēn dié fàng zài zhuō zi shàng."},{"zh":"妳是不是把我的書帶到學校來了？","en":"Did you bring my book to school?","py":"nǐ shì bú shì bǎ wǒ de shū dài dào xué xiào lái le?"},{"zh":"你把那本本子拿給老師了沒有？","en":"Have you given that notebook to the teacher yet?","py":"nǐ bǎ nà běn běn zi ná gěi lǎo shī le méi yǒu?"},{"zh":"房東是不是把熱水器裝在浴室外面了？","en":"Did the landlord install the water heater outside the bathroom?","py":"fáng dōng shì bú shì bǎ rè shuǐ qì zhuāng zài yù shì wài miàn le?"},{"zh":"你把學費用在什麼地方了？","en":"What did you spend your tuition money on?","py":"nǐ bǎ xué fèi yòng zài shén me dì fāng le?"},{"zh":"誰把我的咖啡喝了？","en":"Who drank my coffee?","py":"shuí bǎ wǒ de kā fēi hē le?"},{"zh":"房東要把房子賣了。","en":"The landlord wants to sell the house.","py":"fáng dōng yào bǎ fáng zi mài le."}],"cy":"Write a 把 sentence using A 把 B + verb + 到/在/給 + a location or person, following the rules for where negation goes and what must follow the verb.","ov":"把 is not a verb — it's a marker (proof: verbs can swap in the same frame — 我把球拿到/踢到/放在 — while dropping 把 just reverts to normal word order). The 把 family end to end: ① B1 L15 把 O V 了 (the thing got dealt with, no destination: 誰把我的咖啡喝了？) → ② here, 把 O V 到 + place (it travelled there) → ③ here, 把 O V 在 + place (set down and stays) → ④ here, 把 O V 給 + person (ended up with someone). This is the extension named directly in the project's overlap map: disposal 把 O V 了 → A 把 B V 到／在／給 + location. Shared rules across all four: definite object · 不／沒／別／還沒 before 把 · 來／去 last · something must follow the verb · 是、有、喜歡、知道、覺得 never take 把. Later (not on this test): 把 O V 好／完, 把 O V 成, 把 O 當.","tw":"隨身碟 (suíshēndié) is the Taiwan word for a USB stick; mainland U盤. 垃圾 is read lèsè in Taiwan; mainland lājī.","src":"B2L6"},{"id":"n21-5","t":"Ⅴ. 而且 · and / furthermore","e":"而且 joins two comments about the same thing, pointing the same direction (both good or both bad). Between two state verbs it means 'and'; between two clauses it means 'furthermore', often promoting the second item as new information the listener didn't already have.","pat":"而且 starts the second half. Between two Vs (熱而且濕) it's 'and'; between two clauses it's 'furthermore', often with 還 or 也 in the second clause. Both halves point the same way; for a contrast use 可是.","tgt":["而且"],"alt":["可是","不但","並且"],"s":[{"zh":"台灣的夏天熱而且濕。","en":"Taiwan's summer is hot and humid.","py":"tái wān de xià tiān rè ér qiě shī."},{"zh":"如果多花一點時間找，一定能找到便宜而且合適的。","en":"If you spend a bit more time looking, you can definitely find something cheap and suitable.","py":"rú guǒ duō huā yì diǎn shí jiān zhǎo, yí dìng néng zhǎo dào pián yi ér qiě hé shì de."},{"zh":"房東幫她裝了有線電視，而且還幫她裝了網路。","en":"The landlord installed cable TV for her, and furthermore also installed internet for her.","py":"fáng dōng bāng tā zhuāng le yǒu xiàn diàn shì, ér qiě hái bāng tā zhuāng le wǎng lù."},{"zh":"做這個工作得會說中文，而且得有一些工作經驗。","en":"To do this job you need to speak Chinese, and also need some work experience.","py":"zuò zhè ge gōng zuò dé huì shuō zhōng wén, ér qiě dé yǒu yī xiē gōng zuò jīng yàn."},{"zh":"我想租環境好、光線好的房子。","en":"I want to rent a place with a good environment and good light.","py":"wǒ xiǎng zū huán jìng hǎo, guāng xiàn hǎo de fáng zi."},{"zh":"我想租環境好，而且光線也好的房子。","en":"I want to rent a place with a good environment — and the lighting is good too.","py":"wǒ xiǎng zū huán jìng hǎo, ér qiě guāng xiàn yě hǎo de fáng zi."},{"zh":"這棟大樓裡有教室，而且也有社團辦公室。","en":"This building has classrooms, and it also has club offices.","py":"zhè dòng dà lóu lǐ yǒu jiào shì, ér qiě yě yǒu shè tuán bàn gōng shì."}],"cy":"Write a sentence joining two positive (or two negative) comments about the same thing with 而且.","ov":"","tw":"網路 (wǎnglù) is both the Taiwan word and Taiwan reading for internet; mainland 網絡 (wǎngluò). 濕 is also written 溼 in Taiwan.","src":"B2L6"},{"id":"n21-6","t":"Ⅵ. 什麼樣 vs 怎麼樣 · what kind of…","e":"Both mean 'what kind of N', but 什麼樣 leans on the observable/visible type (what it looks like), while 怎麼樣 leans on how something feels or comes across (character/quality). For objects, 什麼樣的 is the normal choice.","pat":"什麼樣的 + N and 怎麼樣的 + N both mean 'what kind of N'. 什麼樣 leans on 看起來 (looks like); 怎麼樣 leans on 感覺 (comes across as).","tgt":["什麼樣"],"alt":["怎麼樣","哪一種","什麼"],"s":[{"zh":"他是什麼樣的人？他很高、眼睛很大。","en":"What does he look like? He's tall, with big eyes.","py":"tā shì shén me yàng de rén? tā hěn gāo, yǎn jīng hěn dà."},{"zh":"他是怎麼樣的人？他對人很好、很客氣。","en":"What kind of person is he (character-wise)? He's nice to people, polite.","py":"tā shì zěn me yàng de rén? tā duì rén hěn hǎo, hěn kè qì."},{"zh":"你喜歡什麼樣的飲料／食物／房子／包包／衣服／工作？","en":"What kind of drinks/food/house/bag/clothes/job do you like?","py":"nǐ xǐ huān shén me yàng de yǐn liào ／ shí wù ／ fáng zi ／ bāo bāo ／ yī fú ／ gōng zuò?"}],"cy":"Write a question using 什麼樣的 + noun asking what kind (appearance) of something someone likes.","ov":"Don't confuse with bare 怎麼樣, which asks 'how is it?' (那家旅館怎麼樣？) rather than 'what kind?'. The 的 is what turns it into a 'what kind of' question.","tw":"包包 (bāobāo) is Taiwan's everyday word for a bag/handbag.","src":"B2L6"}],"22":[{"id":"n22-1","t":"以為 · I thought (wrongly)","e":"States a belief that turned out to be mistaken — the error is built into the word itself. For a belief that's still true, use 覺得 or 想 instead.","pat":"S + 以為 + clause = 'I assumed (and was wrong)'.","tgt":["以為"],"alt":["覺得","想","以致"],"s":[{"zh":"我以為垃圾車六點來，沒想到五點半就來了。","en":"I thought the garbage truck came at 6, but it turned out it came at 5:30.","py":"wǒ yǐ wéi lā jī chē liù diǎn lái, méi xiǎng dào wǔ diǎn bàn jiù lái le."},{"zh":"他以為紙杯可以回收，可是不行。","en":"He thought paper cups could be recycled, but they can't.","py":"tā yǐ wéi zhǐ bēi kě yǐ huí shōu, kě shì bù xíng."},{"zh":"我以為你今天不來了！","en":"I thought you weren't coming today!","py":"wǒ yǐ wéi nǐ jīn tiān bù lái le!"}],"cy":"Write a sentence using 以為 to describe a mistaken belief you had.","ov":"Contrast with B2 L4's 沒想到 (an unexpected outcome, with no claimed prior belief stated) and B2 L3's 想起來/沒想起來 (recall of something forgotten) — three related but distinct 想/以為 expressions worth telling apart.","tw":"","src":"B2L7"},{"id":"n22-2","t":"…，要不然… · otherwise","e":"States an instruction or plan, then what goes wrong if you don't follow it. Unlike 如果…就 (which can point either direction, good or bad), 要不然 only ever runs one way: do X, or else Y (bad).","pat":"Clause₁，要不然 (+ 就) + bad consequence. 'Do X, or else Y.' Shorter form 不然 means the same.","tgt":["要不然"],"alt":["如果...就","不然","否則"],"s":[{"zh":"你得把垃圾分類，要不然垃圾車不收。","en":"You have to sort your trash, or else the truck won't take it.","py":"nǐ dé bǎ lā jī fēn lèi, yào bù rán lā jī chē bù shōu."},{"zh":"快一點，要不然就追不到垃圾車了。","en":"Hurry up, or else you won't catch the garbage truck.","py":"kuài yì diǎn, yào bù rán jiù zhuī bú dào lā jī chē le."},{"zh":"我們現在去，要不然就太晚了。","en":"Let's go now, or it'll be too late.","py":"wǒ men xiàn zài qù, yào bù rán jiù tài wǎn le."}],"cy":"Write a sentence using 要不然 to state an instruction and the bad thing that happens if it's not followed.","ov":"要不然 vs 如果…就 (B2 L6): 如果 sets up a condition and can point either direction, good or bad — 如果你搬家了，我就少了一個朋友。 要不然 only ever runs one way — the first clause is what you should do, and what follows 要不然 is what goes wrong if you don't. Test: does 'or else' fit the English? Then 要不然. Saying the same thing with 如果 needs the sentence flipped and takes twice the words (如果你不快一點，就追不到垃圾車了) — that's what 要不然 is for.","tw":"","src":"B2L7"},{"id":"n22-3","t":"為了 + purpose，… · in order to","e":"States the goal you're acting toward, looking forward — contrast with 因為 (the reason/cause, looking back at what caused something).","pat":"為了 + goal (noun or VP)，+ what you do. Usually leads the sentence.","tgt":["為了"],"alt":["因為","為","由於"],"s":[{"zh":"為了保護環境，台灣人天天做垃圾分類。","en":"In order to protect the environment, Taiwanese people sort their trash every day.","py":"wèi le bǎo hù huán jìng, tái wān rén tiān tiān zuò lā jī fēn lèi."},{"zh":"為了利用資源，紙、瓶子、塑膠都要回收。","en":"In order to make use of resources, paper, bottles, and plastic all need to be recycled.","py":"wèi le lì yòng zī yuán, zhǐ, píng zi, sù jiāo dōu yào huí shōu."},{"zh":"我為了學中文來台灣。","en":"I came to Taiwan in order to learn Chinese.","py":"wǒ wèi le xué zhōng wén lái tái wān."},{"zh":"我因為喜歡台灣，所以來台灣。","en":"Because I like Taiwan, I came to Taiwan.","py":"wǒ yīn wèi xǐ huān tái wān, suǒ yǐ lái tái wān."}],"cy":"Write a minimal pair: one sentence with 為了 (the goal) and one with 因為…所以 (the cause) for the same action.","ov":"The minimal pair to memorize: 我為了學中文來台灣 (why I came — the goal, forward-looking) vs 我因為喜歡台灣，所以來台灣 (what caused it — the reason, backward-looking). Test: could you say 'in order to' in front of it in English? Then 為了. And 為了 takes a goal, not a whole cause-clause with 所以 hanging off it — ✗為了我喜歡台灣，所以來台灣。","tw":"為 is read in 4th tone in both 為了 and 因為 here.","src":"B2L7"},{"id":"n22-4","t":"Directional complements: V + 出／進／過 + 來／去","e":"Combines a motion verb with a direction word (out, in, across/over, up, down) and then 來/去 to say which way something moved relative to the speaker — toward the speaker (來) or away (去). With an object, 把 O + V + direction is the cleanest structure.","pat":"Motion verb + direction (出 out, 進 in, 過 across/over, 上 up, 下 down) + 來／去 (toward／away from the speaker). With an object: 把 O + V + direction.","tgt":["出來","進去","來/去"],"alt":["到","在","給"],"s":[{"zh":"她拿著垃圾走出來了。","en":"She came out carrying the trash.","py":"tā ná zhù lā jī zǒu chū lái le."},{"zh":"垃圾車開過來了。","en":"The garbage truck is coming this way.","py":"lā jī chē kāi guò lái le."},{"zh":"他走過去跟他們聊天。","en":"He walked over to chat with them.","py":"tā zǒu guò qù gēn tā men liáo tiān."},{"zh":"把瓶子丟進去。","en":"Throw the bottle in.","py":"bǎ píng zi diū jìn qù."},{"zh":"把袋子放下。","en":"Put the bag down.","py":"bǎ dài zi fàng xià."}],"cy":"Write a sentence using a motion verb + direction + 來/去, thinking carefully about where you (the speaker) are standing.","ov":"This is the same 來／去 already met in B2 L6 (Ⅰ, add-on 3). There it was 到 + place + 來／去: 我把書搬到樓上去了 (I'm downstairs) vs 你把書搬到樓上來吧 (I'm already upstairs). Nothing about the 來／去 half changes here: it never names a destination, it says where you are standing, and it still lands at the very end. New in L7: what sits in front of it is no longer 到+place but a bare direction (出／進／過／上／下), so the endpoint can go unsaid — 走出來 = came out (of somewhere we both already know). Same tail, shorter body. The trap: don't hang a place off the short form (✗走出來教室 ✓從教室走出來 ✓走出教室來); the test is still 'am I inside or outside?' (你進來 vs 你進去). Also related — the 把 family gets a third ending: B1 L15 把 O V 了 → B2 L6 把 O V 到／在／給 → here, 把 O V + direction (把瓶子丟進去, 把書拿出來). Frame unchanged: definite object, 不／沒／別 before 把, and something always after the verb.","tw":"垃圾 is read lèsè in Taiwan; mainland lājī.","src":"B2L7"},{"id":"n22-5","t":"一定的 + N · fixed, set","e":"Describes a fixed or set noun — a schedule, place, or rule that doesn't vary. Different from the adverb 一定 (definitely), which modifies a verb; the 的 signals which meaning is meant.","pat":"一定的 + N = a fixed / set N.","tgt":["一定的"],"alt":["一定","固定的","特定的"],"s":[{"zh":"垃圾車有一定的時間和一定的地點。","en":"The garbage truck has a fixed time and a fixed location.","py":"lā jī chē yǒu yí dìng de shí jiān hé yí dìng de dì diǎn."},{"zh":"回收有一定的規定。","en":"Recycling has fixed/set regulations.","py":"huí shōu yǒu yí dìng de guī dìng."}],"cy":"Write a sentence describing something as fixed or set using 一定的 + noun, then contrast it with 一定 as 'definitely' before a verb.","ov":"","tw":"","src":"B2L7"}],"23":[{"id":"n23-1","t":"見 · perceptual result (saw / heard)","e":"看／聽 + 見 means the looking or listening actually landed: the sight or sound reached you, as opposed to bare 看／聽 which only names the attempt.","pat":"看／聽 + 見 = the looking or listening landed; negation is 沒 (沒看見／沒聽見); potential forms 看得見／聽不見 belong to 語法 4","tgt":["見","看見","聽見"],"alt":["沒聽 (didn't listen, a choice) vs 沒聽見 (no sound reached me)","看到／聽到 (到 = general 'managed to'; 見 = perception only; ✗買見 ✗找見)","聽見 (sound got through) vs 聽懂 (meaning got through)"],"s":[{"zh":"昨天我在夜市看見小美了。","en":"Yesterday I saw Xiaomei at the night market."},{"zh":"你說的，我都聽見了。","en":"I heard everything you said."},{"zh":"你為什麼在找書？我們都看見你把書拿回去了。","en":"Why are you looking for the book? We all saw you take it back."},{"zh":"東西在哪裡？我沒看見啊！","en":"Where is the thing? I didn't see it!"},{"zh":"我沒聽見他說什麼。","en":"I didn't hear what he said."},{"zh":"請你再說一次，我沒聽見。","en":"Please say it again, I didn't hear."},{"zh":"我的背包，你看見了沒有？","en":"Have you seen my backpack?"},{"zh":"老師說的，你是不是聽見了？","en":"Did you hear what the teacher said?"},{"zh":"張先生呢？你看見他走出來了嗎？","en":"Where is Mr. Zhang? Did you see him come out?"},{"zh":"對不起，沒聽見你叫我。— 音樂那麼吵，你當然聽不見。","en":"Sorry, I didn't hear you call me. — With music that loud, of course you couldn't hear."},{"zh":"一到學校門口，就看見你推著腳踏車走過來。","en":"As soon as I got to the school gate I saw you walking over pushing your bike."},{"zh":"上課的時候學生在聊天，沒聽老師說的話。","en":"During class the students were chatting and didn't listen to what the teacher said. (didn't listen to)"}],"cy":"Write your own sentence with 「見」 using this lesson's words.","src":"MTC","tw":"腳踏車 (大陸 自行車) · 夜市; Taiwan speech leans toward 看到／聽到 but the book teaches 見, so write 見 on the 考試","ov":"看見 wraps earlier grammar: 看見你把書拿回去了 = B2 L7 語法 2 把 + 方向補語; 看見你推著腳踏車走過來 = B2 L1 V 著 + B2 L7 走過來; 聽見 was already a 語句 on L7's 聽寫二"},{"id":"n23-2","t":"懂 · cognitive result (understood)","e":"聽／看 + 懂 means you understood by ear or by eye: the verb names the channel and 懂 names the result, with negation always 沒 for the compound.","pat":"聽／看 + 懂 = understood, by ear or by eye; negation of the V + 懂 compound is always 沒 (沒聽懂／沒看懂)","tgt":["懂","聽懂","看懂"],"alt":["聽見 (sound reached me) vs 聽懂 (meaning reached me)","不懂 (standing state: 我不懂中文) vs 沒聽懂 (that one attempt failed)","沒看懂／看懂了 (fact, more time on this try) vs 看不懂／看得懂 (capability, she herself had to change)"],"s":[{"zh":"老師說的，我都聽懂了。","en":"I understood everything the teacher said."},{"zh":"老師給的功課我只聽了一次，就聽懂了。","en":"I only listened once to the homework the teacher gave and understood it."},{"zh":"老師寫的那些字，學生都看懂了。","en":"The students all understood the characters the teacher wrote."},{"zh":"他說什麼？我沒聽懂。","en":"What did he say? I didn't understand."},{"zh":"那個電影我第一次沒看懂，第二次看懂了。","en":"I didn't understand that movie the first time; the second time I understood it."},{"zh":"老師說明了半天，可是我沒聽懂。","en":"The teacher explained for ages, but I didn't understand."},{"zh":"他剛說的，你是不是聽懂了？","en":"Did you understand what he just said?"},{"zh":"這些資料你都看懂了沒有？","en":"Have you understood all this material?"},{"zh":"老師教的，你聽懂沒聽懂？","en":"What the teacher taught, did you understand it or not?"},{"zh":"老師教的，你懂了嗎？／ 你聽懂了嗎？／ 你看懂了嗎？","en":"What the teacher taught, do you understand? / Did you understand (by listening)? / Did you understand (by reading)?"},{"zh":"他說中文你聽得懂嗎？— 剛開始我都聽不懂，可是現在沒問題了。","en":"Can you understand him when he speaks Chinese? — At first I couldn't understand at all, but now it's no problem."},{"zh":"我剛剛說的，你懂嗎？— 我不太懂，請再說明一次。","en":"Do you understand what I just said? — Not really, please explain once more."}],"cy":"Write your own sentence with 「懂」 using this lesson's words.","src":"MTC","tw":"隨身碟 (大陸 U盤) · 那個法國電影: 法國 is Fàguó here, Fǎguó on the mainland · 懂 ＝ 明白 (teacher's synonym)","ov":"只聽了一次，就聽懂了 is B1 L11's 就 (sooner than expected), mirrored by 語法 3's 才學會; 不懂 vs 沒聽懂 is L7's 不／沒 rule unchanged"},{"id":"n23-3","t":"會 · achievement result (mastered)","e":"學／教／練 + 會 means the skill stuck: 學會 the subject gets it, 教會 the object gets it, and the skill follows as a VP, a 怎麼-clause or a noun.","pat":"學／教／練 + 會 (+ skill: VP, 怎麼-clause or noun); 學會 = the subject acquires it, 教會 = the object acquires it; 還沒學會 = not yet","tgt":["會","學會","教會","練會"],"alt":["學了 (put the time in) vs 學會了 (it worked)","還沒學會 (hasn't happened yet, more time fixes it) vs 學不會 (more time won't fix it)","會 before the verb (skill B1 L5 / will B1 L11) vs V + 會 after the verb (result)"],"s":[{"zh":"我在大學的時候學會怎麼開車。","en":"I learned how to drive when I was at university."},{"zh":"只有一個鐘頭的課，老師要教會學生怎麼寫書法很難。","en":"With only a one-hour class, it's hard for the teacher to teach the students how to write calligraphy."},{"zh":"學生學會了用中文介紹自己。","en":"The students learned to introduce themselves in Chinese."},{"zh":"我學游泳只學了一個禮拜，還沒學會。","en":"I've only studied swimming for a week and haven't learned it yet."},{"zh":"師父教了兩個星期了，還沒教會馬安同太極拳最難的動作。","en":"The master has been teaching for two weeks and still hasn't taught Ma Antong the hardest tai chi move."},{"zh":"我們都沒學會怎麼騎腳踏車。","en":"None of us learned how to ride a bike."},{"zh":"這些字你是不是都學會了？","en":"Have you learned all these characters?"},{"zh":"太極拳學了這麼久，你還沒學會啊？","en":"You've studied tai chi this long and still haven't learned it?"},{"zh":"馬安同教會那些小孩踢足球了沒有？","en":"Has Ma Antong taught those kids to play football yet?"},{"zh":"我學了三個多月了，才學會了一點。","en":"I've been studying for over three months and have only learned a little."},{"zh":"我會說中文，而且我說得很流利。","en":"I can speak Chinese, and I speak it fluently. (會 = knowing a skill)"},{"zh":"明天晚上我們會一起去吃飯。","en":"Tomorrow evening we will go eat together. (會 = possibility, will)"}],"cy":"Write your own sentence with 「會」 using this lesson's words.","src":"MTC","tw":"禮拜 ≈ 星期 (interchangeable in Taiwan speech, 禮拜 more casual); 星期 is xīngqí here; 師父 printed with full 4th tone shīfù (大陸 neutral)","ov":"會 now has three jobs: skill (B1 L5) and will (B1 L11) before the verb, result after the verb here; 學了三個多月了，才學會了一點 stacks B1 L14 double 了 + B2 L3 才 + 學會"},{"id":"n23-4","t":"V 得／不 C · potential (can / can't)","e":"Wedging 得 or 不 between the verb and its complement turns any result or directional compound into can / can't, answering 能不能 rather than 做沒做.","pat":"V + 得 + C = the result can be reached ／ V + 不 + C = it can't; A-not-A repeats the whole thing (聽得懂聽不懂？)","tgt":["得","不","V得C","V不C"],"alt":["沒 V C (didn't, one occasion) vs V 不 C (can't, standing ability)","不能 + V (forbidden by a rule or person) vs V 不 C (the attempt fails)","manner 得 (學得不好, keeps 得 and adds 不 after) vs potential (學不會, 不 replaces 得; ✗聽得不懂)"],"s":[{"zh":"我看得懂中國電影。","en":"I can understand Chinese movies."},{"zh":"垃圾車的音樂雖然很小，但是我聽得見。","en":"Although the garbage truck's music is very quiet, I can hear it."},{"zh":"早上八點，我當然起得來。","en":"Eight in the morning, of course I can get up."},{"zh":"師父教的這個動作很容易，每個人都學得會。","en":"This move the master teaches is easy; everyone can learn it."},{"zh":"我認識他，但是他的名字我想不起來。","en":"I know him, but I can't recall his name."},{"zh":"夜市太吵了，他聽不見我叫他。","en":"The night market is too noisy; he can't hear me calling him."},{"zh":"半夜三點太早了，誰也起不來。","en":"Three in the morning is too early; nobody can get up."},{"zh":"老師上課，你聽得懂聽不懂？","en":"In class, can you understand the teacher or not?"},{"zh":"廣告上的字那麼小，你是不是看不見？","en":"The writing on the ad is so small, can't you see it?"},{"zh":"只有一個星期，他們學得會學不會一百個漢字？","en":"With only one week, can they learn a hundred characters or not?"},{"zh":"我沒看見那個人從七樓走上來。","en":"I didn't see that person come up from the seventh floor. (it didn't happen — record)"},{"zh":"我在十樓，所以看不見七樓的人。","en":"I'm on the tenth floor, so I can't see people on the seventh. (it can't happen — ability)"}],"cy":"Write your own sentence with 「得」 using this lesson's words.","src":"MTC","tw":"垃圾車 lèsèchē (大陸 lājī) · 漢字 is textbook register; on the street in Taiwan it's 中文字 or 國字","ov":"Extension of B2 L7 語法 1: the slot after V1 that L7 filled with 了 (走了出來) now takes 得／不 (走得出來／走不出來), so all twelve L7 directionals gain potential forms; 誰也起不來 is B1 L13's QW + 也／都; this is the teacher's 能不能？ row of the 結果補語 frame"},{"id":"n23-5","t":"了 liǎo · generic capability complement","e":"V 得了／不了 (liǎo, 3rd tone) is the generic 'can manage to V at all' complement used when no specific result word fits, and it exists only in the potential row.","pat":"V + 得了／不了 (liǎo); ✓V 得了 ✓V 不了 ✗V 了(liǎo) ✗沒 V 了(liǎo); object follows: 回不了家・喝不了奶茶","tgt":["了","得了","不了"],"alt":["V 不了 (can't manage it at all) vs V 不完 (can't finish, leftovers)","了 liǎo (after 得／不) vs 了 le (aspect / change of situation: 去不了了)","V 得了 vs a specific result word (爬得上去 / 起不來) — both accepted, 了 is the fallback"],"s":[{"zh":"這碗牛肉麵，我一個人吃得了。","en":"This bowl of beef noodles, I can eat it by myself."},{"zh":"這麼多書，我拿不了。","en":"So many books, I can't carry them."},{"zh":"颱風來了，今天晚上的喜宴我們去不了了。","en":"The typhoon is here; we can't go to tonight's wedding banquet after all."},{"zh":"到現在我還忘不了第一個女朋友。","en":"To this day I still can't forget my first girlfriend."},{"zh":"還要走半個小時，你走得了走不了？","en":"There's another half hour to walk; can you make it or not?"},{"zh":"我們點了五個菜，吃得了吃不了？","en":"We ordered five dishes; can we manage them or not?"},{"zh":"雪這麼大，今天我們到得了山上嗎？","en":"With snow this heavy, can we get up the mountain today?"},{"zh":"腿也痛得走不了路。","en":"My legs hurt so much I can't walk."},{"zh":"左邊的先生很餓，他吃得了15個漢堡。右邊的先生一點也不餓，他吃不了15個漢堡。","en":"The man on the left is very hungry; he can eat 15 hamburgers. The man on the right isn't hungry at all; he can't eat 15 hamburgers."},{"zh":"小姐買了很多東西，先生快拿不了了。","en":"The lady bought a lot of things; the man is about to be unable to carry them."},{"zh":"她帶了袋子去買東西，所以自己就拿得了了。","en":"She took a bag to go shopping, so now she can carry it herself."},{"zh":"他們想出去玩，可是雨太大了，所以他們去不了。","en":"They want to go out, but the rain is too heavy, so they can't go."}],"cy":"Write your own sentence with 「了」 using this lesson's words.","src":"MTC","tw":"颱風 (mainland writes 台风) · 珍珠奶茶 (Taiwan's own drink) · 妳 (feminine 'you', Taiwan only) · 痛 for every kind of hurt (northern mainland 疼) · 受不了 heard constantly in Taipei","ov":"了 gains a new member that sounds different: everything before was le (B1 L10 change → B1 L13 finished → B1 L14 → B2 L3 → B2 L7); 走不了路 puts the complement inside a separable verb (B1 L15 V-SEP), same rule as 語法 8's 考完試"},{"id":"n23-6","t":"Vs 得 + complement · so… that…","e":"A state verb followed by 得 and a clause states an extent and its consequence ('so tired that I can't get up'), with the clause often carrying its own subject or a comparison.","pat":"Vs + 得 + (its own subject) + VP; the Vs itself is never negated (✗不累得…); the slot takes a potential (拿不了), an event (睡了一天的覺) or a comparison (像過年／跟…一樣)","tgt":["得","Vs得"],"alt":["太…了 (two statements side by side: 太累了，起不來) vs Vs 得… (one statement with the consequence built in); ✗太累得起不來","manner 得 (V 得 + rating) and potential 得 (V 得 + result word) vs extent 得 (Vs 得 + clause)","跟 needs 一樣, 像 doesn't: ✓像過年 ✓跟過年一樣 ✗跟過年"],"s":[{"zh":"我常常累得起不來，腿也痛得走不了路。","en":"I'm often so tired I can't get up, and my legs hurt so much I can't walk."},{"zh":"天氣冷得很多人不想去上班。","en":"The weather is so cold that many people don't want to go to work."},{"zh":"夜市裡到處都是人，熱鬧得像過年。","en":"There are people everywhere in the night market; it's as lively as New Year."},{"zh":"林教授的演講，複雜得我聽不懂。","en":"Professor Lin's lecture was so complicated I couldn't understand it."},{"zh":"他去夜市買了很多東西，多得拿不了。","en":"He bought so many things at the night market that he couldn't carry them."},{"zh":"他腿痛得跑不完一百公尺。","en":"His legs hurt so much he couldn't finish running a hundred metres."},{"zh":"你是不是累得走不了了？","en":"Are you so tired you can't walk any more?"},{"zh":"這個房子是不是小得住不了五個人？","en":"Is this house so small that five people can't live in it?"},{"zh":"那家麵包店賣的蛋糕是不是甜得你吃不了？","en":"Is the cake that bakery sells so sweet you can't eat it?"},{"zh":"她精神差得好像三天沒睡覺。","en":"She looks so worn out it's as if she hadn't slept for three days."},{"zh":"我餓得吃得了一百個小籠包。","en":"I'm so hungry I could eat a hundred xiaolongbao."},{"zh":"這個地方好玩得我不想離開。","en":"This place is so much fun I don't want to leave."}],"cy":"Write your own sentence with 「得」 using this lesson's words.","src":"MTC","tw":"公尺 is Taiwan-only for metre (大陸 米; 公分 vs 厘米 splits the same way) · 小籠包 · 麵包店 · 精神 jīngshén with full tone","ov":"Extension of B2 L5 Vs 得不得了: the slot that L5 froze to 不得了 now takes any clause; the 'negation' examples are 語法 4／5／8 potential-negatives sitting inside it (累得起不來 = 6 wrapped round 4); 熱鬧得像過年 is B1 L13's 像／跟…一樣 comparison inside 得, and 到處都 is B1 L13's QW + 都"},{"id":"n23-7","t":"V + 下去 · keep on doing / continue","e":"An activity verb plus 下去 means carrying on from now into the future, usually with 還／再／一直 and a modal, and nothing may follow 下去 so the object is fronted or dropped.","pat":"(Topic) + S + V + 下去 = continue V-ing; ✓這個工作我想一直做下去 ✗做下去這個工作; takes 得／不: 念得下去／念不下去","tgt":["下去"],"alt":["direction 下去 (B2 L7: 走下去・拿下樓去 = down, away from me) vs time 下去 (說下去・等下去 = onward; test: replace with 繼續 + V)","繼續 + V (before the verb, setup zone) vs V + 下去 (after the verb, outcome zone)","V 不了 takes an object after it (喝不了奶茶) but 下去 does not (✗學下去中文)"],"s":[{"zh":"你說得很好，請你再說下去。","en":"You're speaking well; please go on."},{"zh":"我們在夜市逛了很久了，你還要逛下去嗎？","en":"We've been wandering the night market for a long time; do you still want to keep going?"},{"zh":"雖然學費不便宜，但是我還想念下去。","en":"Although tuition isn't cheap, I still want to keep studying."},{"zh":"他還沒說完，請大家聽下去。","en":"He hasn't finished; please keep listening, everyone."},{"zh":"這份工作不錯，雖然薪水少，可是我還要做下去。","en":"This job is good; although the pay is low, I still want to keep doing it."},{"zh":"已經三個小時了，你還要等下去嗎？我想他不會來了。","en":"It's been three hours already; do you still want to keep waiting? I don't think he's coming."},{"zh":"外面這麼吵，你念得下去嗎？","en":"It's so noisy outside; can you keep studying?"},{"zh":"這個工作我想一直做下去。（✗我想一直做下去這個工作了。）","en":"This job, I want to keep doing it. (object must be fronted)"},{"zh":"雖然很累，我還要念下去。（✗…我還要念下去中文。）","en":"Although I'm tired, I still want to keep studying. (no object after 下去)"},{"zh":"那你怎麼還學得下去？","en":"Then how can you still bear to keep learning it?"},{"zh":"你跟我一起下去吃飯吧！","en":"Come downstairs with me to eat! (direction + reference)"},{"zh":"他把水拿下樓去了。","en":"He took the water downstairs. (direction + reference)"}],"cy":"Write your own sentence with 「下去」 using this lesson's words.","src":"MTC","tw":"薪水 (大陸 工資) · 念書／念下去: Taiwan says 念書 where the mainland says 讀書 or 學習","ov":"下去 now has two jobs: direction (B2 L7 語法 1) and time (here); same last-word rule as L7 but stricter (去 is the last thing out of your mouth); 他還是得學下去 is 得 děi (B2 L1), giving 得 five jobs across the lesson; 我等她等了一個小時了 is B1 L14 double 了"},{"id":"n23-8","t":"V + 完 · completion (finished)","e":"Action verb + 完 marks that the action ran to its end and the thing is used up, and it fills all four cells of the frame (喝完了・還沒吃完・跑得完・跑不完).","pat":"action V + 完 (+ O) + 了; separable verbs keep 完 inside: 考完試・吃完飯・游完泳 (✗考試完)","tgt":["完"],"alt":["V 了 (the event is on the record, maybe partly) vs V 完了 (to the very end, nothing left)","V 不完 (can't finish, leftovers) vs V 不了 (can't manage it at all)","✗考試完 — the complement goes between V and O of a separable verb"],"s":[{"zh":"他們已經喝完咖啡了。","en":"They've already finished their coffee."},{"zh":"你借給我的書，我都看完了。","en":"The books you lent me, I've finished them all."},{"zh":"這個月的薪水，我都用完了。","en":"This month's salary, I've used it all up."},{"zh":"一千公尺我跑得完。","en":"A thousand metres, I can finish running it."},{"zh":"別買水果了，家裡的還沒吃完呢！","en":"Don't buy fruit; we haven't finished what's at home yet!"},{"zh":"我還沒說完，可以再給我一點時間嗎？","en":"I haven't finished speaking; could you give me a little more time?"},{"zh":"他工作沒做完，就去花蓮旅行了，所以老闆很不高興。","en":"He went travelling to Hualien without finishing his work, so the boss was unhappy."},{"zh":"你是不是考完試了？","en":"Have you finished your exam?"},{"zh":"老師給的功課，你寫完了沒有？","en":"Have you finished the homework the teacher gave?"},{"zh":"那些電影，你看完了沒有？","en":"Have you finished watching those movies?"},{"zh":"我考完試，想去看電影。（✗我考試完…）","en":"After I finish the exam, I want to go see a movie."},{"zh":"你們吃完飯，可以去夜市逛逛。","en":"After you finish eating, you can go wander the night market."}],"cy":"Write your own sentence with 「完」 using this lesson's words.","src":"MTC","tw":"薪水 (大陸 工資) · 功課 for homework (大陸 作業) · 花蓮 · 老闆","ov":"Separable verbs again (B1 L15 V-SEP): 完 goes inside, same rule as 走不了路; V 完 is the clean way to fill B1 L15's V 了…就… and B1 L12's 先…再… (做完了功課，再去練習)"}],"24":[{"t":"Resultative 好 and 到","e":"Resultative 好 and 到","tgt":["好","到"],"alt":[],"s":[{"zh":"票訂好了嗎？","en":"Has the ticket been properly booked?","py":"piào dìng hǎo le ma?"},{"zh":"行李準備好了。","en":"The luggage is all packed and ready.","py":"xíng lǐ zhǔn bèi hǎo le."},{"zh":"找到了嗎？","en":"Did you find it?","py":"zhǎo dào le ma?"}],"cy":"Write your own sentence using 「好」.","id":"g24-1"},{"t":"比起來 — Compared To","e":"Compared To","tgt":["比起來"],"alt":[],"s":[{"zh":"跟台北比起來，高雄比較熱。","en":"Compared to Taipei, Kaohsiung is hotter.","py":"gēn tái běi bǐ qǐ lái, gāo xióng bǐ jiào rè."},{"zh":"跟城市比起來，鄉下比較安靜。","en":"Compared to cities, the countryside is quieter.","py":"gēn chéng shì bǐ qǐ lái, xiāng xià bǐ jiào ān jìng."},{"zh":"跟北部比起來，南部的人比較熱情。","en":"Compared to the north, southerners are more hospitable.","py":"gēn běi bù bǐ qǐ lái, nán bù de rén bǐ jiào rè qíng."}],"cy":"Write your own sentence using 「比起來」.","id":"g24-2"},{"t":"極了 — Extremely","e":"Extremely","tgt":["極了"],"alt":[],"s":[{"zh":"風景美極了。","en":"The scenery was absolutely beautiful.","py":"fēng jǐng měi jí le."},{"zh":"食物好吃極了。","en":"The food was incredibly delicious.","py":"shí wù hǎo chī jí le."},{"zh":"氣氛熱鬧極了。","en":"The atmosphere was incredibly lively.","py":"qì fēn rè nào jí le."}],"cy":"Write your own sentence using 「極了」.","id":"g24-3"},{"t":"越來越 — More and More","e":"More and More","tgt":["越來越"],"alt":[],"s":[{"zh":"城市越來越現代。","en":"The city is becoming more and more modern.","py":"chéng shì yuè lái yuè xiàn dài."},{"zh":"物價越來越高。","en":"Prices are going higher and higher.","py":"wù jià yuè lái yuè gāo."},{"zh":"中文越來越有意思。","en":"Chinese is getting more and more interesting.","py":"zhōng wén yuè lái yuè yǒu yì si."}],"cy":"Write your own sentence using 「越來越」.","id":"g24-4"},{"t":"各 — Various","e":"Various","tgt":["各"],"alt":[],"s":[{"zh":"海裡有各種顏色的魚。","en":"The sea has fish of all different colors.","py":"hǎi lǐ yǒu gè zhǒng yán sè de yú."},{"zh":"各地的建築都不一樣。","en":"The buildings in each place are different.","py":"gè dì de jiàn zhù dōu bù yí yàng."}],"cy":"Write your own sentence using 「各」.","id":"g24-5"},{"t":"忘不了 — Unforgettable","e":"Unforgettable","tgt":["忘不了"],"alt":[],"s":[{"zh":"忘不了那個味道。","en":"I can't forget that taste.","py":"wàng bù liǎo nà ge wèi dào."},{"zh":"忘不了南部的熱情。","en":"Can't forget the warmth of the south.","py":"wàng bù liǎo nán bù de rè qíng."}],"cy":"Write your own sentence using 「忘不了」.","id":"g24-6"},{"t":"買得起 — Can Afford","e":"Can Afford","tgt":["買得起"],"alt":[],"s":[{"zh":"那個公寓你買得起嗎？","en":"Can you afford that apartment?","py":"nà ge gōng yù nǐ mǎi de qǐ ma?"},{"zh":"生活費低，什麼都買得起。","en":"Costs are low; you can afford everything.","py":"shēng huó fèi dī, shén me dōu mǎi de qǐ."}],"cy":"Write your own sentence using 「買得起」.","id":"g24-7"}],"25":[{"t":"趁 — While / Seizing the Chance","e":"While / Seizing the Chance","tgt":["趁"],"alt":[],"s":[{"zh":"趁學期還沒開始，多練習。","en":"While the semester hasn't started, practice more.","py":"chèn xué qī hái méi kāi shǐ, duō liàn xí."},{"zh":"趁熱吃。","en":"Eat it while it's hot.","py":"chèn rè chī."},{"zh":"趁機會學。","en":"Take the opportunity to learn.","py":"chèn jī huì xué."}],"cy":"Write your own sentence using 「趁」.","id":"g25-1"},{"t":"下 — Enough Space To","e":"Enough Space To","tgt":["下"],"alt":[],"s":[{"zh":"飯廳坐得下嗎？","en":"Can the dining room fit everyone?","py":"fàn tīng zuò dé xià ma?"},{"zh":"這個鍋子裝得下嗎？","en":"Can this pot hold everything?","py":"zhè ge guō zi zhuāng dé xià ma?"},{"zh":"我已經飽了，吃不下了。","en":"I'm already full — no room for more.","py":"wǒ yǐ jīng bǎo le, chī bù xià le."}],"cy":"Write your own sentence using 「下」.","id":"g25-2"},{"t":"光 — All Gone","e":"All Gone","tgt":["光"],"alt":[],"s":[{"zh":"水餃被吃光了。","en":"The dumplings are completely gone.","py":"shuǐ jiǎo bèi chī guāng le."},{"zh":"材料用光了。","en":"All the ingredients are used up.","py":"cái liào yòng guāng le."},{"zh":"票賣光了。","en":"Sold out.","py":"piào mài guāng le."}],"cy":"Write your own sentence using 「光」.","id":"g25-3"},{"t":"看不出來 — Can't Tell","e":"Can't Tell","tgt":["看不出來"],"alt":[],"s":[{"zh":"看不出來你會包餃子。","en":"I wouldn't have guessed you can wrap dumplings.","py":"kàn bù chū lái nǐ huì bāo jiǎo zi."},{"zh":"看不出來你是外國人。","en":"You can't tell you're a foreigner.","py":"kàn bù chū lái nǐ shì wài guó rén."},{"zh":"看不出來你這麼厲害！","en":"I couldn't tell you were this skilled!","py":"kàn bù chū lái nǐ zhè me lì hài!"}],"cy":"Write your own sentence using 「看不出來」.","id":"g25-4"},{"t":"做起來 — When You Actually Do It","e":"When You Actually Do It","tgt":["做起來"],"alt":[],"s":[{"zh":"做起來不難。","en":"It's not hard when you actually do it.","py":"zuò qǐ lái bù nán."},{"zh":"吃起來很特別。","en":"It tastes interesting when you eat it.","py":"chī qǐ lái hěn tè bié."},{"zh":"做起來比想像的容易。","en":"Easier in practice than imagined.","py":"zuò qǐ lái bǐ xiǎng xiàng de róng yì."}],"cy":"Write your own sentence using 「做起來」.","id":"g25-5"},{"t":"像 — Such As / Similar To","e":"Such As / Similar To","tgt":["像"],"alt":[],"s":[{"zh":"泡菜像台灣的醃菜。","en":"Kimchi is like Taiwanese pickled vegetables.","py":"pào cài xiàng tái wān de yān cài."},{"zh":"很多食物，像壽司、餃子，都需要手工。","en":"Many foods, like sushi and dumplings, need handwork.","py":"hěn duō shí wù, xiàng shòu sī, jiǎo zi, dōu xū yào shǒu gōng."}],"cy":"Write your own sentence using 「像」.","id":"g25-6"}],"26":[{"t":"被 — The Passive","e":"The Passive","tgt":["被"],"alt":[],"s":[{"zh":"錢包被人偷了。","en":"The wallet was stolen.","py":"qián bāo bèi rén tōu le."},{"zh":"票被買完了。","en":"The tickets were all bought up.","py":"piào bèi mǎi wán le."},{"zh":"我被他罵了。","en":"I got scolded by him.","py":"wǒ bèi tā mà le."}],"cy":"Write your own sentence using 「被」.","id":"g26-1"},{"t":"順便 — While You're At It","e":"While You're At It","tgt":["順便"],"alt":[],"s":[{"zh":"去台中，順便去日月潭看看。","en":"Going to Taichung — visit Sun Moon Lake while there.","py":"qù tái zhōng, shùn biàn qù rì yuè tán kàn kàn."},{"zh":"去超商，順便幫我買瓶水。","en":"Going to the store — grab me some water while you're at it.","py":"qù chāo shāng, shùn biàn bāng wǒ mǎi píng shuǐ."},{"zh":"去郵局的路上，我順便去了一下銀行。","en":"On the way to the post office, I stopped by the bank.","py":"qù yóu jú de lù shàng, wǒ shùn biàn qù le yī xià yín háng."}],"cy":"Write your own sentence using 「順便」.","id":"g26-2"},{"t":"後來 — Later On","e":"Later On","tgt":["後來"],"alt":[],"s":[{"zh":"我找不到錢包，後來才發現被偷了。","en":"Couldn't find my wallet; later realized it was stolen.","py":"wǒ zhǎo bú dào qián bāo, hòu lái cái fā xiàn bèi tōu le."},{"zh":"計畫改了很多次，後來決定去墾丁。","en":"The plan changed many times; in the end we picked Kenting.","py":"jì huà gǎi le hěn duō cì, hòu lái jué dìng qù kěn dīng."}],"cy":"Write your own sentence using 「後來」.","id":"g26-3"},{"t":"愛上 — To Fall In Love With","e":"To Fall In Love With","tgt":["愛上"],"alt":[],"s":[{"zh":"我愛上了墾丁。","en":"I fell in love with Kenting.","py":"wǒ ài shàng le kěn dīng."},{"zh":"他愛上了台灣的生活。","en":"He fell in love with life in Taiwan.","py":"tā ài shàng le tái wān de shēng huó."}],"cy":"Write your own sentence using 「愛上」.","id":"g26-4"},{"t":"趟 and 遍 — Trips and Times","e":"Trips and Times","tgt":["趟","遍"],"alt":[],"s":[{"zh":"我去了三趟日月潭。","en":"I made three trips to Sun Moon Lake.","py":"wǒ qù le sān tàng rì yuè tán."},{"zh":"我看了三遍這部電影。","en":"I watched this film three times through.","py":"wǒ kàn le sān biàn zhè bù diàn yǐng."}],"cy":"Write your own sentence using 「趟」.","id":"g26-5"}],"27":[{"t":"讓 — To Let / Make","e":"To Let / Make","tgt":["讓"],"alt":[],"s":[{"zh":"漢堡讓人變胖。","en":"Hamburgers make people fat.","py":"hàn bǎo ràng rén biàn pàng."},{"zh":"這個消息讓我很高興。","en":"This news makes me very happy.","py":"zhè ge xiāo xī ràng wǒ hěn gāo xìng."},{"zh":"讓我試試看。","en":"Let me try.","py":"ràng wǒ shì shì kàn."}],"cy":"Write your own sentence using 「讓」.","id":"g27-1"},{"t":"只要 — As Long As","e":"As Long As","tgt":["只要"],"alt":[],"s":[{"zh":"只要不吃肉，就算素食。","en":"As long as you don't eat meat, it counts as vegetarian.","py":"zhǐ yào bù chī ròu, jiù suàn sù shí."},{"zh":"只要你喜歡，就可以吃。","en":"As long as you like it, you can eat it.","py":"zhǐ yào nǐ xǐ huān, jiù kě yǐ chī."},{"zh":"只要有青菜就好，不用其他的。","en":"Vegetables are enough — nothing else needed.","py":"zhǐ yào yǒu qīng cài jiù hǎo, bù yòng qí tā de."}],"cy":"Write your own sentence using 「只要」.","id":"g27-2"},{"t":"變 — To Become","e":"To Become","tgt":["變"],"alt":[],"s":[{"zh":"最近變胖了。","en":"I've been putting on weight lately.","py":"zuì jìn biàn pàng le."},{"zh":"天氣變了。","en":"The weather has changed.","py":"tiān qì biàn le."},{"zh":"台灣變得越來越現代。","en":"Taiwan is becoming more and more modern.","py":"tái wān biàn dé yuè lái yuè xiàn dài."}],"cy":"Write your own sentence using 「變」.","id":"g27-3"},{"t":"越…越… — The More…The More","e":"The More…The More","tgt":["越","越"],"alt":[],"s":[{"zh":"食物越簡單越好。","en":"The simpler the food, the better.","py":"shí wù yuè jiǎn dān yuè hǎo."},{"zh":"越新鮮越好。","en":"The fresher the better.","py":"yuè xīn xiān yuè hǎo."},{"zh":"越少油越健康。","en":"The less oil, the healthier.","py":"yuè shǎo yóu yuè jiàn kāng."}],"cy":"Write your own sentence using 「越」.","id":"g27-4"}],"28":[{"t":"過 — Phase Completion","e":"Phase Completion","tgt":["過"],"alt":[],"s":[{"zh":"我想過了。","en":"I've thought it through.","py":"wǒ xiǎng guò le."},{"zh":"我已經說過了。","en":"I've already said this.","py":"wǒ yǐ jīng shuō guò le."},{"zh":"這件事我們討論過了。","en":"We've already discussed this.","py":"zhè jiàn shì wǒ men tǎo lùn guò le."}],"cy":"Write your own sentence using 「過」.","id":"g28-1"},{"t":"急著 — In a Hurry To","e":"In a Hurry To","tgt":["急著"],"alt":[],"s":[{"zh":"起床就急著看手機。","en":"Wake up and immediately rush to check the phone.","py":"qǐ chuáng jiù jí zhù kàn shǒu jī."},{"zh":"一有消息就急著回。","en":"The moment there's a message, rush to reply.","py":"yī yǒu xiāo xī jiù jí zhù huí."}],"cy":"Write your own sentence using 「急著」.","id":"g28-2"},{"t":"比方說 — For Example","e":"For Example","tgt":["比方說"],"alt":[],"s":[{"zh":"比方說，起床就看手機。","en":"For example, checking your phone the moment you wake up.","py":"bǐ fāng shuō, qǐ chuáng jiù kàn shǒu jī."},{"zh":"現代人的習慣，比方說低頭族的行為。","en":"Modern habits — say, phone-zombie behavior.","py":"xiàn dài rén de xí guàn, bǐ fāng shuō dī tóu zú de xíng wéi."}],"cy":"Write your own sentence using 「比方說」.","id":"g28-3"},{"t":"做到 — To Achieve","e":"To Achieve","tgt":["做到"],"alt":[],"s":[{"zh":"你做到了！","en":"You did it!","py":"nǐ zuò dào le!"},{"zh":"很難做到。","en":"Hard to pull off.","py":"hěn nán zuò dào."},{"zh":"想做到少用手機，但是很難。","en":"I want to use my phone less, but it's hard.","py":"xiǎng zuò dào shǎo yòng shǒu jī, dàn shì hěn nán."}],"cy":"Write your own sentence using 「做到」.","id":"g28-4"}],"29":[{"t":"連…都 — Even","e":"Even","tgt":["連","都"],"alt":[],"s":[{"zh":"連聲調都不準。","en":"Even the tones aren't accurate.","py":"lián shēng diào dōu bù zhǔn."},{"zh":"連他都同意了。","en":"Even he agreed.","py":"lián tā dōu tóng yì le."},{"zh":"連這個都不會？","en":"You can't even do this?","py":"lián zhè ge dōu bú huì?"}],"cy":"Write your own sentence using 「連」.","id":"g29-1"},{"t":"不但…而且 — Not Only…But Also","e":"Not Only…But Also","tgt":["不但","而且"],"alt":[],"s":[{"zh":"中文不但可以幫助工作，而且可以了解文化。","en":"Chinese helps not only with work but with understanding culture.","py":"zhōng wén bù dàn kě yǐ bāng zhù gōng zuò, ér qiě kě yǐ liǎo jiě wén huà."},{"zh":"他不但語法好，而且發音也很準。","en":"Not only is his grammar good, his pronunciation is accurate too.","py":"tā bù dàn yǔ fǎ hǎo, ér qiě fā yīn yě hěn zhǔn."},{"zh":"不但有用，而且很有趣。","en":"Not only useful, but also fun.","py":"bù dàn yǒu yòng, ér qiě hěn yǒu qù."}],"cy":"Write your own sentence using 「不但」.","id":"g29-2"},{"t":"捨不得 — Can't Bear To","e":"Can't Bear To","tgt":["捨不得"],"alt":[],"s":[{"zh":"捨不得離開台灣。","en":"Reluctant to leave Taiwan.","py":"shě bù dé lí kāi tái wān."},{"zh":"捨不得這裡的朋友。","en":"Can't bear to leave the friends here.","py":"shě bù dé zhè lǐ de péng yǒu."},{"zh":"捨不得吃完。","en":"Too attached to finish eating it.","py":"shě bù dé chī wán."}],"cy":"Write your own sentence using 「捨不得」.","id":"g29-3"},{"t":"說到 — Speaking Of","e":"Speaking Of","tgt":["說到"],"alt":[],"s":[{"zh":"說到語法，你覺得哪個最難？","en":"Speaking of grammar, which is hardest?","py":"shuō dào yǔ fǎ, nǐ jué de nǎ ge zuì nán?"},{"zh":"說到這個，我想到一件事。","en":"Speaking of which, I just thought of something.","py":"shuō dào zhè ge, wǒ xiǎng dào yī jiàn shì."}],"cy":"Write your own sentence using 「說到」.","id":"g29-4"},{"t":"充實 — Enriching","e":"Enriching","tgt":["充實"],"alt":[],"s":[{"zh":"讀研究所可以充實自己。","en":"Grad school can enrich you.","py":"dú yán jiū suǒ kě yǐ chōng shí zì jǐ."},{"zh":"今天過得很充實。","en":"Today was a fulfilling day.","py":"jīn tiān guò dé hěn chōng shí."}],"cy":"Write your own sentence using 「充實」.","id":"g29-5"}],"30":[{"t":"起來 — Beginning of a State","e":"Beginning of a State","tgt":["起來"],"alt":[],"s":[{"zh":"過年前，街道熱鬧起來了。","en":"Before New Year, the streets came alive.","py":"guò nián qián, jiē dào rè nào qǐ lái le."},{"zh":"春節快到了，城市忙起來了。","en":"With New Year near, the city is getting busy.","py":"chūn jié kuài dào le, chéng shì máng qǐ lái le."}],"cy":"Write your own sentence using 「起來」.","id":"g30-1"},{"t":"又 — Again / Once More","e":"Again / Once More","tgt":["又"],"alt":[],"s":[{"zh":"又過了一年。","en":"Another year has passed.","py":"yòu guò le yī nián."},{"zh":"又長大了一歲。","en":"Grown one year older again.","py":"yòu zhǎng dà le yī suì."},{"zh":"大年初一，又是新的開始。","en":"New Year's Day — another fresh start.","py":"dà nián chū yī, yòu shì xīn de kāi shǐ."}],"cy":"Write your own sentence using 「又」.","id":"g30-2"}],"31":[{"id":"g31-1","t":"…的話 · if, supposing","e":"Marks the end of an “if” clause; the result follows, often with 就. It can stand alone or pair with 要是 / 如果.","pat":"Clause + 的話，(S) 就 …","tgt":["的話"],"alt":[],"s":[{"zh":"你想轉系的話，最好先跟老師談談。","py":"nǐ xiǎng zhuǎn xì de huà, zuì hǎo xiān gēn lǎo shī tán tan.","en":"If you want to change majors, you had better talk to your teacher first."},{"zh":"明天下雨的話，我們就不去爬山了。","py":"míng tiān xià yǔ de huà, wǒ men jiù bú qù pá shān le.","en":"If it rains tomorrow, we won’t go hiking."}],"cy":"Write your own sentence using 「的話」."},{"id":"g31-2","t":"不到 · less than","e":"Placed before a number or amount: the real figure falls short of it.","pat":"不到 + number / amount","tgt":["不到"],"alt":[],"s":[{"zh":"這件外套不到一千塊，真便宜。","py":"zhè jiàn wài tào bú dào yì qiān kuài, zhēn pián yí.","en":"This coat is under a thousand dollars — really cheap."},{"zh":"從我家到學校不到十分鐘。","py":"cóng wǒ jiā dào xué xiào bú dào shí fēn zhōng.","en":"It takes less than ten minutes from my place to school."}],"cy":"Write your own sentence using 「不到」."},{"id":"g31-3","t":"差一點（就）… · almost","e":"Something nearly happened but did not — usually something you are glad to have avoided. 就 is optional.","pat":"S + 差一點（就）+ V","tgt":["差一點"],"alt":[],"s":[{"zh":"我今天起得太晚，差一點遲到。","py":"wǒ jīn tiān qǐ de tài wǎn, chà yì diǎn chí dào.","en":"I got up too late today and was almost late."},{"zh":"他差一點就忘了帶成績單。","py":"tā chà yì diǎn jiù wàng le dài chéng jī dān.","en":"He very nearly forgot to bring his transcript."}],"cy":"Write your own sentence using 「差一點」."},{"id":"g31-4","t":"恐怕… · I’m afraid that, probably","e":"An adverb for the speaker’s guess that something — usually unwelcome — is likely.","pat":"(S) 恐怕 + clause","tgt":["恐怕"],"alt":[],"s":[{"zh":"你每天熬夜，恐怕會影響成績。","py":"nǐ měi tiān áo yè, kǒng pà huì yǐng xiǎng chéng jī.","en":"You stay up late every night; I’m afraid it will affect your grades."},{"zh":"現在才出門，恐怕來不及了。","py":"xiàn zài cái chū mén, kǒng pà lái bù jí le.","en":"Leaving only now, we probably won’t make it."}],"cy":"Write your own sentence using 「恐怕」."},{"id":"g31-5","t":"好不容易 · finally managed to","e":"A good result reached only after real effort or a long wait; often followed by 才.","pat":"S + 好不容易 + (才) + V","tgt":["好不容易"],"alt":[],"s":[{"zh":"他好不容易才考上理想的大學。","py":"tā hǎo bù róng yì cái kǎo shàng lǐ xiǎng de dà xué.","en":"After a lot of effort he finally got into the university he wanted."},{"zh":"我好不容易寫完了口頭報告。","py":"wǒ hǎo bù róng yì xiě wán le kǒu tóu bào gào.","en":"I finally managed to finish writing my oral report."}],"cy":"Write your own sentence using 「好不容易」."},{"id":"g31-6","t":"說…就… · just like that, without warning","e":"The same verb goes in both slots: the thing happens at once, sooner than anyone expected.","pat":"說 + V + 就 + V","tgt":["說變就變","說走就走"],"alt":[],"s":[{"zh":"台北的天氣說變就變，出門最好帶傘。","py":"tái běi de tiān qì shuō biàn jiù biàn, chū mén zuì hǎo dài sǎn.","en":"Taipei’s weather changes just like that; better take an umbrella when you go out."},{"zh":"他沒告訴大家，說走就走了。","py":"tā méi gào sù dà jiā, shuō zǒu jiù zǒu le.","en":"He didn’t tell anyone — he just up and left."}],"cy":"Write your own sentence using 「說變就變」."},{"id":"g31-7","t":"不管…都… · no matter, regardless","e":"Whatever the condition after 不管 (a question form or A-not-A), the result after 都 stays the same.","pat":"不管 + question form，S + 都 …","tgt":["不管"],"alt":[],"s":[{"zh":"不管功課多不多，他每天都去運動。","py":"bù guǎn gōng kè duō bù duō, tā měi tiān dōu qù yùn dòng.","en":"Whether or not he has a lot of homework, he exercises every day."},{"zh":"不管父母反對不反對，她都要念會計系。","py":"bù guǎn fù mǔ fǎn duì bù fǎn duì, tā dōu yào niàn kuài jì xì.","en":"Whether her parents object or not, she is going to study accounting."}],"cy":"Write your own sentence using 「不管」."}],"32":[{"id":"g32-1","t":"一般來說 · generally speaking","e":"Opens a sentence that describes the usual case rather than every case.","pat":"一般來說，clause","tgt":["一般來說"],"alt":[],"s":[{"zh":"一般來說，週年慶的時候折扣最多。","py":"yì bān lái shuō, zhōu nián qìng de shí hòu zhé kòu zuì duō.","en":"Generally speaking, discounts are biggest during anniversary sales."},{"zh":"一般來說，百貨公司的東西比較貴。","py":"yì bān lái shuō, bǎi huò gōng sī de dōng xi bǐ jiào guì.","en":"Generally speaking, things in department stores cost more."}],"cy":"Write your own sentence using 「一般來說」."},{"id":"g32-2","t":"弄 · the all-purpose verb","e":"Stands in for a more specific action, especially with a result: 弄丟 lose, 弄壞 break, 弄錯 get wrong, 弄乾淨 clean up.","pat":"(把 + O) + 弄 + result","tgt":["弄"],"alt":[],"s":[{"zh":"對不起，我把你的發票弄丟了。","py":"duì bù qǐ, wǒ bǎ nǐ de fā piào nòng diū le.","en":"Sorry, I lost your receipt."},{"zh":"弟弟把我的手機弄壞了。","py":"dì di bǎ wǒ de shǒu jī nòng huài le.","en":"My little brother broke my phone."}],"cy":"Write your own sentence using 「弄」."},{"id":"g32-3","t":"再說 · besides, moreover","e":"Adds one more reason on top of what was just said.","pat":"Reason 1。再說，reason 2。","tgt":["再說"],"alt":[],"s":[{"zh":"這件外套太短了，再說，我也沒帶那麼多現金。","py":"zhè jiàn wài tào tài duǎn le, zài shuō, wǒ yě méi dài nà me duō xiàn jīn.","en":"This coat is too short; besides, I didn’t bring that much cash."},{"zh":"我不想去，那裡太遠，再說，明天還有口試。","py":"wǒ bù xiǎng qù, nà lǐ tài yuǎn, zài shuō, míng tiān hái yǒu kǒu shì.","en":"I don’t want to go: it’s too far, and besides, there’s an oral exam tomorrow."}],"cy":"Write your own sentence using 「再說」."},{"id":"g32-4","t":"V + 成 · to turn into, to become","e":"After a verb, 成 names what the object ends up as.","pat":"把 + O + V + 成 + new form","tgt":["成"],"alt":[],"s":[{"zh":"請你幫我把這封信翻譯成英文。","py":"qǐng nǐ bāng wǒ bǎ zhè fēng xìn fān yì chéng yīng wén.","en":"Please help me translate this letter into English."},{"zh":"我想把月租型換成預付卡。","py":"wǒ xiǎng bǎ yuè zū xíng huàn chéng yù fù kǎ.","en":"I’d like to switch from a monthly plan to a prepaid card."}],"cy":"Write your own sentence using 「成」."},{"id":"g32-5","t":"並 + 不 / 沒 · contrary to what you might think","e":"Strengthens a negative to correct an assumption: it is not, in fact, so.","pat":"S + 並 + 不 / 沒（有）…","tgt":["並"],"alt":[],"s":[{"zh":"這個牌子很有名，可是品質並不好。","py":"zhè ge pái zi hěn yǒu míng, kě shì pǐn zhí bìng bù hǎo.","en":"This brand is famous, but the quality actually isn’t good."},{"zh":"店員說打了折，可是價錢並沒有比較便宜。","py":"diàn yuán shuō dǎ le zhé, kě shì jià qián bìng méi yǒu bǐ jiào pián yí.","en":"The clerk said it was discounted, but the price isn’t actually any lower."}],"cy":"Write your own sentence using 「並」."},{"id":"g32-6","t":"尤其是 · especially","e":"Picks out the one case to which a general statement applies most; comes in the second half of the sentence.","pat":"General statement，尤其是 + N","tgt":["尤其是"],"alt":[],"s":[{"zh":"我喜歡台灣的小吃，尤其是水煎包。","py":"wǒ xǐ huān tái wān de xiǎo chī, yóu qí shì shuǐ jiān bāo.","en":"I like Taiwanese snacks, especially pan-fried buns."},{"zh":"冬天的衣服都不便宜，尤其是羊毛外套。","py":"dōng tiān de yī fú dōu bù pián yí, yóu qí shì yáng máo wài tào.","en":"Winter clothes are never cheap, especially wool coats."}],"cy":"Write your own sentence using 「尤其是」."},{"id":"g32-7","t":"只好 · have no choice but to","e":"With no better option left, the speaker settles for this one.","pat":"Situation，S + 只好 + V","tgt":["只好"],"alt":[],"s":[{"zh":"我沒帶現金，只好刷卡。","py":"wǒ méi dài xiàn jīn, zhǐ hǎo shuā kǎ.","en":"I didn’t bring cash, so I had to pay by card."},{"zh":"手機壞了，他只好拿去門市修理。","py":"shǒu jī huài le, tā zhǐ hǎo ná qù mén shì xiū lǐ.","en":"His phone broke, so he had no choice but to take it to the shop for repair."}],"cy":"Write your own sentence using 「只好」."}],"33":[{"id":"g33-1","t":"受到（…的）影響 · to be influenced by","e":"The subject is on the receiving end; the source of the influence sits between 受到 and 的影響.","pat":"S + 受到 + source + 的影響","tgt":["受到"],"alt":[],"s":[{"zh":"他受到哥哥的影響，也開始學中文。","py":"tā shòu dào gē ge de yǐng xiǎng, yě kāi shǐ xué zhōng wén.","en":"Influenced by his older brother, he started learning Chinese too."},{"zh":"受到天氣的影響，今天的校外教學改天再去。","py":"shòu dào tiān qì de yǐng xiǎng, jīn tiān de xiào wài jiào xué gǎi tiān zài qù.","en":"Because of the weather, today’s field trip will happen another day."}],"cy":"Write your own sentence using 「受到」."},{"id":"g33-2","t":"幸虧… · fortunately, luckily","e":"Introduces the lucky fact that prevented a bad outcome; 要不然 or 才 often follows.","pat":"幸虧 + clause，(要不然 …)","tgt":["幸虧"],"alt":[],"s":[{"zh":"幸虧你提醒我，要不然我就遲到了。","py":"xìng kuī nǐ tí xǐng wǒ, yào bù rán wǒ jiù chí dào le.","en":"Luckily you reminded me; otherwise I would have been late."},{"zh":"外面下大雨，幸虧我帶了傘。","py":"wài miàn xià dà yǔ, xìng kuī wǒ dài le sǎn.","en":"It’s pouring outside — good thing I brought an umbrella."}],"cy":"Write your own sentence using 「幸虧」."},{"id":"g33-3","t":"算是… · can be considered","e":"A judgment by comparison: measured against similar things, the subject counts as this.","pat":"S + 算是 + description","tgt":["算是"],"alt":[],"s":[{"zh":"台北的冬天算是暖和的。","py":"tái běi de dōng tiān suàn shì nuǎn huo de.","en":"Taipei’s winters count as mild."},{"zh":"這家店的海鮮算是很新鮮的。","py":"zhè jiā diàn de hǎi xiān suàn shì hěn xīn xiān de.","en":"This shop’s seafood can be considered very fresh."}],"cy":"Write your own sentence using 「算是」."},{"id":"g33-4","t":"是… · it is true that … (but)","e":"Unstressed 是 concedes the point just made, and a “but” usually follows with the speaker’s real view.","pat":"S + 是 + description，可是 / 不過 …","tgt":["是很"],"alt":[],"s":[{"zh":"火鍋是很好吃，可是夏天吃太熱了。","py":"huǒ guō shì hěn hǎo chī, kě shì xià tiān chī tài rè le.","en":"Hot pot is delicious, true, but it’s too hot to eat in summer."},{"zh":"這台除濕機是很貴，不過很好用。","py":"zhè tái chú shī jī shì hěn guì, bú guò hěn hǎo yòng.","en":"This dehumidifier is expensive, yes, but it works really well."}],"cy":"Write your own sentence using 「是很」."},{"id":"g33-5","t":"難怪 · no wonder","e":"A new fact explains something that had puzzled the speaker; 難怪 opens the clause that now makes sense.","pat":"New fact，難怪 + what is now explained","tgt":["難怪"],"alt":[],"s":[{"zh":"原來你在荷蘭住過，難怪你不怕冷。","py":"yuán lái nǐ zài hé lán zhù guò, nán guài nǐ bú pà lěng.","en":"So you used to live in the Netherlands — no wonder the cold doesn’t bother you."},{"zh":"今天零下兩度，難怪大家都穿得那麼多。","py":"jīn tiān líng xià liǎng dù, nán guài dà jiā dōu chuān de nà me duō.","en":"It’s two below zero today; no wonder everyone is so bundled up."}],"cy":"Write your own sentence using 「難怪」."},{"id":"g33-6","t":"…死了 · extremely, to death","e":"Attached to a state, it pushes it to the extreme; mostly for complaining.","pat":"Vs + 死了","tgt":["死了"],"alt":[],"s":[{"zh":"走了一天的路，我累死了。","py":"zǒu le yì tiān de lù, wǒ lèi sǐ le.","en":"After walking all day, I’m dead tired."},{"zh":"今天又悶又熱，難受死了。","py":"jīn tiān yòu mēn yòu rè, nán shòu sǐ le.","en":"It’s muggy and hot today — unbearable."}],"cy":"Write your own sentence using 「死了」."},{"id":"g33-7","t":"幾乎 · almost, nearly","e":"Very close to all, every, or completely.","pat":"S + 幾乎 + (都 / 每 / 沒) …","tgt":["幾乎"],"alt":[],"s":[{"zh":"雨季的時候，這裡幾乎天天下雨。","py":"yǔ jì de shí hòu, zhè lǐ jī hū tiān tiān xià yǔ.","en":"In the rainy season it rains here almost every day."},{"zh":"他說的話我幾乎都聽不懂。","py":"tā shuō de huà wǒ jī hū dōu tīng bù dǒng.","en":"I can hardly understand anything he says."}],"cy":"Write your own sentence using 「幾乎」."},{"id":"g33-8","t":"多少 · somewhat, at least a little","e":"As an adverb: some amount, even if small. Often with 一點 or 一些.","pat":"S + 多少 + V + (一點)","tgt":["多少"],"alt":[],"s":[{"zh":"過節的時候，大家多少會買一點禮物。","py":"guò jié de shí hòu, dà jiā duō shǎo huì mǎi yì diǎn lǐ wù.","en":"At festival time everyone buys at least a few gifts."},{"zh":"我在台灣住了一年，台語多少聽得懂一點。","py":"wǒ zài tái wān zhù le yì nián, tái yǔ duō shǎo tīng de dǒng yì diǎn.","en":"After a year in Taiwan I can understand at least a little Taiwanese."}],"cy":"Write your own sentence using 「多少」."},{"id":"g33-9","t":"再…也… · no matter how …, still …","e":"However far the condition after 再 goes, the result after 也 does not change.","pat":"S + 再 + Vs + 也 + V","tgt":["再忙","再貴"],"alt":[],"s":[{"zh":"我再忙也要回家跟家人團聚。","py":"wǒ zài máng yě yào huí jiā gēn jiā rén tuán jù.","en":"However busy I am, I’ll still go home to be with my family."},{"zh":"那家店的月餅再貴也有人買。","py":"nà jiā diàn de yuè bǐng zài guì yě yǒu rén mǎi.","en":"However expensive that shop’s mooncakes get, people still buy them."}],"cy":"Write your own sentence using 「再忙」."}],"34":[{"id":"g34-1","t":"不但…，還… · not only … but also","e":"Gives two facts about the same subject; the second adds to the first.","pat":"S + 不但 + A，還 + B","tgt":["不但"],"alt":[],"s":[{"zh":"這家店的雞排不但便宜，還很好吃。","py":"zhè jiā diàn de jī pái bú dàn pián yí, hái hěn hǎo chī.","en":"This place’s fried chicken cutlet is not only cheap but also delicious."},{"zh":"他不但會說中文，還會寫書法。","py":"tā bú dàn huì shuō zhōng wén, hái huì xiě shū fǎ.","en":"He can not only speak Chinese but also write calligraphy."}],"cy":"Write your own sentence using 「不但」."},{"id":"g34-2","t":"說 vs 談 · to say vs to talk over","e":"說 reports words or facts, one way. 談 is two-way: discussing a topic with someone.","pat":"說 + what was said · 跟 + person + 談 + topic","tgt":["談"],"alt":[],"s":[{"zh":"我想跟你談一談轉系的事。","py":"wǒ xiǎng gēn nǐ tán yì tán zhuǎn xì de shì.","en":"I’d like to talk with you about changing majors."},{"zh":"老師說明天不用上課，我們可以再談這個問題。","py":"lǎo shī shuō míng tiān bú yòng shàng kè, wǒ men kě yǐ zài tán zhè ge wèn tí.","en":"The teacher said there’s no class tomorrow, so we can discuss this question again then."}],"cy":"Write your own sentence using 「談」."},{"id":"g34-3","t":"…不是…，而是… · not …, but rather …","e":"Rejects one explanation and puts the right one in its place.","pat":"S + 不是 + A，而是 + B","tgt":["而是"],"alt":[],"s":[{"zh":"他不是不喜歡吃辣，而是今天不舒服。","py":"tā bú shì bù xǐ huān chī là, ér shì jīn tiān bù shū fú.","en":"It’s not that he dislikes spicy food; he just isn’t feeling well today."},{"zh":"這不是紅茶，而是烏龍茶。","py":"zhè bú shì hóng chá, ér shì wū lóng chá.","en":"This isn’t black tea; it’s oolong."}],"cy":"Write your own sentence using 「而是」."},{"id":"g34-4","t":"從來 + 不 / 沒 · never","e":"從來沒 + V + 過: has never happened so far. 從來不 + V: as a rule, never does.","pat":"S + 從來 + 沒 + V + 過 · S + 從來 + 不 + V","tgt":["從來"],"alt":[],"s":[{"zh":"我從來沒放過天燈。","py":"wǒ cóng lái méi fàng guò tiān dēng.","en":"I have never released a sky lantern."},{"zh":"她從來不熬夜。","py":"tā cóng lái bù áo yè.","en":"She never stays up late."}],"cy":"Write your own sentence using 「從來」."},{"id":"g34-5","t":"上 · many meanings of one verb","e":"Beyond “go up”: go to (a place or activity), start a shift or class, get on, be served, appear on. Each use is learned with its noun.","pat":"上 + place / activity","tgt":["上"],"alt":[],"s":[{"zh":"週末我們上山看夜景吧。","py":"zhōu mò wǒ men shàng shān kàn yè jǐng ba.","en":"Let’s go up the mountain this weekend to see the night view."},{"zh":"他每天早上八點上班。","py":"tā měi tiān zǎo shàng bā diǎn shàng bān.","en":"He starts work at eight every morning."}],"cy":"Write your own sentence using 「上」."},{"id":"g34-6","t":"非…不可 · absolutely must","e":"A double negative for necessity or determination: nothing else will do.","pat":"S + 非 + V + 不可","tgt":["不可"],"alt":[],"s":[{"zh":"聽說那家擔仔麵很道地，我非去吃不可。","py":"tīng shuō nà jiā dàn zǎi miàn hěn dào dì, wǒ fēi qù chī bù kě.","en":"I hear that place’s danzai noodles are the real thing — I simply have to go and try them."},{"zh":"明天的口試很重要，你非來不可。","py":"míng tiān de kǒu shì hěn zhòng yào, nǐ fēi lái bù kě.","en":"Tomorrow’s oral exam matters; you absolutely have to come."}],"cy":"Write your own sentence using 「不可」."},{"id":"g34-7","t":"對…來說 · as far as … is concerned","e":"Frames a statement from one person’s or group’s point of view.","pat":"對 + person / group + 來說，clause","tgt":["來說"],"alt":[],"s":[{"zh":"對外國學生來說，寫漢字很不容易。","py":"duì wài guó xué shēng lái shuō, xiě hàn zì hěn bù róng yì.","en":"For foreign students, writing Chinese characters is not easy."},{"zh":"對我來說，人情味是台灣最美的風景。","py":"duì wǒ lái shuō, rén qíng wèi shì tái wān zuì měi de fēng jǐng.","en":"To me, the warmth of the people is the most beautiful thing about Taiwan."}],"cy":"Write your own sentence using 「來說」."},{"id":"g34-8","t":"對…講究 · to be particular about","e":"Someone has high standards about something and pays attention to its details.","pat":"S + 對 + N + (很 / 不) 講究","tgt":["講究"],"alt":[],"s":[{"zh":"台南人對吃很講究。","py":"tái nán rén duì chī hěn jiǎng jiù.","en":"People in Tainan are very particular about food."},{"zh":"他對穿的衣服不太講究。","py":"tā duì chuān de yī fú bú tài jiǎng jiù.","en":"He isn’t very fussy about what he wears."}],"cy":"Write your own sentence using 「講究」."}]};
